pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 9) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Gap cannot host the next item: mild penalty scaled by how close it is.
            score += 4.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading, favor filling.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins with residuals near the mean (balanced packing),
    // but only mildly so tight fits still dominate.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Early in the stream, be more willing to open fresh bins (cheap now,
    // useful later); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: acceptable early, costly later; baseline so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 0.2 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 5.0; // fresh bin always fits the lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (waste), reward moderate leftovers that stay usable.
    if post_residual > 0 {
        let usable = post_residual as f64 / bin_capacity as f64;
        if usable < 0.10 {
            score += 60.0 * (0.10 - usable) / 0.10;
        } else {
            score -= 10.0 * usable;
        }
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
        // Extra bonus if leftover fits next item almost exactly.
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize proportionally to wasted potential.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let congestion = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).min(20.0);
    score += 2.0 * congestion * (0.5 + progress);

    // Fullness reward: the tighter the fit relative to residual, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // New-bin candidate handling: only attractive when open bins are crowded or residual is poor.
    if bin_residual == bin_capacity {
        let good_reason = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.5 && open_bins_count > 0)
            || (next_item_size > 0 && next_item_size > mean_residual);
        if good_reason {
            score -= 90.0 * (0.3 + progress);
        } else {
            score += 150.0; // discourage scattering into new bins
        }
    }

    // Late in stream: consolidate aggressively, keep mean residual low.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 20.0 * (bin_residual as f64 - mean_residual).max(0.0) / 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress + 0.6 * progress * progress;
    score *= poly;

    // Penalize large dead space more than linearly (quadratic term)
    score += 4.0 * norm_pr * norm_pr * cap;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward leaving room for the next item
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (pr - n).abs();
        score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        if pr >= n {
            score -= 12.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += 0.05 * open_bins_count as f64 * norm_pr * cap;

    // Deviation from mean residual: prefer bins whose residual stays near the mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // New-bin candidate: neutral baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * progress - 0.15 * n;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 20.0 {
        score += 150.0; // unusable tiny gap
    }

    // Non-linear penalty on small post residuals that no plausible item can use.
    if post_residual > 0 {
        let gap = post_residual as f64;
        score += (30.0 / gap).powf(1.5) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward using bins that would otherwise be near-closed (tight fits).
    if (post_residual as f64) < mean_residual {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor filling it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 6.0 * (0.5 + progress);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 40.0; // blocks the next item
        }
    }

    // Prefer keeping large residuals for large future items.
    if next_item_size > item_size && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 30.0;
    }

    // Mild preference for fuller bins (low post residual overall).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: only attractive when it enables a clean fit for the lookahead item.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        } else {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact-fill and lookahead structure (borrowed from best-known).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score += 3.2 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
        }
    }

    // Perfect fill: huge reward.
    if post_residual == 0 {
        score -= 180.0;
    }

    // Penalize creating unusable slivers.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(30) {
        score += 6.0;
        let rel = next_item_size as f64 / cap;
        score += (2.4 + 1.2 * rel) * post_residual as f64;
    }

    // Early-stream: prefer bins leaving moderately reusable residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual != next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Consolidation pressure: mild penalty per open bin.
    score += 0.06 * (bin_capacity - bin_residual) as f64;
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate handling: attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        let mean_tight = mean_residual / cap;
        let openness = 8.0 * (1.0 - mean_tight) - 6.0 * progress;
        score = 30.0 - scarcity - openness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Late-stream: waste matters more.
    score += 2.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize leaving residual that is too small for the next item (dead space risk),
        // scaled by how close the dead space is to the smallest useful size.
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means we are compacting this bin better than typical.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize the brand-new empty bin candidate, but relax it late in the stream
    // or when many bins are open (diversification can help).
    if bin_residual == bin_capacity {
        score += 150.0 - 30.0 * (open_bins_count as f64).sqrt();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Mild penalty for very large wasted residual relative to capacity.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range gaps (10..=25) are mildly wasteful too.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.8 * (post_residual as f64 - 9.0);
    }
    // Perfect or near-perfect fits rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            } else if gap < 10 {
                score += 3.0;
            }
        } else {
            // Next item cannot use residual: residual becomes dead space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than average (good fits relative to fleet state).
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening new bin is fine if it's the only option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Post-residual exactly fits the lookahead item: reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post-residual too small for the next item but not dead-space small: mild penalty.
    if next_item_size > 0 && post_residual >= 10 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: acceptable only when this bin wastes a lot.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score = 80.0 + 0.4 * waste;
        if fitting_bins_count == 1 {
            score += 120.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Mild stream-progression drift: later items favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // treat gaps below the minimum possible item size as pure waste
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap);
        } else {
            // penalize gaps that no plausible next item can use well
            let usable = if (next_item_size > 0 && gap >= next_item_size as f64) || gap >= 10.0 { 1.0 } else { 0.0 };
            if usable < 1.0 {
                score += 40.0;
            }
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover; slight penalty
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading items across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins deviating from mean toward tighter fill.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.9 * open_bins_count as f64 - 0.5 * mean_residual;
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        if next_item_size - post_residual <= 6 {
            score += 5.0 * (1.0 - progress);
        }
        // MUTATION: relative dead-space penalty scaled by item size share
        let rel_dead = (next_item_size - post_residual) as f64 / next.max(1.0);
        score += 3.0 * rel_dead * (1.0 - progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // MUTATION: penalize slack relative to mean residual more broadly
            // (target the dead-space ratio weakness)
