        }
    }

    // Fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable
    // since future items are >= 1..100, but tiny gaps rarely fit anything useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64); // heavy penalty for tiny gaps
    }
    // Perfect fit is the best possible outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer placing into the emptiest bin (largest residual) to consolidate space.
    score -= 0.3 * bin_residual as f64;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer new bin less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits inside post residual, mild reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        score -= 8.0;
    }
    // If post residual is smaller than next item but nonzero, penalize (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate baseline: opening a new bin should only win when placement
    // here is bad (large dead space) or bins are already tight/fragmented.
    if bin_residual == bin_capacity {
        score = 20.0 + 0.4 * mean_residual - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes
    // modulo common item-size divisors of capacity (10, 20, 25, 50).
    let pr = post_residual;
    let harmonic_penalty: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 50 == 0 {
        -12.0 // residual reusable by half-capacity classes
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 20 == 0 {
        -4.0
    } else if pr % 10 == 0 {
        -2.0
    } else if pr < 10 {
        25.0 // tiny dead space: unusable sliver, heavy penalty
    } else {
        0.0
    };
    score += harmonic_penalty;

    // Lookahead: reward if the next item can also fit into the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + 0.25 * (pr - next_item_size) as f64;
        } else {
            // next item won't chain here; penalize proportionally to wasted potential
            score += 5.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // cheaper to open a new bin when many bins are open and mean residual is small
        score -= 0.5 * open_bins_count as f64;
        score -= 0.3 * mean_residual;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 15.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference for tighter fits: closeness of item to residual
    score += 0.1 * (bin_residual - item_size) as f64 / cap * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
