pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear waste penalty: squared residual scaled by stream progress
    score += 0.35 * (pr / cap) * (pr / cap) * (0.5 + progress) * cap;

    // Perfect-fit reward (smooth via exponential)
    score -= 30.0 * (-(pr / 8.0)).exp();

