    // but reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 8.0 * (1.0 - progress) * ((nx - pr) / cap) * cap;
        } else {
            score -= 6.0 * (-( (pr - nx) / 10.0 )).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild preference for tighter bins relative to the fleet mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and more so when other bins could fit the item.
    if bin_residual == bin_capacity {
        score += cap * (0.9 - 0.4 * progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Slight consolidation pressure when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

