pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong preference for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual remains useful for the next item: reward.
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        } else {
            // Residual is dead space relative to lookahead: penalize proportionally.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * dead;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Cost of opening a new bin, modulated by stream position.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 + 20.0 * (1.0 - progress);
        // Cheaper to open a bin when many open bins already exist (spread risk),
        // expensive early in the stream with few bins.
        new_bin_cost -= 0.5 * open_bins_count as f64;
        // If the item is large relative to capacity, opening a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            new_bin_cost -= 10.0;
        }
        // If mean residual is large, open bins have room; discourage new bin.
        new_bin_cost += 0.15 * mean_residual;
        score += new_bin_cost;
    }

    // Mild global pressure: when mean residual is low, conserve space (tighten fits).
    score += 0.05 * mean_residual;

    // Nonlinear coupling: quadratic penalty on medium-size waste chunks.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Slight time decay: later in the stream, prioritize exact packing more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized non-linearly by wasted space.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; later, dead space becomes costly.
    let coupling = 1.0 + progress * progress * (2.5 + 3.0 * (1.0 - norm_pr));
    score *= coupling;

    // Cross term: post_residual scaled by progress polynomially.
    score += 20.0 * progress * (1.0 - progress) * norm_pr * (1.0 - norm_pr);

    // Reward bins whose leftover could still host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference for consolidating into fewer bins when residuals cluster.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, slightly worse late in stream.
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.0 + 0.5 * progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let pr = post_residual;
    let band = pr / (bin_capacity / 10); // 0..10 integer division threshold
    let band_bonus: f64 = match band {
        0 => -30.0,                 // near-perfect fill
        1 => -22.0,                 // excellent
        2 => -14.0,                 // good
        3 => -6.0,
        4 => 0.0,
        5 => 4.0,
        6 => 8.0,
        7 => 12.0,
        8 => 16.0,
        _ => 20.0,                  // large dead space
    };
    score += band_bonus;

    // Harmonic divisibility: if post_residual is a multiple of common item sizes,
    // the leftover is reusable — reward it.
    if pr > 0 {
        let mut harmonic = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                harmonic += 6.0;
            }
        }
        score -= harmonic;
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= pr {
            score -= 12.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; residual becomes dead space
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // existing bins. Penalize unless this is the last chance or existing fits are poor.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else if fitting_bins_count == 1 { 60.0 } else { 25.0 };
        // small items leave huge residuals in fresh bins early on
        let waste = (100.0 - item_size as f64) * 0.3;
        score += 45.0 + urgency + waste * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer fuller bins overall: compare residual to mean residual of open bins.
    score += ((bin_residual as f64) - mean_residual) * 0.25;

    // Mild preference to spread across fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // future item (min size 1..=100, unknown distribution) are wasted.
    // Penalize gaps that are "small but not zero" hardest.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // A gap is "dead" if it's below a plausible minimum item footprint.
        let dead_threshold = 10.0f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 6.0; // near-full but useless gap
        }
        // General convex dead-space penalty: quadratic growth of waste.
        score += (pr / bin_capacity as f64).powi(3) * 40.0;
    } else {
        score -= 25.0; // perfect fill: strongly reward
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.05 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bin is cheaper.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a fresh canvas. Only
    // attractive when existing bins would leave bad dead space or no
    // open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad the best
        // existing option is (proxy: mean residual vs item size).
        let mean_gap = mean_residual - item_size as f64;
        let fit_quality = if mean_gap > 0.0 { (mean_gap / bin_capacity as f64).clamp(0.0, 1.0) } else { 1.0 };
        score += 30.0 - 25.0 * fit_quality;
        // Late in the stream, opening new bins is riskier (less chance to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64 / 100.0) * 10.0;
        }
    }

    // Lookahead coupling: if the post residual exactly accommodates the
    // next item, this placement is chain-efficient.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // gap breaks the chain
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core),
    // scaled by distance from mean residual to break ties.
    score -= (bin_residual as f64 - item_size as f64).max(0.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: small post_residual (tight fit).
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0));

    // 2-step lookahead: perfect match if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain a perfect follow-up placement
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill; // next item fits well in the leftover
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap; // next item cannot use this leftover
        }
    } else {
        // Last item: minimize waste fully.
        score += 2.0 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (consolidate near-full bins), penalize using roomy bins for small items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, mildly prefer tighter fits among them.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).log2();
    }

    // Penalize creating very small dead space that nothing (min size 1..100)
    // can later use well, especially early in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins; prefer reusing existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: penalize unless current bins are crowded
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin useful for a large incoming pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: bonus if the next item can also fit in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // Penalize if next item barely misses, creating likely dead space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(10) {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fit = mean_residual / bin_capacity as f64;
        // New bins get worse as stream progresses or when open bins still have room.
        score += 45.0 + 40.0 * progress + 30.0 * (1.0 - mean_fit);
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early stream: new bins are cheaper.
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving residuals that no typical small item (1..=10) can use.
    if post_residual > 0 && post_residual < 11 {
        score += 3.0;
    }

    // Slight preference to spread load when many bins are open (balance residuals).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Penalize large residuals more strongly as stream progresses
    score += progress * norm_pr * norm_pr * 60.0;

    // Reward tight fits, amplified by progress
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 15.0 * (1.0 - (gap / cap).powf(2.0));
        } else {
            score += 20.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: prefer it only when open bins are quite full
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 30.0 - 55.0 * mean_norm * (1.0 + progress);
    } else {
        // Prefer bins below mean residual (fill emptier bins first)
        let dev = (pr - mean_residual) / cap;
        score += 8.0 * dev * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // granularity classes (5,10,25,50) are more reusable.
    let pr = post_residual as u32;
    let divis_bonus: f64 = if pr == 0 {
        -30.0
    } else {
        let mut b = 0.0;
        if pr % 5 == 0 { b -= 3.0; }
        if pr % 10 == 0 { b -= 4.0; }
        if pr % 25 == 0 { b -= 5.0; }
        if pr % 50 == 0 { b -= 6.0; }
        b
    };
    score += divis_bonus;

    // Integer-division threshold: small post_residual is dead space unless it
    // exactly matches the lookahead item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // lookahead fits exactly
        } else if post_residual >= next_item_size {
            // how well the lookahead item's harmonic class aligns
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.25;
            if next_item_size % 10 == 0 && post_residual % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0; // lookahead can't use this bin
        }
    } else {
        // last item: prefer zero residual strongly
        score += (post_residual as f64) * 0.5;
    }

    // Fraction-of-capacity class of post residual
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.1 {
        score += 12.0; // tiny unusable sliver
    } else if frac >= 0.1 && frac < 0.3 {
        score += 4.0;
    } else if frac >= 0.5 {
        score -= 5.0; // roomy bin stays flexible
    }

    // Last-chance bin: strongly favor using it when it fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // fit is poor (high post residual) and many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1 - item/cap
        score += 25.0 - poor_fit * 20.0; // big items (small residual) open bins more freely
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (1.0 - progress); // early stream: keep bins open, consolidate
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin fits lookahead perfectly
        }
    }

    // Mean residual coupling: if this bin's post residual is far below the
    // mean, we are creating imbalance; reward equalizing residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small but nonzero gaps are unusable by
    // typical items (min size 1..100 stream, but residual < ~10 is near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // tiny gaps penalized hardest
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: dead space penalty
        score += 20.0;
    }

    // Open-bin pressure: prefer spreading load when many bins open,
    // prefer consolidating when few are open.
    score += open_bins_count as f64 * 1.5;
    score -= mean_residual * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., current bin would leave a dead gap) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && post_residual < 10 {
            score -= 80.0; // open fresh bin rather than create dead space
        } else {
            score += 50.0 + progress * 30.0; // otherwise prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect chain: this bin's leftover exactly fits the next item
            score -= 60.0;
        } else if diff > 0 && (diff as u32) < next_item_size {
            // Leftover still usable for a smaller next item
            score -= 25.0 * (1.0 - diff as f64 / next_item_size as f64);
        } else {
            // Leftover too small or overshoots: penalize proportionally to dead space
            let dead = if diff < 0 { -diff } else { diff };
            score += (dead as f64).min(40.0);
        }
    } else {
        // Last item: just minimize waste
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean residual shaping: prefer bins tighter than the mean
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize new-bin opening unless all alternatives are bad:
    // an empty bin has high raw residual; add extra penalty scaled by how
    // many open bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * fitting_bins_count as f64;
        // But if the item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mild stream-progress term: early on, keep bins open loosely;
    // later, consolidate aggressively (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.4 * progress;

    // Slight preference to fill bins among many open bins (reduce bin count)
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
