    let mut score = post;

    // Relative fill ratio reward: the fuller the bin becomes, the better
    let fill = 1.0 - (post / cap);
    score -= 12.0 * fill * fill;

    // Penalize dead space: post-residual that is too small to hold any plausible item
    // (items can be as small as 1, but small leftovers fragment capacity)
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * 2.5 } else { 0.0 };
    score += dead;

    // Perfect fit bonus
    if post == 0.0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.15 * residual;
    }

    // Crowding: many open bins -> consolidate into existing bins
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowd * (post / cap);

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps open bins homogeneous, easier to pack later)
    let dev = (residual - mean_residual).abs();
    score += 0.08 * dev;

    // Lookahead (k=2): reward leaving a residual that exactly fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if post >= nxt {
            // residual can host next item: mild reward scaled by how much slack remains
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            // residual too small for next item: mild penalty for stranding
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Time horizon: early in the stream, be more selective (higher scores for loose fits);
    // late in the stream, just close bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a baseline cost that tight fits
    // in existing bins will beat, but poor fits will not.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item + 3.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

