    let mut score = pr * (1.0 - 0.3 * progress);

    // Non-linear penalty for awkward dead space: quadratic in normalized post residual
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with cubic discount
    score -= (1.0 - pr_norm).powi(3) * 20.0;

    // Penalize bins far from mean residual (fragmentation signal)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: reward leaving space for next item, penalize blocking it
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (ns / cap);
