    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Mid-band waste suppression when late
    if progress > 0.4 && pr_norm > 0.05 && pr_norm < 0.25 {
        score += 1.6 * (1.0 - progress) * (0.25 - pr_norm) * 10.0;
    }

