            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual can host next item twice
            if post_residual >= 2.0 * nis && slack > 20.0 {
                score -= 3.0 * (1.0 - progress);
            }
        } else {
            let gap = (nis - pr);
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: can't even host half of next item — worse
            if pr < 0.6 * nis {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * nis));
            } else if pr > nis / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are still valuable
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Loose fit with many competitors
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / nis * 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            if nis > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
                // Pressure valve: many open bins with low fill → new bin is fine
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score -= 5.0 * (0.18 - avg_fill) * 10.0;
                }
                if open_bins_count > 6 && progress > 0.6 {
                    score -= 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible item are heavily penalized (wasted space).
    let dead_threshold = 10u32; // smallest item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver -> strongly discourage
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill: reward heavily
    } else {
        // Usable but large leftover: mild penalty scaled by gap size
        score += 0.15 * post_residual as f64;
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual >= dead_threshold {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage opening another,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // If this candidate is a brand-new empty bin, penalize it more when
    // open-bin count is already high or mean residual is large.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.25 * mean_residual;
    }

    // Lookahead: if next item could use the post_residual, reward leaving
    // a useful gap; if next item is bigger than post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    score
}

