pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little dead space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward residuals that can still accommodate the next item,
    // penalize residuals that are too small to be useful but not tiny.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Dead space that can't fit the next item: penalize proportionally.
            let waste_frac = (post_residual as f64) / (next_item_size as f64);
            score += waste_frac * 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage it when
    // decent fits exist, but allow it when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / (bin_capacity as f64);
        // Penalize new bins when average residual across open bins is healthy.
        score += 40.0 - openness * 45.0;
        // Late in the stream, slightly favor consolidating into open bins.
        score += progress * 10.0;
        // If many bins are open, prefer reusing one of them.
        score += (open_bins_count as f64).min(20.0) * 1.5;
    }

    // Prefer bins whose residual is close to the item (minimizes fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Mild preference for fuller bins (larger item_size relative to residual is fine).
    let fill_ratio = item_size as f64 / (bin_residual.max(1) as f64);
    score -= fill_ratio * 5.0;

    // Penalize leaving residuals in the awkward "unusable" band (1..10) harder.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // generous residual that can host the next item twice: keep it open
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            // quadratic dead-space blowup early in the stream
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // unusable-space shaping
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // half-dead residual: slightly less hopeless
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // far-dead residual: strongly discouraged
            if (pr as u32) < (next_item_size as f64 * 0.6) as u32 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small leftovers are cheap wins
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // near-miss lookahead: residual just above next item but under 2x is wasteful
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // open bins are expensive when mean residual is already bloated
            if open_bins_count > 4 && progress > 0.5 {
                let avg_fill = (mean_residual / cap).max(1.0);
                if avg_fill < 0.18 {
                    score += 50.0 * (0.18 - avg_fill);
                }
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * ((open_bins_count as f64 / 20.0).min(2.0));
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
