pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fit (small post residual), non-linearly.
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: prefer leaving moderately usable space; Late: strongly prefer tight packing.
    let w = 0.5 + 1.5 * progress * progress;
    score += w * pr_norm * pr_norm * cap;

    // Dead-space penalty: residuals too small to likely fit future items.
    let dead = if next_item_size > 0 {
        let ns = next_item_size as f64;
        ((ns - pr).max(0.0) / cap).powi(2)
    } else {
        0.0
    };
    score += 40.0 * dead;

    // Lookahead synergy: bonus if post_residual can fit the next item.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when progress is high,
    // unless current bin would leave very little waste anyway.
    if bin_residual == bin_capacity {
        let waste = pr_norm; // equals 1 for empty bin
        score += 5.0 + 30.0 * progress * (1.0 - waste);
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins with residual near the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residuals near multiples of 25 are "clean" ---
    let pr = post_residual as i64;
    let class = pr % 25;
    let class_penalty = match class {
        0 => -30.0,                    // perfectly clean residual
        1..=6 => -12.0,                // near-clean
        24 => -20.0,                   // one unit off a clean class (almost perfect)
        19..=23 => -6.0,
        _ => ((class as f64) * 0.9),   // dirty middle classes penalized
    };
    score += class_penalty;

    // Integer-division threshold: post_residual bucket size (harmonic 1/4 of capacity)
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 25.0; // dead space below 1/8 capacity is nearly unusable
    } else if post_residual <= quarter {
        score -= 8.0;  // residual in [12, 25] still fits small items
    }

    // --- Next-item coupling: does post_residual admit the lookahead item? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how snug the future fit is
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * snug;
        } else {
            // lookahead cannot fit: penalize more when the gap is small (wasted near-miss)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
        // harmonic class match: next item is small (fits tiny residuals)
        if next_item_size <= 10 && post_residual >= 10 {
            score -= 6.0;
        }
    } else {
        // last item: prefer tightest packing, no future concerns
        score -= 15.0;
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0; // avoid opening a new bin if this is the only fit
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0); // mild penalty, many alternatives
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline competitive score; only attractive when
        // existing residuals are dirty (mean residual in a bad harmonic class)
        score = (bin_capacity as f64) * 0.55;
        let mean_class = (mean_residual as i64) % 25;
        if mean_class > 6 && mean_class < 19 {
            score -= 20.0; // open bins are dirty -> fresh bin attractive
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 25.0; // big item coming: prefer fresh capacity
        }
        if fitting_bins_count == 1 {
            score += 30.0; // never open when a unique fit exists
        }
        // stream phase: early on, tolerate more bins
        let phase = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - phase);
        return score;
    }

    // --- Fullness reward: bins closer to capacity are better targets ---
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fullness * fullness;

    // Mean residual divergence: prefer bins whose residual is below average (tighter)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Larger residual space is more reusable; reward proportionally.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Bin can also fit the next item: strong reward for chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size as u32) as f64 * 0.2;
    } else if next_item_size > 0 {
        // This placement leaves a gap too small for the next item: dead space risk.
        score += 20.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate / spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.3 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin should only win when the current
    // fit is terrible (large dead space) and few bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 60.0; // item much smaller than residual
        if bad_fit && open_bins_count > 3 {
            score -= 40.0; // fresh bin better than fragmenting
        } else {
            score += 50.0; // prefer existing bins otherwise
        }
    }

    // Mild preference toward bins with below-mean residual (fill emptier bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
