pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Residual that can host the next item twice stays valuable
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            // extra penalty when the dead space is small relative to next item
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            // strong quadratic dead-space blowup early in the stream
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // unusable residual fraction penalty
            let usable = pr_norm;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            } else {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64).max(1.0));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals become nearly perfect closes
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Loose-but-not-double fit: slightly penalize wasted headroom
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // many open bins with low average fill: opening fresh is fine
            if open_bins_count > 4 && progress > 0.5 {
                let avg_fill = (mean_residual / cap).max(0.001);
                if avg_fill < 0.18 {
                    score -= 50.0 * (0.18 - avg_fill);
                }
            }
            if open_bins_count > 6 && progress > 0.6 {
                score -= 2.0 * ((open_bins_count as f64 / 20.0).min(2.0));
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is disproportionately good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-lookahead_gap / 12.0).exp();
        // Penalize if post_residual is a sliver too small to fit the next item
        if (post_residual as i64) < (next_item_size as i64) && post_residual < 10 {
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; avoid wasting them.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.5 * dev; // tighter-than-average bins are valuable, penalize using them
    } else {
        score -= 0.3 * (-dev); // looser-than-average bins should absorb the item
    }

    // Last-chance bonus: only one fitting bin; strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let stream_progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when open bins are tight (mean residual low) or item is large.
        score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        score -= 0.2 * item_size as f64;
        score += 15.0 * stream_progress; // late in stream, consolidation matters more
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 30.0; // don't open a new bin when an existing fit leaves less waste
        }
    }

    // Penalize creating tiny dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
