pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 60.0;
    }

    // Penalize wasted residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // dead space below min item size
    }

    // Lookahead: bonus if next item fits the post residual well.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= (100 - slack_after_next.min(100)) as f64 * 0.5;
        } else {
            // next item won't fit here after placing current one
            score += 15.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins with small residuals relative to the mean (compact bins).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.3;

    // Time horizon: early in the stream, be more willing to open bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 50.0 + 250.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is fine if no open bin fits tightly.
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 120.0;
        }
    }

    // Mild penalty on bin proliferation: prefer filling existing bins
    // when many bins are already open.
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Early in the stream, tolerate residual; late in the stream, penalize residual quadratically.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;

    score += w_late * 60.0 * pr_norm * pr_norm;
    score -= w_early * 15.0 * pr_norm;

    // Reward tight fits via cubic coupling of item size fraction with progress.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill * fill * (0.5 + 0.5 * progress);

    // Penalize residual that cannot fit the next item (dead space) — polynomial in gap.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / bin_capacity as f64;
        score += 40.0 * gap * gap;
        // Bonus if post_residual still accommodates next item.
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - pr_norm);
        }
    }

    // Last-chance bin: strong smooth reward scaled by how full the bin already is.
    if fitting_bins_count == 1 {
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 30.0 * used * used * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open, encouraging consolidation; smooth in count.
    score += 0.8 * (open_bins_count as f64).powf(1.2) * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / (1.0 + mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 8ths.
    let class = (post_residual * 8 / bin_capacity.max(1)) as i64; // 0..7
    let class_weight = match class {
        0 => -30.0,          // near-perfect fit
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,
        5 => 12.0,
        6 => 18.0,
        _ => 25.0,           // large dead space
    };
    score += class_weight;

    // Tightness: fraction of bin used by this placement
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Lookahead: penalize if next item cannot fit into post_residual (dead space lock-in)
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // reward exact pairing (post_residual == next_item_size)
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            }
        }
        // modulo class complementarity: next item in same residue class mod 10
        if next_item_size % 10 == post_residual % 10 && post_residual > 0 {
            score -= 4.0;
        }
    } else {
        // last item: strongly prefer near-zero post_residual
        score += pr * 0.5;
    }

    // Last chance: only this bin can fit the item -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current bin fit is bad
    if bin_residual == bin_capacity {
        // base attractiveness of fresh bin
        score = 45.0 - 30.0 * fill;
        // prefer fresh bin early in stream or when mean residual is already large
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        score += 0.15 * mean_residual;
        // if only a poor class fit is available in open bins, new bin is attractive
        if class >= 5 {
            score -= 15.0;
        }
        // don't open new bin if some open bin gives near-perfect fit (class 0/1)
        // (handled implicitly: those bins get big negative scores)
    }

    // Mild penalty for bin proliferation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let n = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Multi-hosting: bin can host next item at least twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            // Over-slack penalty when residual barely exceeds next item
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / n * 10.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = n - pr;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 40.0 * dead_rel * (1.0 - progress);
            // Stronger dead-space shaping (borrowed & tuned)
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Nearly-half-dead residual is worst: extra shaping
            if pr > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * n {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * n));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are cheap to accept
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        // Consolidation pressure: many open bins with low average fill -> open new bins
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = (mean_residual / cap).max(1.0);
            if avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: residuals below min item size (1..10)
    // are pure waste; residuals that can't hold the next item are also suspect.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 * (1.0 - fit_ratio.min(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage proliferation of bins
    // unless the fit is genuinely good.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: neutral-ish base, penalized when open bins
    // with decent residual exist, rewarded when residuals are fragmented.
    if bin_residual == bin_capacity {
        score = 70.0 + 1.2 * open_bins_count as f64 - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 20.0; // big next item: fresh bin useful
        }
