        score -= 6.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: make empty bin attractive only when fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * frac_post; // base cost of opening a new bin
        if item_size >= 70 {
            score -= 30.0; // big item: fresh bin is good
        }
        if next_item_size > 0 && post_residual >= next_item_size && item_size <= 30 {
            score -= 15.0; // small item with room for lookahead item
        }
    }

    // Time horizon: early in stream, be more conservative about dead space; late, just pack
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalize post residual
    let x = pr / cap;

    // Non-linear polynomial coupling: dead space penalized more as stream progresses
    let poly = x * x * (1.0 - x) + x * x * x;
    score += 20.0 * poly * (0.5 + progress);

    // Reward tight fits (small post residual) increasingly over time
    let tightness = (1.0 - x).powi(3);
    score -= 15.0 * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: favor residuals that can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (ni / cap)) * (1.0 - progress);
        } else {
            score += 6.0 * progress * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Slight penalty when bin residual is far above mean residual (fragmentation)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild preference for filling existing bins when many are open
    score += 0.5 * (open_bins_count as f64).ln() * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class decomposition of post_residual ----
    // Class A: near-perfect fit (residual < 10) -> excellent, big reward.
    // Class B: residual divisible into small useful chunks (mod 10 == 0) -> reward.
    // Class C: mid-range residual (35..=65) -> dead-space danger, penalize.
    // Class D: large residual (> 65) -> still flexible, mild reward.
    let pr = post_residual;
    if pr < 10 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr >= 35 && pr <= 65 {
        score += 18.0;
    } else if pr > 65 {
        score -= 6.0;
    }

    // Finer modulo structure: residuals that divide evenly by 20 or 25 pair
    // well with common item sizes; reward those harmonics.
    if pr % 20 == 0 { score -= 6.0; }
    if pr % 25 == 0 { score -= 5.0; }
    // Odd primes / awkward remainders create dead space.
    if pr % 10 != 0 && pr % 5 != 0 { score += 4.0; }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap >= 0 {
            // Next item fits exactly into this residual: strong reward.
            if gap == 0 {
                score -= 35.0;
            } else if gap <= 10 {
                score -= 20.0;
            } else {
                // Fits but leaves a new residual; judge that new residual's class.
                let nr = gap as u32;
                if nr < 10 { score -= 15.0; }
                else if nr % 10 == 0 { score -= 8.0; }
                else if nr >= 35 && nr <= 65 { score += 8.0; }
            }
        } else {
            // Next item will NOT fit here: if residual is small this bin is
            // "closed" cleanly (good); if residual is mid-range it becomes
            // stranded dead space (bad).
            if pr >= 20 && pr <= 45 {
                score += 25.0;
            } else if pr < 20 {
                score -= 10.0;
            } else {
                score += 5.0;
            }
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; avoid opening a new bin.
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new bin: post_residual = capacity - item_size.
        // Prefer opening a new bin when existing bins are tight / item fits
        // nowhere well, i.e. when the item is large relative to capacity and
        // open bins are already fragmented.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.5 {
            score -= 10.0 * fill_frac;
        }
        // If many bins are open and mean residual is high, prefer reusing.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Late in the stream, consolidating is better than spreading.
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.7 {
            score += 8.0;
        }
    } else {
        // Reusing an open bin: reward keeping open_bins_count low.
        score -= 3.0;
        // Slight preference for tighter existing bins (best-fit flavor)
        // beyond the raw post_residual baseline.
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 4.0 * tightness;
    }

    // Mild global pressure: when many bins are open, favor consolidation.
    if open_bins_count > 5 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable
    // since future items are >= 1..100, but tiny gaps rarely fit anything useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64); // heavy penalty for tiny gaps
    }
    // Perfect fit is the best possible outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer placing into the emptiest bin (largest residual) to consolidate space.
    score -= 0.3 * bin_residual as f64;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer new bin less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits inside post residual, mild reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        score -= 8.0;
    }
    // If post residual is smaller than next item but nonzero, penalize (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate baseline: opening a new bin should only win when placement
    // here is bad (large dead space) or bins are already tight/fragmented.
    if bin_residual == bin_capacity {
        score = 20.0 + 0.4 * mean_residual - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Residual large enough to host next item twice: keep it alive
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            // Slack just above next item: mildly discourage wasteful hosting
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                score += 0.8 * slack / next_item_size as f64;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // Usability shaping: near-half leftovers are salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            let usable = pr_norm;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            if (pr) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress)
                    * (1.0 - (pr / (0.6 * next_item_size as f64)));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are cheap to finish off
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        // Many open bins with low average fill: resist opening yet another bin
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = mean_residual / cap.max(1.0);
            if avg_fill < 0.18 {
                score += 50.0 * (0.18 - avg_fill);
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, be more selective about bin choice.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin's leftover.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward proportionally to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 25.0 * tight;
        } else {
            // Next item won't fit in leftover: penalize wasted space relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.3 * gap;
        }
    }

    // --- Deviation from mean residual: prefer bins with small residuals (tight fits) ---
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits, or if it
        // enables a perfect 2-item chain (item + next fill it exactly).
        if fitting_bins_count > 0 {
            let perfect_chain = next_item_size > 0 && (item_size + next_item_size) == bin_capacity;
            if perfect_chain {
                score -= 70.0;
            } else {
                score += 25.0 + 20.0 * (1.0 - progress);
            }
        }
    }

    // Slight preference for keeping many open bins consolidated when late in stream.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but scale by capacity usage.
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score *= 0.5 + 0.5 * fill_ratio;

    // Reward tight fits: small post_residual relative to capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * 20.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward but less if it leaves awkward remainder
            let rem = post_residual - next_item_size;
            score -= 12.0 - (rem as f64) * 0.1;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count.min(50) as f64) * 0.3;
    }

    // Global residual balance: prefer bins whose residual is near mean
    // (keeps flexibility) unless tight fit overrides.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Time horizon: early in stream, be conservative (favor new bins
    // less); late in stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // New-bin candidate handling: opening a new bin is fine early or when
    // item is large relative to residual elsewhere; penalize moderately
    // so it only wins when existing fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + progress * 5.0 - (item_size as f64) * 0.15;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 40.0; // reserve empty bin for a full-size item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

