}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual

    // Base: penalize wasted space quadratically-cubically
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    // Early stream (t small): mild penalty on residual -> prefer filling bins loosely
    // Late stream (t large): strong penalty on residual -> prefer tight fits
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * x * x * cap;

    // Cubic interaction: dead space (small post_residual) is fine; large residual is bad
    score += t * (x * x * x) * cap * 0.8;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= (1.0 - x) * (1.0 - x) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild penalty when many bins are open (avoid sprawl)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Lookahead coupling: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 3.0 + 5.0 * fit_quality * (1.0 - t);
        } else {
            // next item won't fit: penalize slightly more late in stream
            score += 2.0 * t;
        }
    }

    // New-bin candidate handling: empty bin gets neutral-ish score unless open bins are fragmented
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; more when mean residual of open bins is large
        score = cap * (0.9 + 0.3 * t) + (mean_residual / cap) * 20.0;
        if fitting_bins_count <= 1 {
            // no real alternative, allow new bin
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items (quadratic, stronger)
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 5.5 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-of-next-item chain bonus
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            // Over-slack penalty when barely bigger than next item
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size.max(1) as f64 * 10.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: slightly less bad
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
            // Strongly unusable residual: extra penalty scaled early
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: tiny residual is a good finishing move
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
            }
            // Mid-stream pressure: many open bins with low average fill -> allow fresh bin
            if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularity (e.g. multiples of 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals that fall into "harmonic" classes (mod 10 == 0, mod 5 == 0)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: tiny dead space is effectively perfect.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Fraction of capacity wasted: penalize residuals in the awkward middle band
    let frac = post / cap;
    if frac > 0.3 && frac < 0.5 {
        score += 10.0 * (0.4 - (frac - 0.4).abs()) + 5.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // this bin is doubly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 4.0; // next item likely won't fit here
        }
        // Harmonic check: post_residual is a multiple of next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit
    // here would be poor.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score += 15.0;
        score -= crowded * 8.0;
        // If item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / cap) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 12.0;
    }

    // Mild pressure to balance residual mass across bins.
    score += (post - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small,
    // likely unusable gap) is heavily penalized. Dead zone grows with
    // typical item size; treat gaps below ~30 as increasingly wasteful.
    let dead_zone = 30.0f64;
    if (post_residual as f64) < dead_zone {
        let depth = (dead_zone - post_residual as f64) / dead_zone;
        score += 45.0 * depth * depth; // quadratic penalty for unusable slivers
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 20.0 * tightness * tightness;
    }

    // Perfect fit bonus: leaving exactly zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few
    // fitting bins exist; encourage using existing bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the
    // mean (keeps the pool of usable residuals homogeneous).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mildly penalize leaving residual it
        // cannot use if that residual is small (dead space for the future).
        let wasted = (post_residual as f64) / (next_item_size as f64);
        if wasted < 1.0 {
            score += 8.0 * (1.0 - wasted);
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is attractive early in the stream or when few bins
    // are open; it becomes unattractive as the stream fills up.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 40.0 * progress + 6.0 * pressure;
        // Exception: large items with poor fit prospects elsewhere still
        // favor a fresh bin slightly.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild stream-progress coupling: later in the stream, be more frugal
    // about residual waste overall.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 6.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
