pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but never leave a residual
    // that is unusably small yet nonzero (dead space) for typical item sizes.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 12.0; // tiny unusable sliver
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack = post_residual as f64 - next;
            // Reward perfect 2-step chain heavily; decay with slack.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 15.0; // perfect chain: item + next fills bin exactly
            }
        } else {
            // Next item cannot follow: penalize proportionally to how much
            // the next item overshoots the residual.
            let overshoot = next - post_residual as f64;
            score += 4.0 * (overshoot / 100.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable
    // to fill now; looser-than-average bins can be saved for awkward items.
    let cap = bin_capacity as f64;
    let relative = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * relative;

    // Last-chance logic: if this is the only fitting bin, avoid forcing a
    // new bin open unless the fit is terrible.
    if fitting_bins_count == 1 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 20.0 * fit_ratio; // strong reward to use the last fitting bin on a good fit
        } else {
            score += 6.0; // poor fit into the only option; let new bin compete
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): should only win when
    // no open bin offers a decent fit. Penalize opening new bins mildly, more
    // so early in the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 6.0 * (open_bins_count as f64).ln().max(0.0) + 5.0 * (1.0 - progress);
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 22.0;
        }
    }

    // Mild preference to consolidate into bins that are already mostly full.
    let fill = 1.0 - (bin_residual as f64 / cap);
    score -= 5.0 * fill;

    // Small nonlinear tightening: quadratic in post residual to favor
    // near-exhaust placements over medium leftovers.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
