    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual - post_residual) as f64 * (0.5 + 0.5 * progress);

    // Penalize dead space: post residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
