        // But if the only alternative wastes a lot, allow new bin (tight item).
        if item_size >= bin_capacity * 9 / 10 {
            score -= 35.0;
        }
    }

    // Global balance: prefer bins whose residual is near mean residual (avoid extremes).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
