pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class A: post_residual in {0} -> perfect fit, strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: post_residual <= 10 -> near-perfect, dead space minimal
    else if post_residual <= 10 {
        score -= 60.0;
    }

    // Class C: post_residual in (10, 20] -> still usable for smallest items
    else if post_residual <= 20 {
        score -= 15.0;
    }

    // Dead zone: (20, 30) is the worst waste band (nothing guaranteed fits later if min size is 10,
    // but with unknown distribution 1..100, treat 20..40 as progressively risky)
    else if post_residual < 40 {
        score += 20.0 + (40 - post_residual) as f64 * 0.5;
    }

    // Harmonic quarter classes: post_residual divisible structure
    let q = post_residual / 25; // 0..4 quarters of capacity
    score -= match q {
        0 => 10.0,
        1 => 5.0,
        2 => 0.0,
        _ => -5.0, // large residual: bin stays flexible, mildly favored
    };

    // Modulo-10 harmonic: post_residual that is a multiple of 10 aligns with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or with small slack -> strong reward
            let slack = post_residual - next_item_size;
            score -= 40.0 + (10 - slack.min(10)) as f64;
        } else if next_item_size <= post_residual + 15 {
            // near miss: penalize slightly, bin would become nearly useless
            score += 12.0;
        }
        // lookahead modulo harmony: next_item_size harmonic with post_residual
        if post_residual > 0 && next_item_size % 10 == post_residual % 10 && next_item_size < post_residual {
            score -= 10.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // this is the only bin that can take the item; avoid opening a new bin
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // fresh bin: attractive if current open bins have small residuals (fragmented),
        // unattractive if open bins are roomy
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + fragmentation * 0.5;
        if open_bins_count == 0 {
            score -= 200.0; // must use a bin at all
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: new bin is the only option
        }
    }

    // --- Stream progression: pack tighter as stream advances ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // --- Mean residual coupling: prefer bins deviating favorably from mean ---
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Tightness ratio reward: how well item fills the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // worst kind of dead space
    } else if post_residual == 0 {
        score -= 45.0; // perfect closure, reward heavily
    } else if post_residual <= 20 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits relative to the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    // and open-bin pressure is low.
    if bin_residual == bin_capacity {
        score += 40.0 + 6.0 * open_bins_count as f64;
        // If the next item would fit in the leftover of this placement,
        // opening fresh is less attractive.
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to the item (snug placement).
        let snug = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 12.0 * snug;
        // Lookahead: bonus if next item fits exactly into post_residual.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 10.0; // leftover likely wasted given lookahead
        }
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += 1.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Late in the stream, prefer packing tightly into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base shaping: prefer tight fits, mild non-linearity
    score += 0.5 * pr_norm * pr_norm * cap * 0.1;

    // Lookahead: exact fit jackpot, graded slack reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // two-for-one: residual hosting next item twice is a jackpot
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            // bin can't host next item: penalize dead space strongly
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 800.0 * dead * dead * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // half-dead space: residual too small to be useful for next item
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            } else if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: squeeze tiny residuals
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Early stream: keep mid-size residuals usable
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Many competitors and loose fit: mild penalty
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }
    // near-miss overhang when crowded
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    score += 0.06 * (bin_capacity - bin_residual) as f64;

    // New-bin candidate: open only when no fit or a good chain is possible
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // pressure when many bins are open and mean residual is low
            if open_bins_count > 4 && progress > 0.5 {
                let avg_fill = mean_residual / cap;
                if avg_fill < 0.18 {
                    score += 50.0 * (0.18 - avg_fill);
                }
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 45.0; // perfect 2-step match: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item still fits here; mild reward scaled by tightness
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to waste
            let waste = (post_residual as f64 - nxt).abs();
            score += 0.35 * waste;
        }
    }

    // Tight fit reward relative to mean residual of open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * (1.0 - t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving residuals that are small but not zero (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Favor bins already below mean residual (fill emptier bins first when lookahead neutral).
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: make it attractive only when no open bin offers a good 2-step fit.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if good_lookahead || fitting_bins_count <= 1 {
            score += 25.0; // discourage opening a new bin when decent fits exist
        } else {
            score -= 5.0; // allow fresh bin when all open fits are poor
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
