pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty growth
    let mut score = post * (1.0 + 0.35 * norm_post * norm_post);

    // Smooth coupling of post_residual with stream progress:
    // early on, tight packing matters more; late, avoid leaving large residuals
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 12.0 * norm_post * progress_coupling;
    score -= 8.0 * norm_post * progress;

    // Reward using a bin whose residual is well matched to item size (smooth quadratic mismatch)
    let mismatch = (bin_residual as f64 - item_size as f64) / cap;
    score += 15.0 * mismatch * mismatch;

    // Last-chance bonus: only one fitting bin -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits in post_residual (smooth sigmoid-like gain)
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fits = (post - next_item_size as f64) / cap;
        if fits >= 0.0 {
            score -= 10.0 * (1.0 - next_norm) * (1.0 + progress);
        } else {
            score += 6.0 * (-fits) * (1.0 - progress);
        }
    }

    // Prefer consolidating into fewer bins when many are open
    score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - norm_post);

    // Slight penalty when bin residual deviates from mean residual (keep balance)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only for large items leaving small dead space
    if bin_residual == bin_capacity {
        score = 20.0 + 30.0 * norm_post - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality by integer division thresholds
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: near-perfect fit (post_residual small) -> strong reward
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 12 {
        score -= 35.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by small steps (10, 20)
    // are more reusable by typical item sizes drawn on a coarse grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 4.0;
    }

    // Harmonic pairing: post_residual can exactly host next_item_size (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Exact match is a harmonic resonance: extra reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Integer-division threshold: post_residual hosts next item with room for another
        let div = post_residual as u32 / next_item_size.max(1);
        if div >= 2 {
            score -= 10.0 * (div.min(4) as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: dead space penalty scaled by how close it is
        let gap = (next_item_size - post_residual) as f64;
        score += (gap / cap) * 30.0;
    }

    // Capacity fraction classes: reward filling toward harmonic fractions of capacity
    let fill = (bin_residual as f64) / cap;
    if fill > 0.9 {
        score -= 25.0;
    } else if fill > 0.75 {
        score -= 15.0;
    } else if fill > 0.5 {
        score -= 5.0;
    } else {
        // Filling a low-fill bin wastes its versatility
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would be left with unusable dead space and the item is large.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin
        score += 55.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Large item followed by large item: fresh bin may pair them
            score -= 30.0;
        }
        if post_residual as f64 > cap * 0.5 {
            // Item small relative to bin: wasteful to open a new bin
            score += 20.0;
        }
    }

    // Stream progression: early in the stream, keep bins open/versatile;
    // late in the stream, aggressively fill existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    if progress < 0.25 && post_residual > 40 {
        score += 8.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, prefer using it
    // (concentrate slack), scaled mildly.
    score += (post - mean_residual) * 0.15;

    // Many open bins: prefer tightening existing ones over spreading
    if open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Small gaps are risky: penalize quadratically the unusable fraction.
        let gap = post_residual as f64;
        score += (20.0 - gap) * (20.0 - gap) * 0.15;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Perfect "pairing" fit: this bin's leftover exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If the next item fits the post residual, this is a great chain placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (discourage opening new bins); with few bins, opening is cheap.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    // New-bin candidate (bin_residual == bin_capacity): penalize it by pressure,
    // but less late in the stream when leftovers are unlikely to be reused.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure - 15.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with below-mean residual (tighter bins first), keeping
    // looser bins flexible for future large items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
