    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit jackpot; graded slack reward; dead-space penalty
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // bins that can host next item twice are valuable
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_rel = gap / cap;
            // scaled dead-space penalty (borrowed from best)
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr_norm;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // half-fit: residual still useful for smaller follow-ups
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // severely undersized residual relative to next item
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - (pr / (0.6 * next_item_size as f64)));
            }
            // small dead space relative to next item
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            // residual too small to ever be useful again
            if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
                score -= 2.5;
            }
        }
        // chain fit: residual between next and 2x next with competition
        if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let over = (post_residual - next_item_size) as f64;
            score += 0.8 * over / next_item_size as f64 * 10.0;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        // open new bins when many open bins are nearly empty (consolidation pressure)
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = (mean_residual / cap).max(0.0);
            if avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * ((open_bins_count as f64 / 20.0).min(2.0));
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving residual that neither fits next item nor is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.2 * next_item_size as f64;
        }
        if mean_residual > 0.6 * bin_capacity as f64 {
            score -= 25.0; // open bins are nearly empty, spreading is fine
        }
    }

    // Dead-space penalty: small unusable leftovers are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let tightness = item_size as f64 / residual;
        score -= 40.0 * tightness * tightness;
    }

    // Penalize dead space: small post_residual that is still hard to fill later.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0; // awkward sliver
    } else if pr == 0.0 {
        score -= 25.0; // perfect closure is excellent
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if post residual can't hold next item but could hold
    // typical items, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 35.0; // chains a perfect follow-up placement
        } else if pr >= nxt {
            score -= 8.0; // next item still fits here afterwards
        } else {
            score += 6.0 * (1.0 - pr / 100.0); // stranded space for the lookahead
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing bins rather than opening new ones.
    let mean_res = mean_residual;
    if bin_residual < bin_capacity {
        // existing bin: reward more when bin is below-average residual (denser bin)
        score -= 10.0 * (mean_res - residual).max(0.0) / 100.0;
    } else {
        // new-bin candidate: penalize when open bins already hold plenty of space
        score += 12.0 * (mean_res / 100.0) + 0.5 * open_bins_count as f64;
        // but allow opening when existing bins are nearly full
        if mean_res < 20.0 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, keep bins open and flexible (favor
    // larger post residuals slightly less); late in stream, close bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (pr / 100.0) - progress * 10.0 * (pr / 100.0);

    score
}

