pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // tight fits (small post_residual) are increasingly valuable as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + 6.0 * progress) * 8.0;

    // Cubic dead-space penalty for large post_residual, growing with progress.
    let dead = pr / cap;
    score += dead * dead * dead * (2.0 + 10.0 * progress) * 10.0;

    // Reward using a bin whose residual matches the item well (relative fill).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * fill * 6.0;

    // Last-chance bin bonus (only one bin fits): smooth interaction with progress.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Slight preference for bins with residual close to the mean (balance pressure).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 4.0;

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 3.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize mildly early, allow more when many bins open / late stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress) - (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Overhang penalty: residual barely above next item wastes space (from best)
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                score += 0.8 * slack / next_item_size as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            // Relative dead-space shaping (from best): residual below next item scales with item size
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    if post_residual == 0 {
        score -= 180.0;
    }

    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25 define
    // "good" leftover classes (small, reusable remainders).
    let r10 = (post_residual % 10) as f64;
    let r25 = (post_residual % 25) as f64;

    // Penalize awkward residues (5..9 mod 10 wastes space for small items).
    if post_residual > 0 {
        score += (r10 - 2.0).abs() * 0.8;
        // Penalize residues in the middle of the mod-25 class (dead zone).
        if r25 > 8.0 && r25 < 17.0 {
            score += 3.0;
        }
    }

    // Integer-division thresholds on post_residual: quarters of capacity.
    let q = post_residual / 25; // 0..4
    score += match q {
        0 => -6.0,           // tiny leftover: excellent packing
        1 => -2.0,           // small leftover
        2 => 1.5,            // medium leftover: risky
        3 => 4.0,            // large leftover: wasteful
        _ => 0.0,            // empty/new bin handled below
    };

    // New-bin candidate: prefer it only if no open bin leaves a "harmonic" fit.
    if bin_residual == bin_capacity {
        score = 55.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // next item won't fit a fresh bin anyway
        }
        return score;
    }

    // Perfect-fit reward: post_residual in {0, 10, 20, 25, 50} are reusable classes.
    let harmonic = matches!(post_residual, 0 | 10 | 20 | 25 | 50);
    if harmonic {
        score -= 8.0;
    }

    // Lookahead coupling: does next_item_size exactly fill the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let nxt_class = next_item_size % 10;
            score -= (10 - nxt_class) as f64 * 0.3; // small next items reuse residue
        } else {
            score += 2.0; // next item breaks this bin anyway
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 7.0;
    }

    // Mild pull toward the mean residual to balance bin load.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, tighten packing (favor tight bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps are the enemy.
    // Any post_residual below the minimum item size (1) is impossible here,
    // but small residuals (< 20) are statistically hard to fill later.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: best possible outcome.
        score -= 1000.0;
    } else if post_residual < 20 {
        // Dead-space zone: penalize quadratically as gap shrinks.
        score += (20.0 - pr) * (20.0 - pr) * 2.0;
    } else if post_residual > 80 {
        // Large leftover is fine (still flexible), mild reward.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Mean residual coupling: if mean residual is low, conserve bins tightly.
    score += (mean_residual - pr).max(0.0) * 0.5;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap the next item can't use: penalize.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded
    // or the fit would be wasteful.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; pressure grows with open bins count.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 20.0; // fresh bin can serve the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
