                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space relative to mean residual.
            let dead = post_residual as f64;
            score += dead * (1.0 + (mean_residual - dead).max(0.0) / bin_capacity as f64);
