    } else {
        // Last item: just minimize post-residual.
        score -= 10.0;
    }

    // Prefer tighter current fit.
    score += (bin_residual - item_size) as f64 * 0.1;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins could fit well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // But if existing bins leave bad dead space, new bin becomes attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        if next_item_size == 0 {
            score -= 50.0;
        }
    }

    // Late in the stream: consolidate, avoid leaving many tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
