    } else {
        // Late in the stream: strongly prefer filling existing bins over opening new ones
        score += progress * 8.0;
        // Crowding: with many open bins, prefer bins with small residuals (consolidate)
        if open_bins_count > 3 {
            score += (bin_capacity - bin_residual) as f64 * 0.05;
        }
    }

    score
}

