        score += 15.0;
    }

    // Modulo-10 class coupling: remainders divisible by 10 align with the item grid
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual > 0 {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
