            // next item won't chain here; penalize more if leftover is small/dead
            score += 6.0 + pr * 0.05;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // and many bins are open with slack.
    if bin_residual == bin_capacity {
