                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual can host next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: nearly unusable, stronger early
            if (pr as u32) > next_item_size / 2 && pr < next_item_size as f64 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    let crowd = if progress > 0.6 && open_bins_count > 6 {
                        2.0 * ((open_bins_count as f64) / 20.0).min(2.0)
                    } else {
                        0.0
                    };
                    score += pressure + late + crowd;
                    // Low average fill: opening fresh bins is wasteful
                    if avg_fill < 0.18 {
                        score += 50.0 * (0.18 - avg_fill);
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: low post_residual relative to capacity, amplified by progress.
    let tight = 1.0 - (pr / cap);
    score -= 18.0 * tight * tight * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let waste = (ni - pr) / cap;
            score += 22.0 * waste * (1.0 + progress);
        } else {
            // Reward leaving exactly enough room for the next item.
            let margin = (pr - ni) / cap;
            score -= 10.0 * (-8.0 * margin).exp();
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to prefer better-fitting bins.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate: penalize opening a bin unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        let penalty = 26.0 - 14.0 * progress - 20.0 * frag * frag;
        score += penalty.max(0.0);
    } else {
        // Prefer bins whose residual is below the mean (consolidate large holes).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev.max(0.0);
    }

    // Smooth polynomial coupling of post_residual with stream progress.
    let x = pr / cap;
    score += 6.0 * x * x * (1.0 - progress) - 4.0 * x * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // partial dead space: how much of next item could have fit
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            } else {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Bins that can host the next item twice: keep them alive
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 3.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Loose-fit-over-next-item penalty when competition exists
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // Late-stream: squeeze small residuals hard
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are nearly empty, opening fresh is less wasteful
            if open_bins_count > 4 && progress > 0.5 {
                let avg_fill = (mean_residual / cap).max(0.0);
                if avg_fill < 0.18 {
                    score -= 50.0 * (0.18 - avg_fill);
                }
            }
            if progress > 0.6 && open_bins_count > 6 {
                score -= 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: coarse buckets via integer division.
    // Small post_residual (tight fit) is good -> keep base low there.
    let class = post_residual / 10; // 0..=10 harmonic class
    score += (class as f64) * (class as f64) * 1.5; // quadratic penalty on coarse class

    // Exact harmonic residue: reward leftovers that are multiples of 10/20 (likely reusable).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fit: absolutely reward zero residual.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next fits, but how harmonically? Reward small leftover-after-next.
            let next_left = post_residual - next_item_size;
            score -= 15.0 - (next_left as f64) * 0.2;
        } else {
            // Next item cannot use this leftover: penalize proportional to wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residuals are hopeless.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin becomes attractive.
        score -= mean_residual * 0.6;
        // Late in the stream, avoid spawning bins for few remaining items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins below mean residual (spreading large gaps).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score += 3.0;
    }

    // Threshold logic: leftovers below 10 are dead space (items are >= 1 but classes
    // below 10 are hard to reuse) -> extra penalty scaled by deadness.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // item size (1..100 interface, but typical stream items >= 10) are wasted.
    // Penalize "unusable" gaps hard, but reward perfect closure.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always prefer
    } else if post_residual < 10 {
        score += 50.0 + post_residual as f64; // dead space: tiny unusable gap
    } else if post_residual < 20 {
        score += 15.0; // likely dead space too
    }

    // Prefer bins whose residual is "tight" relative to item size.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when there are many open bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 30.0 + 20.0 * (1.0 - progress);
        // If lookahead item could pair with this fresh residual, make new bin cheaper.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= 0.0 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Slight nudge toward bins below mean residual (fill the emptiest-fit bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

