    // concentrates small residuals, keeping larger residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = 110.0
            - 20.0 * (1.0 - (step_index as f64 / total_items as f64).min(1.0))
            + (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0; // big items better in fresh bins
        }
    }

    // Late in the stream: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

