pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post residual (larger leftover = better fill)
    let mut score = pr;

    // Non-linear penalty for mid-range dead space (worst residuals ~ 10..50)
    let dead = (pr_norm - 0.3).powi(2);
    score += 40.0 * dead * (1.0 - progress);

    // Stream-progress coupling: late in stream, prefer tight fits more aggressively
    score -= 30.0 * progress * (1.0 - pr_norm).powi(3) * item_size as f64 / cap;

    // Last-chance bonus: only fitting bin -> strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening new bins when others fit, less so early
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 15.0 + 35.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - ((pr - ni) / cap).powi(2));
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Mean residual interaction: penalize bins far from the fleet mean (fragmentation)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Smooth open-bin pressure: more open bins -> prefer consolidation into emptier-tight bins
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction slot we land in.
    let quarter = bin_capacity / 4; // 25
    let post_class = post_residual / quarter; // 0..=4
    let item_class = item_size / quarter;

    // Reward landing in "clean" harmonic classes (residual is a multiple of quarter).
    if post_residual % quarter == 0 {
        score -= 6.0;
    } else {
        score += (quarter - post_residual % quarter) as f64 * 0.15;
    }

    // Dead-space penalty: residual in the awkward (10..25) band is nearly unusable
    // for items in [1,100] unless next item is tiny.
    if post_residual > 0 && post_residual < quarter {
        score += 14.0;
        // salvageable if lookahead item fits snugly
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Perfect fit reward, stronger late in the stream.
    if post_residual == 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 + 10.0 * progress;
    }

    // Lookahead coupling: harmonic class match between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // same harmonic class chain bonus
            if (next_item_size / quarter) == post_class {
                score -= 4.0;
            }
            score -= 2.0;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 20.0 + 25.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && post_residual == bin_capacity {
            score -= 5.0; // big next item favors fresh bin
        }
    }

    // Prefer filling bins whose residual is already below the mean (consolidate waste).
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    }

    // Integer-division threshold: penalize leaving residual in [quarter, 2*quarter)
    // band when item is large (creates mid-size dead zones).
    if post_class == 1 && item_size > bin_capacity / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residual too small for typical future items is wasted.
    let dead_threshold = next_item_size.max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 30.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * open_bins_count as f64;
        if post_residual >= 70 {
            score -= 10.0; // big item into fresh bin is fine
        }
    }

    // Open-bin pressure: mild reward for using existing bins when many are open.
    score -= 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Progress: early in stream, be pickier about residual quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Slight alignment with mean residual: avoid making bins worse than average.
    if (post_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            // Perfect 2-step match: strongly reward
            score -= 60.0;
        } else if post >= next {
            // Next item still fits: mild reward, scaled by leftover after next
            let after_next = post - next;
            score -= 25.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize wasted potential
            score += 15.0 * (next - post) / 100.0;
        }
        // Coupling with mean residual: bins far from mean are less predictable
        score += ((post - mean_residual) / 100.0).abs() * 5.0;
    } else {
        // Last item: just minimize post_residual
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if no good fit exists among open bins
    if bin_residual == bin_capacity {
        // Penalize opening new bins moderately; lookahead match elsewhere overrides
        score += 30.0;
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 20.0; // open bins likely useful for next item too
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: tight fits preferred, with mild non-linear shaping
    let mut score = pr * (1.0 + 0.4 * pr_norm * pr_norm);

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward for preserving tight chains
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // penalize loose fits when many alternatives exist
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            // overhang between one and two next items: mild penalty
            if post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size.max(1) as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_rel = gap / cap;
            score += 1.8 * gap;
            score += 40.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // unusable sliver: strongly discourage
            if post_residual > 0 && (pr) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // half-usable residuals: discourage early, allow late
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // relative dead-weight of residual vs capacity
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // small residuals below item size get scaled penalty
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    // Late-stream: snap up residuals close to current item scale
    if progress > 0.75 && post_residual > 0 && (pr) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap;
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Penalize dead space that no future item (10..80 range, but here 1..100) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    if let Some(_n) = None { let _ = _n; }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted residual
            score += 5.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // existing residuals are large (bad fits) or many bins are open already.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 80.0;
        new_bin_penalty -= 40.0 * avg_pressure;      // if open bins are full-ish, new bin ok
        new_bin_penalty -= 30.0 * (1.0 - progress);  // early on, keep bins compact
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open first bin
        }
        score += new_bin_penalty.max(-100.0);
    } else {
        // Slight preference for bins with residual close to mean (balance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Mild global compactness: more open bins -> prefer filling existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_frac = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, tolerate slack; later, squeeze bins hard
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits (small post_residual) with a smooth bonus term
    let tightness = 1.0 - norm_pr; // 1 when perfectly full
    score -= 12.0 * tightness * tightness * item_frac;

    // Penalize leaving residual that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 8.0 * g * g * (1.0 - progress);
        } else {
            // lookahead fits: mild reward, stronger if it fits snugly
            let snug = (-gap / cap).min(1.0);
            score -= 4.0 * snug * (1.0 - snug);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open relative to stream length (encourage consolidation)
    let bin_pressure = open_bins_count as f64 / (total_items as f64).max(1.0).sqrt();
    score += 2.0 * bin_pressure * norm_pr;

    // Encourage balancing residuals toward the mean (smooth attraction)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits get huge reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Reward tight fits (small post_residual), stronger when it's a divisor-class fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if bin_capacity % post_residual == 0 {
        // residual that divides capacity evenly is reusable by harmonic packing
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    }

    // Penalize residuals in awkward classes (prime-ish / non-harmonic zones)
    if post_residual > 25 && post_residual < 50 && bin_capacity % post_residual != 0 {
        score += 10.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 80.0;
        } else if post_residual < next_item_size && post_residual >= 1 && post_residual <= 10 {
            // dead space that next item can't use but is small
            score -= 5.0;
        } else if post_residual < next_item_size {
            score += 12.0; // dead space for lookahead
        }
        // harmonic: residual is an integer multiple/divisor relation with next item
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 30.0;
        }
        let _ = nx;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer filling bins with low mean residual (denser packing) mildly
    score -= 0.15 * (cap - mean_residual);

    // New-bin candidate (empty bin): penalize so it's chosen only when open bins fit badly
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * it;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
    }

    // Late-stream tightening: near the end, favor closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / cap);

    // Mild preference for bins with larger current residual usage
    score -= 0.1 * (bin_residual as f64);

    // Many open bins: discourage spreading, reward consolidation
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln() * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
