pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that cannot hold
    // even the smallest plausible item are heavily penalized.
    let min_useful = 10u32.min(bin_capacity / 10).max(1);
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Penalize leaving large-but-awkward gaps relative to the next item:
    // if next item fits snugly in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // and avoid spreading; with few bins, allow new-bin opening.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: empty bin should only win when the current bin
    // would leave bad dead space or the fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < min_useful as f64 && post_residual > 0;
        if poor_fit {
            score -= 10.0; // never mind, this placement was bad anyway
        }
        // Base new-bin cost: opening a bin is expensive unless pressure is low.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is less attractive (waste).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing)
    // unless the fit is tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
