pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item closes this bin
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to leftover space
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * ratio * ratio;
        } else {
            // next item cannot fit here; leftover is dead space for lookahead
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Penalize leaving residuals that are likely unusable (very small gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space creation
    }

    // Compare against mean residual across open bins:
    // favor bins whose residual is above-average (they have room to spare),
    // penalize consuming below-average residual bins too eagerly.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 5.0 * (1.0 - rel);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Slight penalty so open bins with decent fits win; but if all fits are bad
        // (large post_residual on open bins), the base score comparison handles it.
        score += 12.0;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference for using many open bins efficiently vs. sprawling.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
