pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Penalize dead space that can't fit the smallest plausible next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += pr * 0.5;
        }
        // Reward residuals that exactly fit the lookahead item (perfect pairing).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
        // Smooth quadratic penalty on large leftover space.
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding: many open bins -> prefer packing existing bins harder.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= crowding * 3.0;

    // Global mean residual coupling: if mean residual is large, waste matters less;
    // if mean residual is small, avoid creating more waste.
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.3;

    // Time horizon: late in the stream, be more conservative (avoid tiny slivers).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.4;

    // New-bin candidate handling: an empty bin has huge post_residual;
    // only allow it when nothing else fits well (its raw score is naturally high,
    // but give a small bonus when current bin residual is a very poor fit).
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Bonus for fresh bin when the item is large relative to capacity.
        score -= 10.0 + (item_size as f64 / bin_capacity as f64) * 20.0 - poor_fit * 0.1;
