    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space non-linearly (quartic term grows fast)
    score += 12.0 * fit_norm * fit_norm * fit_norm * fit_norm * cap * (0.5 + progress);

    // Reward tight fits with smooth exponential-like polynomial
    let tightness = 1.0 - fit_norm;
    score -= 20.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // Last-chance bonus: only one fitting bin -> prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: mildly penalize opening bins late in the stream,
    // but allow it when post_residual of open bins would be very small waste
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.1 + 0.4 * progress) - 6.0 * tightness;
        if fitting_bins_count == 0 {
