        }
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate space)
    score += 0.3 * (pr - mean_residual) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes are more reusable. Reward residuals that align with likely future
    // item classes (multiples of 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Dead-space penalty: tiny residuals are unusable (items >= 1, but
        // realistically small fragments waste capacity).
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    }

    // Lookahead coupling: does the residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Harmonic class match: exact or near-exact fit for next item.
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 25.0;
            } else if gap < 10 {
                score -= 12.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize mildly, more if residual
            // becomes dead space anyway.
            score += 5.0;
            if pr < 10 { score += 4.0; }
        }
        // Integer-division harmonic class of next item size.
        let cls = next_item_size / 20; // 0..5 coarse classes
        let resid_class = pr / 20;
        if resid_class >= cls && pr >= next_item_size {
            score -= 3.0; // same-or-coarser harmonic band
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0 * (open_bins_count as f64 / 8.0).min(2.0);

    // Early in the stream, be more willing to open bins (keep residuals
    // flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score += 20.0 * (1.0 - progress) - 15.0 * progress;
        // Still allow new bin if no open bin leaves a decent residual.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Mean-residual steering: if average residual is large, discourage
    // spreading; if small, encourage filling this bin.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below smallest item)
    // are pure waste -> heavy penalty.
    let dead_threshold: f64 = 9.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 12.0;
    }

    // Penalize leaving gaps that cannot fit the lookahead item (wasted for k=2)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + pr);
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few bins, allow spreading (favor new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    // (mean residual high but item large) or few bins open.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 15.0 * (1.0 - fragmentation) + 20.0 * (1.0 - progress);
        score += new_bin_bonus;
        // Opening new bin leaves full residual; penalize if many bins already open
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for bins whose residual deviates below mean (consolidate emptier space)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // scarcity-aware slack reward: when few bins can host next item,
            // preserving a tight chain matters more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // bonus for hosting next item twice (chain of two)
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // scarcity-weighted slack preservation (from best heuristic)
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 40.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // half-usable residual: mild extra discouragement early
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap residuals that can't host next item again
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            // extra pressure with many open bins late in the stream
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 500.0; // next item fits perfectly here
            } else if gap <= 5.0 {
                score -= 150.0;
            } else {
                // prefer leaving space the next item can actually use
                score -= 50.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item won't fit in this bin's leftover: penalize large dead space
            score += 0.3 * (pr - nxt);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // Penalize wasting a fresh bin on small items when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress;
        if item_size < 50 {
            score += 25.0;
        }
    }

    // Mild preference for more-filled bins among open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large dead space non-linearly: small residuals are hard to reuse.
    let dead = post_residual as f64;
    score += 0.35 * (dead / bin_capacity as f64).powf(2.0) * bin_capacity as f64;

    // Reward tight fits (small post_residual) — best-fit core with sharpening.
    score -= 12.0 * (1.0 - dead / bin_capacity as f64).powf(3.0);

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow here; penalize stranding this bin unless residual is tiny.
        if dead > 20.0 {
            score += 8.0 * (dead / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // or open-bin pool is congested / residuals are large.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        let time_pressure = progress.powf(0.5);
        score += 30.0 // base cost of opening a new bin
            - 20.0 * congestion.max(0.0)
            - 10.0 * time_pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is necessary
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidating space).
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Slight preference for many open bins being closed out early in the stream.
    if bin_residual < bin_capacity && open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity-aware slack reward (from best heuristic)
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            // bin can't host next item: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Relative-size scaled dead-space penalty (from best heuristic)
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            // Half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: tiny residuals are worth finishing
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Loose fit among many candidates
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        if post_residual < 2 * next_item_size {
            score += 0.8 * slack / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic coupling of post residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - x)) + 30.0 * x * x * (0.5 + progress);

    // Penalize large dead space more when many bins are open
    score += 0.05 * (open_bins_count as f64) * x * x * cap;

    // Reward tight fits (small post residual) especially when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Smooth lookahead coupling: penalize if post residual is slightly larger than next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = (x - nx).abs();
        score += 20.0 * diff * (1.0 - diff) * (1.0 - progress);
        // Reward if next item fits exactly into post residual
        let fit_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 15.0 * fit_next * nx * (1.0 - progress);
    }

    // Mild mean-residual anchoring: prefer bins close to mean (balance residuals)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * progress;

    // New-bin candidate: empty bin should only win when item is huge relative to mean residual
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 12.0 + 25.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common small sizes
    // (e.g. 10, 20, 25, 50) are more reusable; penalize "odd" dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are harmonic with typical item sizes.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    } else {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
        // Dead space: post_residual too small for any plausible item (1..100)
        if post_residual < 10 {
            score += (10.0 - pr) * 2.0; // unusable sliver
        }
        // Integer division threshold: post_residual in awkward mid-band
        let band = post_residual / 10; // 0..10
        if band >= 1 && band <= 3 {
            score += 5.0; // small leftover, hard to reuse
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0) * 0.5;
            if slack % 10 == 0 { score -= 2.0; }
        } else {
            // next item cannot fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count.min(5) as f64) * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap; // high => open bins nearly full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so we prefer existing bins unless they're poor fits
        score += 25.0;
        score -= crowding * 30.0;
        score -= progress * 10.0;
        if open_bins_count == 0 { score -= 50.0; }
        // If the item is large relative to capacity, starting fresh is safer
        if (item_size as f64) / cap > 0.6 { score -= 12.0; }
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score -= (cap - bin_residual as f64) * 0.05;

    // Mean residual coupling: when mean residual is high, be pickier about waste
    score += (mean_residual / cap) * (pr / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact-fill and lookahead structure.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
        }
    }

    // Perfect fill: huge reward.
    if post_residual == 0 {
        score -= 180.0;
    }

    // Penalize creating unusable dead space (scaled by remaining stream).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let rel = next_item_size as f64 / cap;
        score += (2.4 + 1.2 * rel) * post_residual as f64;
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 800.0 * dead * dead * (1.0 - progress);
        // Very small residuals (< half next item) are near-unusable.
        if (post_residual as f64) < 0.6 * next_item_size as f64 {
            score += 3.5 * (1.0 - progress) * (1.0 - post_residual as f64 / (0.6 * next_item_size as f64));
        }
    }

    // Reward residuals able to host the next item twice (chained fits).
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 3.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early-stream: prefer bins leaving moderately reusable residuals.
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual != next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= 6.0 + 0.9 * slack * scarcity * (1.0 - progress);
    } else if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Consolidation pressure: mild penalty per open bin.
    score += 0.06 * (bin_capacity - bin_residual) as f64;
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate handling: attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        let mean_tight = mean_residual / cap.max(1.0);
        let openness = 8.0 * (1.0 - mean_tight) - 6.0 * progress;
        score = 30.0 - scarcity - openness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        // Open a fresh bin when existing bins are mostly empty and stream is late.
        if open_bins_count > 4 && progress > 0.5 && mean_tight < 0.18 {
            score += 5.0 * (0.18 - mean_tight) * 10.0;
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Late-stream: waste matters more, but tiny residuals are still valuable.
    score += 2.0 * progress * (post_residual as f64 / cap);
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A residual below the smallest item (1) is impossible here, but gaps that
    // can only absorb tiny items waste the bin. Penalize post_residual in the
    // "dead zone" [1, 20] with a strong superlinear penalty.
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bins early in the stream or when mean residual is low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        score += (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward leaving that gap; otherwise penalize gaps close to next_item_size
    // being wasted.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            score -= 4.0; // gap still usable by next item
        } else {
            score += 5.0; // next item cannot use this gap
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

