pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus for perfect fit for the next item
        score -= 40.0 * (1.0 - diff / 100.0).max(0.0);
        // Extra jackpot for exact match
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize post_residual that can fit next item but wastefully large gap
        if post_residual >= next_item_size && post_residual > next_item_size {
            score += 0.3 * (post_residual - next_item_size) as f64;
        }
        // Penalize post_residual too small to fit next item (dead space for next step)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 20.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.4 * (mean_residual - post_residual as f64);

    // Penalize leaving large unusable residue relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill is great
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Late in stream: consolidate, prefer filling existing bins harder
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
