pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero.
    if post_residual > 0 {
        score -= 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);
    } else {
        // Perfect fill is highly desirable.
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 3.0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this bin strongly (chaining placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let chain_fit = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 10.0 + 12.0 * chain_fit;
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += 2.0 + 0.05 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor for the item. Make the empty bin slightly
    // unattractive by default so tight fits win, but attractive when the item
    // is large relative to typical residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 18.0 * tightness;
        // If many bins are open and mean residual is low, new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing
    // bins rather than spreading.
    score += 0.3 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps residuals balanced), unless a very tight fit exists.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be more willing to open bins (exploration);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with non-linear shaping.
    let mut score = pr as f64;

    // Smooth non-linear coupling: post_residual interacts with stream progress.
    // Early on, prefer tight fits (low post residual) strongly; later, tolerate slack.
    let progress_coupling = (x * x - 0.5 * x) * (1.0 - t) * 30.0
        + (x * x * x) * t * 40.0;
    score += progress_coupling;

    // Perfect fit bonus (smooth near-zero term).
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Dead-space penalty: residuals too small to fit typical future items.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = nxt - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 15.0 * g * g * (1.0 + t);
        } else {
            // Smooth reward when next item fits in this bin's residual.
            let f = (-gap / cap);
            score -= 10.0 * f / (1.0 + f);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * t);
    }

    // Mean residual alignment: prefer bins near the mean residual (smooth).
    let mr = mean_residual;
    let d = (pr - mr) / cap;
    score += 8.0 * d * d;

    // Slight penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05 * (1.0 - x);

    // New-bin candidate: empty bin gets a mild penalty so it's chosen only
    // when open bins would create large dead space.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Bands: (0, 10] dead, (10, 25] narrow, (25, 50] half, (50, 100] roomy.
    let dead = post_residual <= 10;
    let narrow = post_residual > 10 && post_residual <= 25;
    let half = post_residual > 25 && post_residual <= 50;
    let roomy = post_residual > 50;

    // Exact-fit / zero-residual is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty grows super-linearly for tiny unusable residuals.
    if dead {
        score += (post_residual as f64) * (post_residual as f64) * 2.0;
    }

    // Narrow band: good only if the next item can slot in.
    if narrow {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0; // chains nicely
        } else {
            score += 15.0; // stranded small gap
        }
    }

    // Half band: versatile residual, mild reward.
    if half {
        score -= 20.0;
        // modulo-10 class: residuals that are multiples of 10 align with item grids
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Roomy: wasteful unless the bin was nearly full before (good compaction).
    if roomy {
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Integer-division threshold: item size classes (harmonic octiles of capacity).
    let item_class = item_size / 10; // 0..=10 roughly
    let next_class = next_item_size / 10;
    // Reward placing big items into tight bins (class >= 6 into residual < 40)
    if item_class >= 6 && bin_residual < 40 {
        score -= 25.0;
    }
    // Penalize dumping small items into wide-open bins when other bins exist.
    if item_class <= 2 && roomy && open_bins_count > 1 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should lose unless everything else is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Prefer a new bin for very large items when few bins fit them at all.
        if item_class >= 7 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early stream: opening bins is cheaper (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Coupling with mean residual: placing into a bin below-mean residual
    // (i.e., fuller than average) is good packing.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Lookahead harmonic check: if next item exactly divides the post residual
    // (post_residual % next_item_size == 0), it's a perfect chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, shaped
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm) / cap * 4.0;

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity reward: slack worth more when few alternatives exist
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: burn off small residuals
    if progress > 0.7 && post_residual > 0.0 && post_residual <= 15.0 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0.0 && (post_residual as u32) < item_size * 3 / 2 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Loose fit with many competitors
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Overfit guard
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = (mean_residual / cap).max(0.001);
            if avg_fill < 0.18 {
                score += 50.0 * (0.18 - avg_fill);
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead gap that likely nothing can ever fill
    } else if post_residual == 0 {
        score -= 60.0; // perfect closure is excellent
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving a gap that the next item could have used but we waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap too small for the known next item
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0; // post gap nicely sized for the lookahead item
    }

    // Open-bins pressure: discourage scattering into many bins early/mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (1.0 - 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual is below average
    // (consume the small leftovers first, keep large residuals flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins fit badly.
    if bin_residual == bin_capacity {
        // Base mild penalty so a decent existing fit beats opening a new bin.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // Last-chance existing bin exists; new bin only if it's very tight already.
            score += 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
