            if (post - nxt) < 1.0 {
                score -= 8.0; // perfect chain
            }
        } else {
            score += (nxt - post).min(cap) * 0.15; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing bins are fragmented or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
