    // Penalize bins whose residual is far below the mean residual (fragmented bins).
    score += 0.3 * (mean_residual - pr).abs();

    // Lookahead: favor residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // less so early in the stream or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        score += 20.0 + 30.0 * crowding * (0.5 + 0.5 * progress);
    }

    // Mild preference to spread across fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits with mild non-linear shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Scarcity-aware slack reward: fewer competing bins -> reward keeping
            // a residual that still hosts the next item
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Two-item chain: residual can host next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: almost useless for next item
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are cheap to close out
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Deviation from mean residual penalized mildly
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Loose fits with many competitors are less attractive
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                    // Many open bins late: fresh bins are more acceptable
                    if progress > 0.6 && open_bins_count > 6 {
                        score -= 2.0 * ((open_bins_count as f64 / 20.0).min(2.0));
                    }
                    // Low average fill means open bins are wasted anyway
                    if avg_fill < 0.18 {
                        score -= 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residues are gold,
    // residues in the "dead zone" (just below small item sizes) are poison.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity classes: divide residual into 10 harmonic bands.
    let band = (post_residual * 10) / bin_capacity; // integer division class 0..9
    let band_bonus = match band {
        0 => -30.0, // nearly empty residual left -> excellent fit
        1 => -12.0,
        2 => 6.0,   // awkward mid-small dead space
        3 => 10.0,
        4 => 8.0,
        5 => 0.0,
        6 => -2.0,
        7 => -4.0,
        8 => -6.0,
        _ => -8.0,  // bin was almost empty anyway
    };
    score += band_bonus;

    // Modulo-10 arithmetic: residues divisible by 10 align with typical item sizes.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0;
    } else if m10 >= 7 {
        score += 4.0; // ragged residue, hard to fill
    }

    // Dead-zone penalty: residual that no plausible item (1..=100) fills efficiently.
    // A residual just above a "round" size wastes the difference.
    if post_residual > 0 && post_residual <= 15 {
        score += 14.0; // too small for most items, guaranteed waste
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap_f);
            // modulo harmony between next item and leftover
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / cap_f);
        }
    }

    // Last-chance rescue: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-ish, but prefer reusing open bins
    // when the fit is decent; make new bin attractive only when this placement is bad.
    if bin_residual == bin_capacity {
        score += 10.0; // base cost of opening a new bin
        // If many open bins exist with large mean residual, opening new bins is wasteful.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score += (mean_residual - 40.0) * 0.3;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / cap_f);

    // Tie-break toward bins tighter than average (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

