        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize creating more bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full / crowded.
        score += 40.0 + 6.0 * open_bins_count as f64;
        // But if mean residual is small (open bins nearly exhausted), opening is fine.
        score -= 0.8 * mean_residual;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
