pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect match: next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                // Partial reward scaled by how well the next item consumes the leftover.
                let fill_frac = next_item_size as f64 / post_residual as f64;
                score -= 10.0 + 20.0 * fill_frac;
            }
        } else {
            // Next item cannot use this leftover: penalize dead space relative to next size.
            let waste = post_residual as f64;
            score += 0.3 * waste.min(next_item_size as f64);
        }
    }

    // Penalize leaving residual far below the mean (creating unusable slivers),
    // but reward residual close to mean (balanced packing).
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.5 * (mean_residual - res);
    } else {
        score -= 0.1 * (res - mean_residual).min(50.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good existing options exist,
    // unless residual is tiny (dead space anyway).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score is its post_residual (= capacity - item_size).
        // Add penalty so we only open new bins when existing bins are truly bad.
        score += 15.0;
        // But if lookahead shows next item is large, new bin may be attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with fewer alternatives when residual is tight.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Scarcity-weighted slack reward: fewer fitting bins -> hoard slack less
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Two-item chain: residual hosts next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Over-just-fit penalty: barely past next item wastes little space but chains poorly
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: salvageable for smaller future items
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
                if pr < 0.6 * next_item_size as f64 {
                    score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
                }
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
            }
            // Low average fill pressure: fresh bin less harmful when bins are empty-ish
            if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is nearly dead space
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // fits well (poor fit ratio here) or when open bins are already congested.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.55;
        let congested = open_bins_count as f64 > 2.0 + mean_residual / 20.0;
        if poor_fit || congested {
            score -= 12.0;
        } else {
            score += 20.0; // discourage wasting a fresh bin on a decent fit
        }
        // Lookahead: if the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    } else {
        // Lookahead synergy: reward placements that leave room for the next item.
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 6.0;
            } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
                score += 5.0; // blocks next item without being fully used
            }
        }
    }

    // Time horizon: early in the stream, be conservative with open bins (favor
    // consolidation); late in the stream, tight fits dominate anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Global balance: penalize bins whose residual deviates far from the mean,
    // encouraging a homogeneous set of residuals that pack cleanly later.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for many open bins to discourage needless bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
