    let poly = prn * prn * (1.0 + progress) - prn * prn * prn * progress;
    score += 12.0 * poly * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses.
    let tight = 1.0 - prn;
    score -= 8.0 * tight * tight * (0.5 + progress);

    // Penalize dead space: residuals too small for typical future items.
    let dead = (prn * (1.0 - prn)).max(0.0); // peaks mid-range, small at extremes
    let unusable = if next_item_size > 0 {
        ((next_item_size as f64 - pr) / cap).clamp(0.0, 1.0)
    } else {
        0.0
    };
    score += 10.0 * unusable * (1.0 + dead) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * prn * 2.0;

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: neutral-ish baseline, penalized slightly so it is
    // chosen only when open bins would create large unusable residuals.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
