pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, or large enough for typical items) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 12.0; // clean class, easy to refill
    } else {
        // awkward remainder: penalize proportional to dead space
        let dead = pr % 10;
        score += dead as f64 * 1.5;
    }

    // Threshold classes on post_residual via integer division
    let class = pr / 20; // 0..5 harmonic band
    match class {
        0 => score -= 20.0,             // 0..19: nearly full, great
        1 => score += 6.0,              // 20..39: awkward small gap
        2 => score += 2.0,              // 40..59: moderate
        3 => score -= 3.0,              // 60..79: still useful
        _ => score += 10.0,             // 80+: wasteful placement
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact-fit chain bonus (harmonic divisibility)
            if pr % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // leftover too small for the next item: dead space risk
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0; // default cost of opening a new bin
        if post_residual > 70 {
            score -= 30.0; // huge item, fine to open fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mean-residual drift: prefer bins close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight early-stream preference for tight fits to seed good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

