        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin only when fit is bad.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
    score += 0.6 * pressure * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when existing fits are poor and mean residual is high.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.25 * mean_residual;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Mild stream-progression damping: tighten packing as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small leftover (<= 5)
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
        score -= 25.0;
    }

    // Next item cannot fit here -> dead space penalty scaled by dead space size
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable post_residual (dead space) more aggressively
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward tight fits relative to mean residual
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mr {
        score -= 8.0;
    } else if (post_residual as f64) > mr + 20.0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer existing bins unless nothing fits
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits, must open new bin
        } else {
            score += 40.0; // discourage opening new bin when one fits
        }
    }

    // Mild late-stream conservatism: fewer open bins -> slightly prefer reuse
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
