pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal leftover space.
    let mut score = post;

    // Non-linear polynomial penalty for awkward dead space: residuals near half
    // capacity are least reusable, very small residuals are nearly dead anyway.
    let x = post / cap; // in [0,1]
    let deadness = 4.0 * x * (1.0 - x); // peaks at x=0.5
    score += 12.0 * deadness * deadness;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tight = 1.0 - x;
    score -= 8.0 * tight * tight * (0.5 + progress);

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            let fit_q = 1.0 - gap / cap;
            score -= 10.0 * fit_q * fit_q;
        } else {
            // Penalize leaving a residual that barely misses the next item.
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins whose residual is below mean (compact them).
        score += 2.0 * (post - mean_residual) / cap;
    }

    // Mild penalty for spreading across many bins; encourages bin consolidation.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: opening a fresh bin should only win when no open bin
    // offers a decent fit. Penalize it, scaled by stream progress and item size.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress + item * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
