pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (10/20/25/50) are far more reusable than odd ones.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else {
        let mut harmonic_bonus = 0.0;
        if r % 10 == 0 { harmonic_bonus += 12.0; }
        if r % 20 == 0 { harmonic_bonus += 8.0; }
        if r % 25 == 0 { harmonic_bonus += 8.0; }
        if r % 50 == 0 { harmonic_bonus += 6.0; }
        // Small odd residuals are dead space: penalize non-harmonic slivers.
        let dead = if r < 10 && r % 10 != 0 { 15.0 } else { 0.0 };
        score += dead - harmonic_bonus;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Harmonic match between next item and residual classes
            let k = r / next_item_size.max(1);
            if r % next_item_size.max(1) == 0 {
                score -= 25.0 + 5.0 * k as f64; // exact division: excellent
            } else {
                score -= 8.0 + (r - next_item_size) as f64 * 0.15;
            }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot
            let over = (next_item_size - r) as f64;
            score += 4.0 + over * 0.10;
        }
    } else {
        // Last item: prefer zero residual strongly
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit is bad, otherwise prefer reuse.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > bin_residual - item_size { 1.0 } else { 0.0 };
        score = 40.0 - pressure * 10.0 + open_bins_count as f64 * 0.5;
        // Late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 8.0;
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight early-stream preference for compacting into few bins
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
