pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Scarcity-weighted slack reward (borrowed from best): fewer fitting bins => tighter preference
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score += 3.6 * slack - 14.4 * (1.0 - scarcity);
            } else if slack <= 20.0 {
                score += 1.1 * slack - 8.0 * (1.0 - scarcity);
            } else {
                score += 0.25 * slack - 2.0 * (1.0 - scarcity);
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits exactly two of next item
            if post_residual == 2 * next_item_size {
                score -= 2.5;
            } else if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            // Residual barely above next item: discourages awkward overhang
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                score += 0.8 * slack / n * 10.0;
            }
        } else {
            // Bin can't host next item: penalize unusable dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: slightly less hopeless
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // Very small relative to next item: extra early penalty
            if (post_residual as f64) < 0.6 * n {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * n));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Deviation from mean residual penalty
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Loose-fit competition penalty
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && ((post_residual - next_item_size) as f64) <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    if bin_residual >= next_item_size && (bin_residual - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    let crowd = if open_bins_count > 6 {
                        2.0 * (open_bins_count as f64 / 20.0).min(2.0)
                    } else {
                        0.0
                    };
                    score += pressure + late + crowd;
                    // Low average fill: open bins are wasting space, fresh bin acceptable
                    if avg_fill < 0.18 && open_bins_count > 4 {
                        score += 50.0 * (0.18 - avg_fill);
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // plausible future item (1..=100, but tiny gaps < ~12 are near-unusable).
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Medium dead space: gaps 12..40 are risky, penalize non-linearly,
    // but reward exact-ish fits (small post_residual already low base).
    if post_residual >= 12 && post_residual < 40 {
        score += (40.0 - post_residual as f64) * 0.8;
    }

    // Lookahead: if the next item fits into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + next_item_size as f64 * 0.3;
    }
    // If next item almost fits (within 5), mild reward.
    else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual + 5 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "junk" bin; filling it is good.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.35;
    } else {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // no good fit exists (post_residual here == capacity, so the dead-space
    // checks don't fire). Penalize it by default; the last-chance and
    // lookahead bonuses on real bins will beat it.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, opening fresh bins is fine.
        if progress > 0.85 {
            score -= 20.0;
        }
    }

    score
}

