            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount bins whose residual nearly vanishes.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Perfect-fit bonus: leave zero dead space.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize creating dead space too small for typical future items
    // (residual chunks that can't hold even a small item are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a chain — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
        } else {
            // Next item won't fit here: residual becomes dead space for the horizon.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are already open; make the empty bin less attractive as open_bins grows.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * (open_bins_count as f64).sqrt();
        // But if no bin fits well (large post residuals everywhere), allow opening.
        let avg_waste = mean_residual - (bin_capacity as f64 - mean_residual).max(0.0);
        if avg_waste > 0.5 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Global state: when mean residual is high, prefer bins that reduce spread
    // (balance residuals across bins for future flexibility).
    let balance = (bin_capacity as f64 - post_residual as f64 - mean_residual).abs();
    score += 0.15 * balance;

    // Time horizon: late in the stream, close out bins aggressively —
    // reward tight fits even more, penalize spreading across new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 25.0 * progress * (1.0 - tightness);
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // Mild preference for filling already-open bins to reduce active bin count.
    score += 0.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward (borrowed from best): slack is
            // valuable when few bins can host the next item
            score -= 1.4 * slack * scarcity * (1.0 - progress);
            // chain of two bonus
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // exact double chain jackpot
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // over-tight chain penalty when fit barely exceeds next item
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size.max(1) as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // usable fraction shaping: even a small leftover beats pure waste
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // half-usable residuals: mildly encourage
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // strongly discourage leaving unusable slivers
            if post_residual > 0 && pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: absorb residuals that are nearly dead for the current item
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            // crowding pressure late in stream
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress + 0.6 * progress * progress;
    score *= poly;

    // Penalize large dead space more than linearly (quadratic term)
    score += 4.0 * norm_pr * norm_pr * cap;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward leaving room for the next item
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (pr - n).abs();
        score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        if pr >= n {
            score -= 12.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += 0.05 * open_bins_count as f64 * norm_pr * cap;

    // Deviation from mean residual: prefer bins whose residual stays near the mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // New-bin candidate: neutral baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * progress - 0.15 * n;
    }

    score
}

