    // Residuals that are "dead" (small, hard to fill later) get penalized.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64; // unusable sliver
    }

    // Modulo class reward: residuals in classes that pair well with common item
    // sizes (multiples of 10, 20, 25) are favored.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 12.0,
        5 => 8.0,
        2 | 8 => 4.0,
        _ => 0.0,
