    score -= class_bonus;

    // Integer-division harmonic: post_residual / 10 gives number of "unit slots".
    // Reward bins whose slot count can absorb next_item_size cleanly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slots = post_residual / 10;
        let next_slots = next_item_size / 10;
        if slots >= next_slots {
