        let good_fit_exists = fitting_bins_count > 0 && post_residual <= 30;
        if !good_fit_exists || progress < 0.05 {
            score -= 18.0;
        } else {
            score += 30.0;
        }
    }

    // Mild preference for tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

