pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap below the minimum item size (1..100 unknown, assume worst small threshold)
    // is nearly worthless. Use a smooth penalty ramp for gaps below ~15.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        // Dead space: heavily penalize (invert value so tiny gaps score worse than large ones)
        score += (15.0 - gap) * 4.0;
    }

    // Perfect fit bonus: strongly reward filling the bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit bonus: reward using most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: discourage opening new bins when many bins are open,
    // encourage consolidating items into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (1.0 + progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin if item is big and would leave a useful large gap anyway
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    // (creates a bin that can host the next item too).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Penalize leaving a gap that the next item cannot use.
        score += gap * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth filling; if far above, deprioritize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
