pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling: tight fits are better, more so as stream progresses.
    let tightness = 1.0 - post / cap; // 1 = perfect fit, 0 = empty bin
    let tight_bonus = tightness * tightness * (20.0 + 40.0 * progress);
    score -= tight_bonus;

    // Penalize dead space that is too small to be useful, scaled by progress.
    let dead = if post > 0.0 && post < item_size as f64 { 1.0 } else { 0.0 };
    let small_space_penalty = post * (1.0 - post / cap) * (0.5 + 1.5 * progress);
    score += small_space_penalty * dead.max(small_space_penalty / (small_space_penalty + 1.0));

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 * (0.5 + progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // Deviation from mean residual: prefer bins near the mean to balance load.
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.01;
