pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions.
    // Residuals that are "harmonically useful" (multiples of common item sizes)
    // should be rewarded (subtract), dead-space residuals penalized (add).
    let cap_frac = (bin_capacity as f64) / 4.0; // 25.0 for C=100

    // Reward residuals that are multiples of 10 or 25 (classic item sizes)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Perfect fit is golden
    if post_residual == 0 {
        score -= 40.0;
    }
    // Dead space: post_residual below the minimum plausible item size (1..10 band)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Integer division thresholds: pair current post_residual with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: strong reward, scaled by slack quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + slack * 0.15;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0; // chained harmonic fit
            }
        } else {
            // next item cannot fit here; penalize by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // When many bins fit the item, prefer tighter (smaller post_residual) fits more
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.10 * ((fitting_bins_count - 1) as f64).min(3.0);
    }

    // Late in the stream, consolidate: penalize spreading across many open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && open_bins_count > 2 {
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    score -= (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no open bin is a good harmonic match.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if large_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 8.0 + mean_residual * 0.03;
        }
    }

    // Modulo-3 / modulo-7 harmonic texture on post_residual for tie-breaking
    score += (post_residual % 3) as f64 * 0.3;
    score -= (post_residual % 7) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
