pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is better (already baseline).

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: strong reward.
            score -= 18.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 4.0 + diff as f64 * 0.05;
        }
        // Perfect two-item fill bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize post_residual (baseline handles it), slight extra tightening.
        score -= 2.0;
    }

    // Penalize dead space that no plausible item can use (min item size 1, but small slivers are bad).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Relative to mean residual: prefer bins that are more filled than average
    // (packing into tight bins keeps many loose bins available).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 2.0;
    }

    // Early in stream, be slightly more willing to open bins (build diversity);
    // late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity-aware slack reward: when few bins can host the next item,
            // favor bins whose residual stays usable for it
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            // bin can't host next item: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if (pr) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // Relative-size weighted dead-space penalty (from best heuristic)
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: tiny residuals are worth finishing
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Loose fit among many candidates
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        if post_residual < 2 * next_item_size {
            score += 0.8 * slack / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
                // Open a fresh bin when existing residuals are all tiny/unusable
                if open_bins_count > 3 && avg_fill > 0.75 && progress > 0.35 {
                    score -= 4.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let nrel = next_item_size as f64 / cap.max(1.0);
            if slack <= 4.0 {
                score += 3.6 * slack; // graded penalty grows with slack (borrowed from best)
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Scarcity-weighted slack reward: fewer competing bins -> value tight chains more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity {
                if post_residual % next_item_size.max(1) == 0 {
                    score -= 6.0;
                }
                if post_residual == 2 * next_item_size {
                    score -= 1.5;
                }
                // Multi-item hosting potential: residual covers 2+ next items
                if post_residual >= 2 * next_item_size {
                    score -= 3.0;
                }
            }
            // Overshoot penalty for residuals just above next item (near-wasted space)
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size.max(1) as f64 * 10.0;
            }
            let _ = nrel;
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: slightly less hopeless
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // Severely undersized residual: strong penalty graded by how far below
            if (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress)
                    * (1.0 - (post_residual as f64 / (0.6 * next_item_size as f64)));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    // Pressure to avoid new bins, stronger late and with many open bins
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    let crowd = if progress > 0.6 && open_bins_count > 6 {
                        2.0 * (open_bins_count as f64 / 20.0).min(2.0)
                    } else {
                        0.0
                    };
                    score += pressure + late + crowd;
                    // Fragmented mean residual: opening a fresh bin is less harmful
                    if avg_fill < 0.18 && progress > 0.5 && open_bins_count > 4 {
                        score -= 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Waste of a residual that could have been shaped for the next item.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // If next item is large, avoid leaving large-ish residuals that fragment.
        if next_item_size > 50 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Prefer filling already-open bins over opening new ones, more so late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by how many bins are open and progress.
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 10.0 + 15.0 * progress;
    }

    // Global state: if mean residual is high, prefer using bins with below-average residual
    // (consolidate fragmentation); if mean residual is low, keep spread.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Slight preference for bins whose residual is close to item (best-fit flavor)
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, mildly
    let mut score = pr as f64;

    // Non-linear coupling: quadratic/quartic shaping of residual against stream progress.
    // Early in stream: prefer filling bins tightly (low post_residual favored strongly).
    // Late in stream: tolerate larger residuals slightly to keep bins reusable.
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    score += 30.0 * w_early * norm_pr * norm_pr;
    score -= 25.0 * w_late * norm_pr * (1.0 - norm_pr);

    // Perfect fit reward: smooth bump around near-zero residual
    let fit_bump = (-norm_pr * 8.0).exp();
    score -= 40.0 * fit_bump;

    // Dead-space penalty: residual too small for typical future items
    // smooth logistic penalty when post_residual is small but nonzero
    let dead = 1.0 / (1.0 + (-(norm_pr - 0.15) * 25.0).exp());
    score += 20.0 * dead * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits in post_residual, reward; smooth gaussian
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let fit_next = (-gap * gap / (2.0 * 15.0 * 15.0)).exp();
        score -= 18.0 * fit_next;
        // penalize if next item barely misses
        let near_miss = (-(gap - 10.0f64).abs() * 0.15).exp();
        score += 8.0 * near_miss * w_early;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.55;
        // cheaper to open new bin early in stream
        score -= 30.0 * (1.0 - progress);
        // expensive when many bins already open and residual mean is low (good packing)
        score += 12.0 * (open_bins_count as f64).ln();
        score += 20.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
