pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space penalty grows for residuals
    // that are hard to fill (small odd / awkward classes).
    let pr = post_residual;
    let class = pr % 10;
    let awkward = match class {
        0 => 0.0,                       // perfectly harmonic, easy reuse
        1 | 2 | 3 => 6.0,               // tiny slivers -> near-dead space
        4 | 5 | 6 => 2.0,
        _ => 4.0,
    };
    score += awkward;

    // Penalize residuals below the smallest possible item (dead space).
    if pr < 10 {
        score += 40.0;
    } else if pr < 20 {
        score += 15.0;
    }

    // Integer-division thresholds: reward near-perfect fits.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 - 0.3 * slack;
    }
    // If next item cannot fit this bin, mild penalty proportional to how
    // badly it misses (wasted pairing opportunity).
    if next_item_size > pr && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many alternatives -> slight penalty to prefer tighter bins.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., a very full bin) is good; being above mean is wasteful.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev.max(0.0) - 0.04 * (-dev).max(0.0);

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (pr <= 10) as i32 as f64;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, but relax penalty if this item is huge
        // relative to capacity or the open bins are mostly full.
        let huge = (item_size as f64 / bin_capacity as f64) > 0.7;
        let tight = mean_residual < 15.0;
        score += if huge || tight { 8.0 } else { 45.0 };
        // Late in stream, a fresh bin is less costly.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty for residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // near-half-dead residuals: discourage leaving unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // residual just above half of next item: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap residuals that can't host a plausible follow-up
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // wasteful when open bins are mostly empty
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

