    if post_residual == 0 {
        score -= 100.0;
    }

    // Reusability bonus: leftover space that can still hold typical items.
    if post_residual >= 50 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones; with few open bins, allow spreading.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to remaining stream, or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 60.0 + open_bins_count as f64 * 5.0;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is more acceptable.
        new_bin_penalty -= mean_residual * 0.5;
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size >= 70 {
            new_bin_penalty -= 25.0;
        }
        // Late in the stream, avoid spawning bins with large future waste.
        new_bin_penalty += progress * 20.0;
        score += new_bin_penalty.max(0.0);
    }

    // Lookahead synergy: if placing here leaves exactly enough room for the
    // next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score -= 20.0;
    }

    score
}

