    // Mild time-dependent exploration: early stream favors tight fits, later favors balance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

