                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;

    // Penalize residuals that fall into "dead" classes: too small to be useful
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 50.0; // tiny dead space is bad
    } else if post_residual < quarter as u32 {
        score += 20.0 * (quarter - post) / quarter;
    } else {
        // Larger residuals are useful; reward them mildly
        score -= 10.0 * (post / cap);
    }

    // Modulo arithmetic on post_residual: harmonically "aligned" residuals
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 15.0; // residual aligned to decade is reusable
    } else {
        score += 2.0 * harmonic as f64; // misalignment penalty
    }

    // Integer division threshold classes of post_residual
    let class = post_residual / 10; // 0..10 classes
    score -= 3.0 * class as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // reward proportional to how much next item consumes of post_residual
            score -= 40.0 * (nxt / post);
            // modulo harmony between next item and post residual
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 {
                score -= 25.0;
            } else {
                score += (diff % 10) as f64;
            }
        } else {
            // next item cannot fit here: penalize slightly
            score += 8.0;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a tight fit relative to others
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a new bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap - item_size as f64; // its post_residual
        score += 60.0; // inherent opening penalty
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        } else if next_item_size > 0 && next_item_size as f64 >= post {
