        score -= 20.0 * progress * (post / cap); // exploit tight fits later
    }

    // Mild penalty for bin proliferation
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: prefer placing into bins whose residual deviates favorably
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
