pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Partial lookahead reward: next item still fits after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }

    // Penalize creating dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize bins far below mean residual (poorly utilized bin)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Mild penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
        // But allow opening a new bin if the item is large and would leave a bad gap
        if item_size >= 60 && post_residual < 15 {
            score -= 35.0;
        }
    }

    // Reward tight fits (small post residual relative to capacity)
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 8.0;

    // Reward perfect fit
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits after placement: good chaining
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 * (miss / 100.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins below mean residual (keep residuals balanced)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, prefer conserving space (favor tighter packs);
    // late in stream, just close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        score = 45.0 + 40.0 * (1.0 - progress);
        // If this is the only fitting option, opening is acceptable
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If next item is large and current item is small, deferring may help
        if next_item_size > 0 && next_item_size > item_size && item_size < 30 {
            score -= 10.0;
        }
    }

    // Slight penalty for proliferating open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

