        }
    }

    // Slight penalty for proliferation of open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: discourage unless residuals are poor
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (mean_residual / cap).min(1.0);
