    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // for common item sizes (mod 10 classes), penalize awkward dead space.
    let pr_mod = post_residual % 10;
    let friendly: f64 = match pr_mod {
        0 => 1.0,
        5 => 0.6,
        2 | 8 => 0.3,
        4 | 6 => 0.15,
        _ => 0.0,
    };
    score -= 40.0 * friendly;

