    // unknown, but treat < 12 as likely waste) yet nonzero.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12 - post_residual) as f64;
    }

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // reward small gaps after next item, penalize large leftover
            score -= 80.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += 20.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Integer-division threshold on post_residual thirds of capacity.
    let third = (post_residual * 3) / bin_capacity;
    score -= 15.0 * third as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 - 70.0 * tightness - 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
    }

    // Fraction-of-capacity residual: prefer residuals that are large fractions
    // usable later (keep bins flexible), slight reward for high residual fraction.
    score -= 25.0 * (post_residual as f64 / cap);

    // Mild preference to keep number of open bins low when many are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Mean-residual alignment: bins far from mean residual get slight penalty.
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Progress-based tightening: later in stream, be greedier about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
