        score -= 15.0;
    }

    // Reward leaving room for the lookahead item when it would fit exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 25.0 - 1.5 * gap as f64;
        } else {
            score += 0.05 * (gap as f64 - 10.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins; encourage new bin only when few open.
    let open_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate,
        // but soften when this bin's residual would be dead space anyway.
        score += 10.0 + 12.0 * open_pressure;
        if post_residual > 85 {
            score -= 8.0; // fresh bin keeps large residual, acceptable
        }
