        // Existing bin: reward reuse, scaled by pressure to close bins.
        score -= 6.0 + 2.0 * open_pressure;
        // Bonus for filling below mean residual (tightening the fleet).
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
