    // --- 2-step lookahead: reward placements that leave room for the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Perfect chaining: next item fits exactly-ish in the new residual.
            let chain_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 30.0 * chain_quality;
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // the leftover dead space exceeds what's usable.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * dead * dead;
        }
        // Coupling with mean residual state: if the bin's post-residual is
        // far below the fleet mean, it's a good "sink" for this item.
        let mean_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 10.0 * mean_gap;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit (i.e., when the item is large relative to residuals).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin generally, more when item is small
        // (small items should go into existing residual space).
        score += 35.0 * (1.0 - fit_ratio);
        // But if many bins are open and residuals are fragmented, opening
        // a fresh bin for a large item is less bad.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress * fit_ratio;
        // If next item is also large, a fresh bin can host both -> reward.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

