    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, shaped
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm) / cap * 4.0;

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty (borrowed from best: quadratic, lookahead-driven)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 800.0 * dead * dead * (1.0 - progress);
    }

    // Lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity reward: slack worth more when few alternatives exist
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            // Penalize residuals that can't hold next item, scaled by residual size
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: burn off small residuals
    if progress > 0.7 && post_residual > 0.0 && post_residual <= 15.0 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0.0 && (post_residual as u32) < item_size * 3 / 2 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Loose fit with many competitors
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Overfit guard
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = (mean_residual / cap).max(0.001);
            if avg_fill < 0.18 {
                score += 50.0 * (0.18 - avg_fill);
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "friendly"
    // residue classes (multiples of common small item sizes) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit, best outcome
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr <= 9 {
        25.0 // tiny dead space, nearly unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: how many "typical" small items fit.
    let slots = pr / 10;
    score -= slots as f64 * 2.5;

    // Lookahead coupling: does next_item_size divide or fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by how cleanly it fits.
            let slack = pr - next_item_size;
            score -= 15.0;
            if slack % 10 == 0 { score -= 6.0; }
            if slack == 0 { score -= 10.0; }
        } else {
            // Next item cannot use this bin's residual: penalize leftover size mismatch.
            let mismatch = ((pr as i64 - next_item_size as i64).unsigned_abs()) as f64;
            score += mismatch * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // But if existing bins would leave nasty residue, new bin is less bad.
        let residue_ugly = (bin_residual - item_size) % 10 != 0 && (bin_residual - item_size) < 10;
        if residue_ugly { score -= 10.0; }
    }

    // Mean-residual coupling: prefer bins deviating favorably from the mean
    // (pack into below-average-residual bins to consolidate fullness).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Modulo-3 class of item_size: coarse harmonic tier adjustment.
    score += (item_size % 3) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Fine-grained slack shaping (combined with lookahead chain bonus)
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Multi-item chain: residual can host two next items exactly
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
                if post_residual == 2 * next_item_size {
                    score -= 1.5;
                }
            }
            // Scarcity-coupled slack reward (borrowed from best)
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 40.0 * dead_rel * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residuals: barely below next item — extra penalty, graded
            if pr > 0.5 * next_item_size as f64 {
                score += 2.0 * (1.0 - progress) + 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    if post_residual == 0 {
        score -= 180.0;
    }

    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate decision (combined logic)
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if fitting_bins_count > 0 && open_bins_count > 2 {
                    if post_residual >= next_item_size && (post_residual - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    // Low average fill: fresh bins are cheap to open
                    if avg_fill < 0.18 && open_bins_count > 4 && progress > 0.5 {
                        score += 5.0 * (0.18 - avg_fill) * 10.0;
                    } else if progress > 0.6 && open_bins_count > 6 {
                        score += 2.0 + 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                    }
                    score += pressure + late;
                }
            }
        }
    }

    score += 0.06 * (bin_capacity - bin_residual) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
