pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Very tight fit reward (nearly perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, scaled by pressure.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 8.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Open-bin pressure: prefer filling existing crowded bins.
    score += 0.5 * open_bins_count as f64;

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize if next item nearly fits, leaving awkward choice.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    }

    // Prefer bins below mean residual (fill the emptiest-fitting bins last).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 45.0; // perfect 2-chain: item + next item fill bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / nxt).min(1.0);
        }
        // mild bonus if post_residual can hold next item at all
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // last item: pure tightness packing
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Exact-fill reward for the current item
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare residual against mean residual of open bins: keep residual near mean to preserve flexibility
    let res = post_residual as f64;
    score += 0.15 * (res - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in stream: keep bins flexible (avoid committing to near-full bins too fast)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.05 * res;
    }

    // New-bin candidate: only attractive when no good fit exists (large dead space would result elsewhere)
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so decent fits in open bins win
        score += 10.0;
        // but if item is large and would leave open bins with tiny residuals, opening fresh helps
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that is hard to fill later
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * (dead / 10.0).powi(2);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size as u32 {
            // this placement blocks the next item from using this bin; mild penalty
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).powi(2);
        // open new bin when mean residual across open bins is small relative to item
        let appeal = 55.0 - 90.0 * crowdedness - 25.0 * progress + 20.0 * pressure;
        score += appeal;
        // avoid bin proliferation early in the stream
        score += 0.6 * open_bins_count as f64;
    }

    // Mild preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
