pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack
    // since remaining items are few and a wasted bin is the bigger cost.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 0.5;
    score += 40.0 * poly;

    // Reward exact or near-exact fits with a smooth quadratic decay.
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item,
    // smoothly weighted by how close the next item is to the post residual.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 12.0 * gap * (0.5 + 0.5 * progress);
        // Reward residuals that still accommodate the next item comfortably.
        let room = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * room.max(0.0) * room.max(0.0) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    // (fragmentation pressure), smoothed non-linearly.
    let frag = (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).max(0.0);
    score += 3.0 * frag * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small integers capture
    // "usable leftover" structure (e.g. leftover that matches common item sizes).
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward leftovers that are multiples of 10 (common item granularity)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else {
        score += 2.0;
    }

    // Reward leftovers that are multiples of 5 as secondary harmonic
    if pr % 5 == 0 && pr > 0 {
        score -= 2.5;
    }

    // Dead-space penalty: tiny leftovers that no item (>=1) can pair with later
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Integer-division threshold on post_residual: leftovers that can host
    // a "medium" item (<= half capacity) are more valuable
    if pr >= bin_capacity / 2 {
        score -= 4.0;
    }

    // Lookahead coupling: does the leftover exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // leftover too small for next item: penalize by the gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic: next item size residue classes
        if next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin gives a tight fit; make empty bin moderately unattractive
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if stream is early, allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer fuller bins relative to capacity fraction
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 5.0;

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small tie-breaker by step to diversify exploration deterministically
    let harmonic = ((step_index % 7) as f64) * 0.01;
    score += harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward (borrowed from best heuristic)
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two bonus
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // over-slack penalty when just past next item
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // near-half-dead residuals: discourage unusable slivers
            if post_residual > 0 && pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // half-usable residuals slightly less bad
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream snap of residual just below item's next-fit window
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
