    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 25 { 0.6 } else { 0.0 };
        score += 30.0 * dead;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Even better if next item fills further.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual in existing bins) or few bins are open.
    if bin_residual == bin_capacity {
        let worst_fit = post_residual as f64; // equals bin_capacity - item_size here
        score = worst_fit + 40.0 - 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - t);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If mean residual across open bins is large, prefer using existing bins.
        score += 0.5 * mean_residual;
        return score;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight time pressure: later in stream, consolidate more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * t * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (lower = tighter fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: waste penalty grows super-linearly as stream progresses
    let coupling = prn * prn * (1.0 + 2.0 * p) - prn * p * (1.0 - p);
    score += coupling * cap * 0.6;

    // Perfect fit reward (smooth gaussian-like bump around pr=0)
    score -= 12.0 * (-prn * 8.0).exp();

    // Reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = prn * cap >= nxt;
        let closeness = 1.0 - ((prn * cap - nxt) / cap).abs();
        if fit_next {
            score -= 6.0 * closeness * closeness;
        } else {
            score += 4.0 * prn * prn;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins have slack, smoothly
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let slack = mean_residual / cap;
        score += 8.0 + 10.0 * slack * (1.0 + p);
        score -= (open_bins_count as f64).ln() * 2.0;
    } else {
        // Favor bins below mean residual (consolidate waste)
        score += 0.05 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    let r = post_residual;
    let m2 = (r % 2) as f64;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;

    // Penalize residues that are "dead" (small nonzero leftovers)
    if r > 0 && r < 10 {
        score += 30.0 - r as f64; // tiny dead space is bad
    }

    // Reward residuals that are harmonic multiples (50, 25, 20, 10)
    let harmonic_bonus = if r == 0 { 60.0 }
        else if r % 50 == 0 { 40.0 }
        else if r % 25 == 0 { 25.0 }
        else if r % 20 == 0 { 20.0 }
        else if r % 10 == 0 { 10.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Odd/awkward residues slightly penalized
    score += 0.3 * m2 + 0.4 * m5 + 0.5 * m10 + 0.6 * m25;

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size < r {
            score -= 10.0 * (next_item_size as f64 / r as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
        if post_residual < 10 { score -= 15.0; } // near-perfect fill
    } else if fitting_bins_count > 2 {
        // Many options: be pickier about wasted space
        score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate: neutral-ish but slightly worse than good fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // Open a new bin only if open bins are crowded
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Progression: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * harmonic_bonus / 60.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Scarcity-aware slack reward (borrowed): fewer competing bins -> tighter choice matters more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Multi-fit residual: can host next item twice or more
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            // Bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Very dead residual (less than 60% of next item): extra penalty early
            if pr < 0.6 * nxt {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * nxt));
            }
            // Half-usable residual: slightly less bad early
            if pr > nxt / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small leftovers are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
                // Many open bins with low average fill: opening a new bin is less harmful
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score -= 5.0 * (0.18 - avg_fill) * 10.0;
                }
                if progress > 0.6 && open_bins_count > 6 {
                    score -= 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

