        score -= 200.0;
    }

    // Tight-fit reward: small dead space is good
    if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let lookahead_waste = post_residual - next_item_size;
            // Reward proportional to how well next item fits after this placement
            score -= 60.0 * (1.0 - (lookahead_waste as f64 / bin_capacity as f64)).powi(3);
            // Extra reward if after both placements the bin is nearly full
            if lookahead_waste <= 5 {
                score -= 50.0;
            }
        } else {
            // Next item cannot follow into this bin; penalize more if it leaves big dead space
            score += 20.0 + 0.5 * (post_residual as f64 - (bin_capacity - next_item_size) as f64).abs();
        }
