        score += (post_residual as f64 / item_size as f64) * 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Many fitting bins: mild penalty for using a scarce-resource bin poorly.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward large residuals.
            if post_residual > 0 && post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Global state: prefer filling bins when mean residual is high (bins are fragmented).
    let mr_gap = (mean_residual - post_residual as f64).abs();
    score -= 3.0 * mean_residual / bin_capacity as f64;
    score += 0.5 * mr_gap / bin_capacity as f64 * (open_bins_count as f64).sqrt();

    // Time horizon: early on, be conservative (keep bins open); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 * (1.0 - 0.15 * desperation)
            - 20.0 * desperation
            + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
