pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly damped by progress
    let mut score = pr * (1.0 - 0.3 * progress);

    // Non-linear coupling: quadratic waste penalty grows as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits via smooth cubic decay of post_residual
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Dead-space term: residual too small for typical future items
    let dead = (1.0 - norm_pr * 1.6).max(0.0);
    score += 30.0 * dead * dead;

    // Lookahead: if next item fits remaining residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 20.0 * fits_next * (1.0 - gap).powi(2);
        score += 10.0 * (1.0 - fits_next) * norm_pr;
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin when early, reward when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        score += 2.0 * open_bins_count as f64 * (mean_residual / cap - 0.5).abs();
    }

    // Mean residual alignment: prefer bins near the mean residual state
    score += 5.0 * ((pr - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual classes via modulo arithmetic
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Harmonic class: how many "typical" items (>=10) could still fit
        let slots = pr / 10;
        match slots {
            0 => score -= 150.0,           // dead space < 10, essentially closed
            1 => score -= 40.0,            // small but usable slot
            2 => score -= 10.0,
            3 => score -= 2.0,
            _ => {}                        // large residual: keep base penalty
        }
        // Non-linear coupling: penalize residuals in awkward modulo classes
        let m = pr % 10;
        if m != 0 {
            score += (10 - m) as f64 * 0.8; // non-multiple of 10 is harder to fill
        }
    }

    // Lookahead: bonus if the next item exactly fits the post-residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave big residual
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 120.0 + (open_bins_count as f64).sqrt() * 15.0;
        // if current open bins have small mean residual, opening new is cheaper
        score -= mean_residual * 1.5;
    }

    // Progress-based scaling: tighten criteria late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
