pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual below the minimum item size (1..100 unknown, assume small threshold ~10)
    // is pure dead space; amplify its cost super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else {
        // Mild convex penalty on leftover to prefer tight fits.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into post_residual,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate (empty bin): apply a fixed opening cost so we only
    // open when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin fits comfortably (large dead space everywhere),
        // opening is less penalized as the stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 35.0 + 10.0 * progress;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, shaped
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm) / cap * 4.0;

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty (sharpened: quadratic ramp on unusable space)
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity reward: slack worth more when few alternatives exist
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
            // COMBINED: rel-weighted dead residual penalty from best heuristic
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: burn off small residuals
    if progress > 0.7 && post_residual > 0.0 && post_residual <= 15.0 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0.0 && (post_residual as u32) < item_size * 3 / 2 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Loose fit with many competitors
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }

    // Overfit guard
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
        }
        if open_bins_count > 4 && progress > 0.5 {
            let avg_fill = (mean_residual / cap).max(0.001);
            if avg_fill < 0.18 {
                score += 50.0 * (0.18 - avg_fill);
            }
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

