pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Perfect chain: this item plus next exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 15.0 * (1.0 - tight);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9
            + 10.0 * (open_bins_count as f64).ln().max(0.0)
            - (mean_residual / (bin_capacity as f64)) * 20.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    } else {
        // Prefer bins below mean residual (fill emptier bins first).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - tight);

    // Fragmentation penalty: leaving residuals that fit nothing typical.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
