    if bin_residual == bin_capacity {
        score += 15.0 - progress * 10.0 + mean_residual * 0.05;
    }

    // Coupling with mean residual across open bins.
    score += (mean_residual - pr) * 0.1;

    // Non-linear penalty for creating very small unusable residuals, smoothed.
    let small = (1.0 - (pr / cap)).max(0.0);
    score += (1.0 - small * small) * (pr / cap) * (pr / cap) * 5.0;

