    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    // Crowding: more open bins -> more reluctance to add another
                    let crowd = 2.0 * (open_bins_count as f64 / 20.0).min(2.0) * progress;
                    score += pressure + late + crowd;
                }
                // Sparse-fill guard: if open bins are nearly empty, hesitate less
                if avg_fill < 0.18 {
                    score -= 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "divisible" the leftover space is
    // into plausible future item sizes (items are 1..100, but common classes matter).
    let pr = post_residual as i64;
    if pr > 0 {
        // Residuals that are multiples of small harmonics are more reusable.
        let mut harmony: f64 = 0.0;
        if pr % 10 == 0 { harmony += 1.5; }
        if pr % 20 == 0 { harmony += 1.0; }
        if pr % 25 == 0 { harmony += 0.8; }
        if pr % 50 == 0 { harmony += 1.2; }
        score -= harmony;
    }

    // Dead space: leftover that is too small for the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Prefer leaving room the next item can use; penalize leftover modulo mismatch.
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
            if gap > 0.0 && (post_residual % next_item_size.max(1)) == 0 {
                score -= 10.0; // next item tiles the leftover harmonically
            }
        } else {
            // Next item won't fit here; slightly reward tight fits now.
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins relative to capacity (integer-division thresholds).
    let fill_class = (bin_residual * 4) / bin_capacity; // 0..4 quartile of used space
    score -= fill_class as f64 * 6.0;

    // Early in the stream, allow opening bins to build a diverse residual portfolio;
    // late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += progress * 40.0 - 15.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Penalize bins far below the mean residual (fragmented portfolio) mildly.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100, but
    // conservatively assume ~10) can use are "dead" — penalize them hard.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // If this bin is the only fitting bin, strongly favor using it (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // existing fits would create dead space or the fit is very loose.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so it only wins on bad alternatives.
        score += 45.0 + 2.5 * open_bins_count as f64;
        // But if lookahead item would pair with typical leftovers, slight relief.
        if next_item_size > 0 && next_item_size <= 90 {
            score -= 5.0;
