    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // If next item could fit in post_residual, mild reward.
    else if next_item_size > 0 && next_item_size < post_residual {
        score -= 10.0;
    }
    // If next item cannot fit in post_residual but this bin's fit was loose,
    // penalize leaving a stranded gap.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the
    // mean (consuming the emptier / more fragmented bins first).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
