}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor minimal post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how well next item fills the remaining space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item cannot use the leftover space; penalize large leftovers
            // that are likely dead space for the upcoming item.
            score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is poor (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // If item fills a fresh bin well, opening is more attractive.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill_ratio;
        // With many open bins, prefer consolidating into existing ones.
        score += open_bins_count as f64 * 1.5;
        // If the current bin would leave a big unusable gap, opening a new
        // bin becomes relatively better.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0; // item nearly fills any bin; new bin is fine
        }
    }

    // Penalize wasting space in a bin relative to the average residual state:
    // placing an item that leaves much more residual than the mean suggests
    // fragmentation.
    if (post_residual as f64) > mean_residual * 1.3 && bin_residual != bin_capacity {
        score += 3.0;
    }

    // Time-horizon modulation: early in the stream, be conservative (favor
    // tight fits even more); late in the stream, allow more flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty on wasted space (quadratic coupling with progress)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: item filling most of the bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Lookahead coupling: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 20.0 * (1.0 - pr / cap) * (0.5 + progress);
        } else {
            score += 10.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins when mean residual is high
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Mild preference toward bins near mean residual (balance)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via non-linear post-residual penalty.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Harmonic class of post_residual: residues divisible by common item
    // granularity (e.g. 10) are more reusable than odd residues.
    let class = post_residual / 10;
    score -= 8.0 * class as f64;
    let rem = (post_residual % 10) as f64;
    score += 2.0 * rem;

    // Dead-space cliff: very small post_residual is excellent (near-full bin).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large relative to capacity or no good fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0
            - 0.2 * (item_size as f64)
            - 10.0 * progress;
        // If many bins are open, spreading load is less attractive.
        score += 0.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more valuable.
        score -= 0.15 * next_item_size as f64;
    }

    // Lookahead coupling: if next item exactly fills the post-residual,
    // reward this bin strongly (perfect 2-item packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here too: mild reward scaled by how well it fits.
        let waste = (post_residual - next_item_size) as f64;
        score -= 10.0 - waste * 0.2;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leftover dead space.
        score += 5.0 + (post_residual as f64) * 0.1;
    }

    // Prefer bins below mean residual (consolidating emptier bins keeps
    // fuller bins free for large future items).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream progress coupling: later waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // chain of two
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // scarcity-aware slack reward (borrowed from best)
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // over-fit penalty when post_residual barely exceeds next item but is < 2x
            if post_residual > next_item_size && post_residual < 2 * next_item_size && fitting_bins_count > 2 {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            // amplified dead-space shaping (from best heuristic)
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // near-half-dead residuals: discourage unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // sliver just above half of next item: still mostly wasted
            if post_residual > next_item_size / 2 && post_residual < next_item_size {
                score += 2.0 * (1.0 - progress);
            }
            // usable-residual shaping
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
        }
