    // Penalize creating tiny unusable dead space (post_residual < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

