    // New-bin candidate handling: opening a new bin is penalized, more so early on
    // and when many bins are already open with slack space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (item large relative to mean residual), soften penalty.
        if item_size as f64 > mean_residual {
            score -= 35.0;
        }
    }

    // Prefer bins with residual below mean (denser bins) to consolidate slack.
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0);
        // Mild preference for already-open bins vs. fragmenting many bins.
        score -= 3.0;
    }

    // Time-horizon coupling: late in stream, prioritize immediate compaction.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;

    score
}

