pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Base: prefer small post_residual (tight fit), normalized.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, dead space becomes costlier (fewer chances to fill it).
    let poly = pr / cap;
    let coupling = poly * poly * (0.5 + progress) + poly * progress * progress;
    score += 1.5 * coupling;

    // Reward near-perfect fits (small pr) more strongly as stream progresses.
    let tightness = (1.0 - poly).powi(3);
    score -= tightness * (0.5 + 1.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item but almost could
    // (wasted opportunity), reward if next item fits well in the residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits: reward proportionally to how well it fills residual
