    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover is
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward
        score -= 200.0;
    } else {
        // Class by modulo arithmetic on residual: multiples of common item sizes
        let class_bonus = match pr % 10 {
            0 => 40.0,           // residual aligns with decade grid
            5 => 20.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Small unusable residuals are dead space: penalize heavily
        if pr < 10 {
            score += 60.0;
        }

        // Does the next item fit into the post-residual? Big reward (chaining)
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 120.0; // exact chain
            } else if next_item_size <= pr {
                // harmonic fraction: how much of next item the residual covers
                let frac = pr as f64 / next_item_size as f64;
                score -= 30.0 * frac;
            } else {
                // next item cannot use this residual: mild penalty scaled by residual waste
                score += 0.05 * pr as f64;
            }
        }
    }

    // Tightness reward: fraction of bin used by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 30.0 * fill_frac;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good fits exist
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(3.0);
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins with below-average residual (consolidate waste)
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild pressure to use many open bins rather than proliferate
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

