    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 60.0; // unusable sliver
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residuals that still accommodate the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // gap created that cannot fit the next known item: dead space pressure
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
        // bonus if post_residual fits next item snugly
        let snug = (post_residual as f64 - next_item_size as f64).abs();
        score -= 10.0 / (1.0 + snug);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, allow consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates from mean residual in a
    // "fillable" direction (large residual bins are easier to fill later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 / (1.0 + dev);

    // New-bin candidate penalty: only open a new bin if forced
    // (no good existing fit / huge item relative to residuals).
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if item is large and mean residuals are small, new bin is fine
        score -= 0.4 * item_size as f64;
