        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 20.0; // pairing lookahead items in a fresh bin
        }
    }

    // Mild reward for tight fit ratio
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    score
}

