            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Next item fits perfectly in this bin afterwards -> big reward.
            score -= 10.0 / (1.0 + gap);
            if gap < 5.0 { score -= 8.0; }
        } else {
            // Next item would not fit: penalize proportionally to the overshoot.
            score += 0.15 * gap;
        }
    }

    // Penalize residuals far above the mean residual (wasteful leftover).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins can fit the item reasonably well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 5.0; // large items may justify a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
