pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: mildly penalize this one unless it's a very tight fit,
    // encouraging consolidation into the best-fitting bin.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual relative to capacity) or no good alternative exists.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count > 0 {
            fit_ratio > 0.35
        } else {
            true
        };
        if poor_fit {
            score -= 20.0;
        } else {
            score += 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item could use this bin's post_residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Perfect chain: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space the next item cannot use.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is near the mean residual (keeps bin pool balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling already-open bins as they accumulate.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = pr * (1.0 + poly);

    // Penalize bins that are nearly the item's own size (tight fit is actually good -> reward)
    let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins below mean residual when many bins are open (balance load)
    score += 0.15 * (pr - mean_residual) * (open_bins_count as f64).sqrt();

    // New-bin candidate: mild penalty so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let nis = next_item_size as f64;

    // Base: prefer tight fits with mild nonlinear shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Scarcity-weighted slack reward: fewer fitting bins => tighter fits matter more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);

            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;

            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item lookahead: residual hosts next item twice exactly
            if post_residual == 2 * next_item_size {
                score -= 2.5;
            }
        } else {
            // Bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: barely below next item, might still be salvaged later
            if pr > 0.5 * nis && pr < nis {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            // Large next item: a fresh bin may serve it better
            if nis > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if open_bins_count > 2 && post_residual >= next_item_size && (post_residual - next_item_size) <= 3 {
                    tight_open = true;
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
            }
            // Late-stream pressure against wasteful new bins when open bins are nearly empty
            if progress > 0.6 && open_bins_count > 6 && avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that fall into "small" classes
    // (near unusable dead space) are rewarded; large leftover classes are
    // penalized so we prefer bins that get filled tightly.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1
    let class = (frac * 10.0).floor() as i32; // 0..9 harmonic class
    match class {
        0 => score -= 30.0,          // near-perfect fill
        1 => score -= 20.0,
        2 => score -= 10.0,
        3 => score += 5.0,
        4 => score += 10.0,
        5 => score += 15.0,
        6 => score += 20.0,
        7 => score += 25.0,
        8 => score += 30.0,
        _ => score += 35.0,          // almost-empty bin kept as-is
    }

    // Lookahead synergy: if the next item exactly fills the post-residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post - nxt;
            // reward proportionally to how tightly the next item fits
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: slight penalty if we
            // leave a large unusable gap relative to next item size
            let dead = post - (nxt * 0.5);
            if dead > 0.0 {
                score += 0.15 * dead;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mild reward keeps ordering stable
        score -= 2.0 * (fitting_bins_count.min(8) as f64);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists among open bins. Compare its
    // residual against the mean residual of open bins: if open bins are
    // already tight (mean residual small), opening fresh is fine.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin, discounted early in the stream
        let mut new_bin_cost = 55.0 - 25.0 * progress;
        // If mean residual across open bins is large, prefer reusing them:
        // penalize opening a new bin when existing capacity is plentiful.
        if open > 0.0 {
            let slack_total = mean_residual * open;
            if slack_total > item_size as f64 * 2.0 {
                new_bin_cost += 20.0;
            }
        }
        score += new_bin_cost;
        // Empty-bin score should reflect its raw potential: subtract a bit
        // so it wins only when all open bins scored poorly.
        score -= 10.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is far
    // below the mean (i.e., already tight) is good; far above the mean is bad.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Modulo-flavored tie-breaking on post_residual: residuals that are
    // multiples of small harmonic steps (5, 10) pair well with typical
    // item sizes drawn from the same grid.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Integer-division threshold: if post_residual < smallest conceivable
    // item size region (<= 10), it's dead space — reward eliminating it.
    if post_residual <= 10 {
        score -= 15.0;
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
