pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap is "dead" if it cannot fit even the smallest plausible item (1..100 range)
        // Treat gaps below a threshold as wasted, scaled by how far below.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Non-linear penalty on very small gaps (1..=3) — nearly unusable.
        if post_residual <= 3 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward if the gap left behind can fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if the gap almost fits the next item (tempting but wasteful).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: bins with residual far below mean are scarcer —
    // favor placing into them to keep large residuals available.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // New-bin candidate: penalize slightly so it is only chosen when open bins
    // are all poor fits (score here = full capacity residual, already high).
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with modest slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    }
    // Next item cannot follow: penalize dead space, worse when post_residual very small
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += (15.0 * (1.0 - dead / 100.0)).max(0.0);
    }

    // Reward bins that are tighter than average (good consolidation)
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    // Penalize bins looser than average slightly
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discard opening new bins when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 * open_bins_count as f64;
    }

    // Late in stream: value tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
