    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are cheap to finish with
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        // Slightly-loose fit over next item: discourage wasting chain potential
        if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
            let over = slack;
            score += 0.8 * over / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                    // Low average fill: fresh bin can absorb slack later
                    if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                        score += 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                    if progress > 0.6 && open_bins_count > 6 {
                        score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: penalize small post-residuals less than linearly,
    // reward very tight fits strongly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize unusable dead space: if post_residual is small but nonzero and
    // unlikely to fit a typical future item, it's wasted.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement; if next item can't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits too: residual chaining is good
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this
    // empty bin's future. Only attractive when the item is large (poor fit
    // elsewhere) or many bins are open with scattered residuals.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let scattered = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        if large_item || scattered < 1.5 {
            score -= 30.0;
        } else {
