    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - tight);

    // Slight early-stream preference for balanced residual vs mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
