        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (-gap / cap) * progress;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - fit_norm);
    }

    // Mean-residual divergence penalty: avoid unbalanced bins
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 * progress;
    }

    score
}

