pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect closure: zero residual is the ideal harmonic class
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space below minimum item size (1..100 interface)
        score += 12.0;
    }

    // Harmonic class bucketing via integer division on post_residual
    let cls = (post_residual / 10) as f64;
    score += cls * 2.5;

    // Lookahead coupling with next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 14.0; // exact two-item pairing
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating residual far above the mean (wasteful spread)
    if post_residual as f64 > mean_residual + 20.0 {
        score += 6.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 28.0; // default: prefer reusing open bins
        // Opening a new bin is attractive if it leaves a "good class" residual
        // (residual in 20..=45 is reusable by typical mid-size items)
        if post_residual >= 20 && post_residual <= 45 {
            score -= 35.0;
        }
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Mild progress term: as the stream advances, tighter fills matter more
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
