pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot plausibly host a future item (min size 1..100,
    // but practically small gaps below ~10 are dead weight) gets a large bump.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 6.0;
    }

    // Perfect fit bonus: strongly reward zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty if the post-residual cannot fit the lookahead item
    // while the current bin could have been saved for it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bins pressure: discourage spreading across many open bins
    // unless the fit is tight; encourages consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would create severe dead space (post_residual small) or fit is loose.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 25.0;
        // But if the best alternative leaves a tiny unusable gap, allow the new bin:
        // emulate via mean_residual context: if mean residual is small (bins are tight),
        // opening a new bin is more acceptable.
        score -= (mean_residual / 10.0).min(3.0) * 4.0;
        // Lookahead: if next item is large, a fresh bin is useful.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild tightness reward relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (fewer chances to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: prefer tight fits (small post_residual), scaled by capacity fraction.
    score += 0.5 * pr / cap * 100.0;

    // 2-step lookahead: reward when post_residual can host next item exactly or well.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = pr - ni;
            // Perfect match: strong reward; penalize leftover gap otherwise.
            score -= 60.0 * (1.0 - gap / cap);
            score += 0.8 * gap;
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            score += 25.0 + 0.5 * (ni - pr);
        }
        // Bonus when this bin becomes perfectly closed after serving next item.
        if (post_residual as u32) == next_item_size {
            score -= 80.0;
        }
    } else {
        // Last item: just prefer minimal residual.
        score -= 10.0;
    }

    // Compare residual against mean residual of open bins:
    // bins with residual below mean are "tighter" -> favor using them.
    score += 0.3 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when all fits are bad.
    if bin_residual == bin_capacity {
        score = 95.0 + 0.1 * pr;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin is more attractive.
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild pressure against proliferating bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
