    // or the bin would be nearly empty anyway.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.4 * bin_capacity as f64;
        if fitting_bins_count == 0 || poor_fit {
            score -= 20.0;
        } else {
