    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Global state coupling: many open bins with high mean residual -> encourage
    // using existing bins to consolidate.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 12.0;
    }
    if open_bins_count > 0 && bin_residual as f64 > mean_residual {
        score += 5.0; // prefer bins below-average residual (tighter bins)
