    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Scarcity-weighted slack reward: prefer roomy fits when few alternatives.
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
        }
    }

    // Perfect fill: huge reward.
    if post_residual == 0 {
        score -= 180.0;
    }

    // Penalize creating unusable slivers / dead space relative to next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let rel = next_item_size as f64 / cap;
        score += (2.4 + 1.2 * rel) * post_residual as f64;
        // Harsher for residuals that are less than 60% of next item.
        if (post_residual as f64) < 0.6 * next_item_size as f64 {
            score += 3.5 * (1.0 - progress) * (1.0 - (post_residual as f64 / (0.6 * next_item_size as f64)));
        }
    }

    // Early-stream: prefer bins leaving moderately reusable residuals.
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual != next_item_size {
        score -= 6.0;
        if post_residual >= 2 * next_item_size {
            score -= 3.0;
        }
        if fitting_bins_count > 3 && (post_residual - next_item_size) > 10 {
            score += 2.5;
        }
    } else if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Consolidation pressure: mild penalty per open bin.
    score += 0.06 * (bin_capacity - bin_residual) as f64;
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate handling: attractive only when open bins fit poorly or bins are very full.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        let mean_tight = mean_residual / cap.max(1.0);
        let openness = 8.0 * (1.0 - mean_tight) - 6.0 * progress;
        score = 30.0 - scarcity - openness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        // Encourage fresh bins late when many bins are open and near-full.
        if open_bins_count > 4 && progress > 0.5 && mean_tight < 0.18 {
            score += 5.0 * (0.18 - mean_tight) * 10.0;
        }
        if open_bins_count > 6 && progress > 0.6 {
            score += 2.0 * ((open_bins_count as f64 / 20.0).min(2.0));
        }
    }

    // Late-stream: waste matters more.
    score += 2.0 * progress * (post_residual as f64 / cap);

    // Late-stream: small residuals are nearly perfect fills.
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    let tight = (bin_residual - item_size) as f64;
    score -= 40.0 * (1.0 - tight / bin_capacity as f64).powi(3);

    // Harmonic classes: classify post_residual into residue classes mod 10
    // Small dead space classes (< next plausible item size) are heavily penalized
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver under min item size
    }
    // Modulo-class coupling: residuals in classes {0, 25, 50, 75} are "harmonic"
    // (likely to combine with common item sizes); reward them.
    let class = pr % 25;
    if class == 0 && pr > 0 {
        score -= 15.0;
    } else if pr >= 10 {
        score += (class as f64) * 0.3; // mild penalty for off-harmonic residues
    }

    // Dead-space penalty scaled by how dead the space is relative to next item
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 25.0 * (1.0 - pr as f64 / next_item_size as f64);
    }
    // Reward a bin that fits both current and next item (chaining)
    if next_item_size > 0 && pr >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * progress - 8.0 * crowd.min(5.0);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
        // discourage opening new bin when a near-perfect fit exists elsewhere
        if item_size > 0 && tight < 5.0 {
            score += 50.0;
        }
    }

    // Mild pressure to fill already-open bins rather than spreading
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for typical future items (unusable gap < 10 units is pure waste).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Non-linear coupling: squared residual pressure for near-full bins,
    // rewarding very tight fits that leave almost nothing behind.
    let pr = post_residual as f64;
    if pr <= 5.0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement (creates a perfect future fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Small bonus if next item still fits after this placement.
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it is the "driest" bin — prefer filling it to keep the fleet uniform.
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual - 15.0 {
        score -= 10.0;
    } else if bin_res > mean_residual + 15.0 {
        score += 8.0;
    }

    // New-bin candidate: make opening a new bin only attractive when no open
    // bin offers a decent fit (post_residual small) or fleet is empty.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // Baseline new-bin cost: moderate, so poor fits in existing bins
            // (which accumulate dead-space penalties) can lose against it.
            score = 55.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - nr;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow; penalize proportionally to wasted potential
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.3 * unusable.min(nr);
        }
    }

    // Tight fit reward relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize large dead space relative to mean residual across open bins
    let cap = bin_capacity as f64;
    if post_residual as f64 > mean_residual + 0.25 * cap {
        score += 0.5 * (post_residual as f64 - mean_residual - 0.25 * cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (mean_residual >= item_size as f64 * 0.9);
        if good_fit_exists {
            score += 30.0; // discourage opening new bin when decent fit exists
        } else {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: tight-fit preference with mild convex shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Steeper slack penalty (borrowed: linear slack weighting)
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Multi-item chain: residual holds >= 2 copies of next item
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
                if post_residual == 2 * next_item_size {
                    score -= 1.5;
                }
            }
            // Scarcity-weighted slack reward (from best): fewer fitting bins -> prefer slack use
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: nearly useless
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            } else if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing space
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Deviation from mean residual penalty
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }
    // Band fit: residual just above next item but under 2x is loose
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
            }
            // Low average fill: opening a fresh bin is less costly
            if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    if fill_ratio > 0.85 {
        score -= 40.0 * fill_ratio;
    } else if fill_ratio > 0.6 {
        score -= 20.0 * fill_ratio;
    }

    // Penalize dead space: small post-residual that can't fit typical items is fine,
    // but medium dead space (e.g. 1..=9) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if post-residual can't fit the next item but is
    // still sizable, mildly penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin when decent
    // alternatives exist; allow it when few bins fit or residual is large.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0;
        if fitting_bins_count == 0 {
            new_bin_score = -100.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            new_bin_score = 15.0; // last-chance bin likely better
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        // Many open bins with high mean residual: reuse them.
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 5.0
            + (mean_residual / bin_capacity as f64) * 15.0;
        return new_bin_score;
    }

    // Mild penalty for spreading across many bins when mean residual is low.
    if (mean_residual / bin_capacity as f64) < 0.2 && open_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
