            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when an open bin holds a near-exact fit
                let mut tight_open = false;
                if open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    let crowd = if progress > 0.6 && open_bins_count > 6 {
                        2.0 * ((open_bins_count as f64) / 20.0).min(2.0)
                    } else {
                        0.0
                    };
                    score += pressure + late + crowd;
                    if avg_fill < 0.18 {
                        score += 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals close to next item size (wasted space)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.3 + 0.7 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - norm_post);

    // Prefer bins below mean residual slightly (consolidation)
    score += 0.2 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // bonus for hosting next item twice (chain of two)
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // penalize residuals just barely above next item (wasteful overhang)
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // half-usable residual: mildly bad early
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: grab residuals that cannot host anything bigger
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (divisible into common small-item denominations) deserve reward.
    let reusable = |r: u32| -> bool {
        r == 0 || r % 10 == 0 || r % 25 == 0 || r % 50 == 0
    };
    if reusable(post_residual) {
        score -= 12.0;
    } else if post_residual < 10 {
        // dead space: too small for any item
        score += 18.0;
    }

    // Integer-division thresholds on post_residual
    match post_residual {
        0 => score -= 25.0,                 // perfect fit
        1..=9 => score += 20.0,             // unusable sliver
        10..=19 => score -= 5.0,            // fits smallest class
        20..=39 => score -= 8.0,
        40..=59 => score -= 3.0,
        _ => {}
    }

    // Capacity fraction coupling: reward tight fills
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;                  // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            score -= 6.0;
            if post_residual % next_item_size == 0 {
                score -= 8.0;               // harmonic divisibility
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;            // penalize near-miss dead space
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // New-bin candidate handling: only attractive early or when bin is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fresh_penalty = 30.0 + 40.0 * progress;
        let poor_fit = post_residual > 60.0;
        if poor_fit && progress > 0.15 {
            score -= 20.0;                  // prefer fresh bin over waste
        } else {
            score += fresh_penalty;
        }
    }

    // Mean residual context: avoid fragmenting when residuals already low
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 6.0;
    }

    // Mild pressure to consolidate as bins accumulate
    score += open_bins_count as f64 * 0.05;

    score
}

