pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let miss = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 / (1.0 + miss * 0.35);
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Perfect chain of two: item fills bin so residual == next item, and
        // next item then fills it completely.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are more precious.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = (mean_residual - res) / mean_residual;
        score += tightness * 8.0;
    }

    // Penalize creating unusable dead space (small residual that nothing can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity or no good fit exists elsewhere; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 {
            score += 40.0 - 30.0 * frac;
        } else {
            score += 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

