    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- Harmonic classes on post_residual (base 10) ----
    // Residuals that are multiples of 10 are "harmonic" with typical item
    // granularity: they are likely to be exactly reusable later.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Very small non-harmonic residuals (1..10) are near-dead space for
    // coarse items but can still catch tiny items: mild penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Mid-range awkward residuals (11..19) are the worst dead zone.
    if post_residual > 10 && post_residual < 20 {
        score += 3.0;
    }

    // ---- Lookahead (k=2) coupling ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: strong reward, scaled
            // by how "harmonically" the pair fits.
            let pair = post_residual - next_item_size;
            score -= 6.0;
            if pair % 10 == 0 {
                score -= 3.0;
            }
        } else if post_residual > 0 {
            // Next item cannot follow into this bin: penalize leaving a
            // gap that is smaller than the incoming item.
            score += 2.0 + (post_residual as f64) * 0.05;
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is only good for large items or late in stream
        // when open bins are fragmented.
        score += 18.0 - 24.0 * fill_frac;
        if item_size >= 60 {
            score -= 12.0;
        } else if item_size >= 50 {
            score -= 5.0;
        }
        score += progress * 6.0;
        // If existing bins are already crowded, a new bin is more acceptable.
        score -= (open_bins_count as f64).min(10.0) * 0.4;
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 8.0;
    }

    // ---- Mean-residual context: avoid worsening an already fragmented fleet ----
    if !is_new_bin && (post_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

