pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, tight packing matters more -> amplify small residuals.
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * norm_pr * (1.0 - norm_pr) * cap * (1.0 + progress);

    // Penalize residuals too small to ever be useful (dead space) smoothly.
    let deadness = 1.0 - norm_pr; // large when residual small
    score += 12.0 * deadness * deadness * (1.0 + progress);

    // Reward bins whose residual can also fit the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: make it attractive only when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let crowdedness = mean_residual / cap;
        // If mean residual across open bins is large, prefer existing bins;
        // penalize the new bin proportionally; otherwise allow opening.
        score += 10.0 * crowdedness + 2.0 * (open_bins_count as f64).sqrt();
        // Perfect fit for a large item in a fresh bin is fine.
        if norm_pr < 0.2 {
            score -= 8.0;
        }
    } else {
        // Mild bonus for using bins that are already well-utilized.
        let used_frac = 1.0 - (bin_residual as f64) / cap;
        score -= 2.0 * used_frac * used_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" integer-division classes are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible into clean quarters -> highly reusable.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Class B: post_residual divisible by 10 (harmonic tenths of capacity).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class C: tiny dead space (1..=5) is nearly unusable -> strong penalty.
    if post_residual <= 5 {
        score += 25.0 * (1.0 - post_residual as f64 / 6.0);
    }
    // Class D: mid-range awkward leftover (6..=9) after a big item.
    if post_residual >= 6 && post_residual <= 9 {
        score += 8.0;
    }

    // Integer-division threshold coupling: leftover bucket via post_residual / 10.
    let bucket = post_residual / 10;
    score -= bucket as f64 * 1.5;

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead harmonic coupling: if the next item exactly fills the leftover,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 25 == 0 || next_post == 0 {
                score -= 10.0;
            }
            score += next_post as f64 * 0.3;
        } else {
            // Next item cannot use this bin's leftover anyway.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual <= 5 {
            score += 20.0; // still penalize creating dead space
        }
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual across open bins is small, new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Large item: prefer a fresh bin to avoid fragmenting open bins.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, consolidate harder (prefer filling
    // existing bins rather than spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty proportional to current waste relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity-aware slack reward (from best heuristic)
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            // bin can't host next item: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if (pr) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // Relative-size-aware dead-space extra (from best heuristic)
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: tiny residuals are worth finishing
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Loose fit among many candidates
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        if post_residual < 2 * next_item_size {
            score += 0.8 * slack / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score += 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64).max(0.3);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins attractive only when open bins are crowded
    // or the fit would create dead space.
    if bin_residual == bin_capacity {
        let mean_fit_penalty = (mean_residual - item_size as f64).abs();
        if mean_fit_penalty > 25.0 || post_residual < 10 {
            score -= 20.0;
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Deviation from mean residual: prefer bins with residual close to the item
    // (best-fit flavor), penalize both too-large and too-small mismatches.
    let dev = bin_residual as f64 - item_size as f64;
    score += 0.15 * (dev - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let nis = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack reward (borrowed from best): preserve tight chains
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // post_residual just above next item: mildly discourage (wasted sliver)
            if post_residual < 2 * next_item_size && fitting_bins_count > 2 {
                let over = slack;
                score += 0.8 * over / nis * 10.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // unusable residual: penalize relative to usable fraction
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && pr < 0.6 * nis {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * nis));
            }
            if pr > nis / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    let pr = post_residual as f64;

    // 2-step lookahead: reward when next item fits exactly into post_residual
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        -40.0 * (1.0 - diff / bin_capacity as f64)
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use leftover; penalize wasted space proportionally
        15.0 * (pr / bin_capacity as f64)
    } else {
        0.0
    };

    // Perfect match bonus: next item exactly fills the bin
    let perfect = if next_item_size == post_residual && next_item_size > 0 {
        -60.0
    } else {
        0.0
    };

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    let mean_coupling = (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Penalize creating very small dead space (< 10) that likely can't fit future items
    let dead_space = if post_residual < 10 && post_residual > 0 { 20.0 } else { 0.0 };

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let progress_term = progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly
    let is_new = bin_residual == bin_capacity;
    let new_bin_term = if is_new {
        bin_capacity as f64 - 30.0 + 10.0 * (1.0 - progress)
    } else {
        0.0
    };

    score = pr + lookahead_bonus + perfect + mean_coupling + last_chance + dead_space + progress_term + new_bin_term;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.80;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead: if the next item fits in the post residual, this is a great chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize leaving awkward mid-size gaps.
            let gap = post_residual as f64;
            if gap < 10.0 {
                score -= 6.0; // tiny dead space is fine
            } else {
                score += 0.15 * gap;
            }
        }
    } else {
        // Last item: pure tightness matters most.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and this is a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But allow new bin if item is large relative to mean residual (poor fits elsewhere).
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Slight preference for filling bins with large residuals using large items.
    score -= 0.05 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: prefer existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 8.0 * (bin_residual == bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        // extra: small dead residuals are near-certain waste
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // relative dead-space shaping (from best): weight residual itself
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // scarcity-aware slack pull toward tight chains
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two bonus
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // over-slack penalty when many fitting bins compete
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            // slack just over next item: mild penalty to prefer tighter hosts
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            // near-half-dead residuals: discourage unusable slivers
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            // half-usable residuals slightly worse early
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // wasteful when open bins mostly empty
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            // never open a new bin when a tight fit exists
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // combined feature: new bin especially wasteful when a slack-fitting
            // host also leaves a residual usable by the next item
            if next_item_size > 0 && post_residual >= 2 * next_item_size {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: dead space matters more late in the stream
    score += 12.0 * progress * norm_pr * norm_pr;

    // Tight fits rewarded: quadratic decay of penalty as post_residual -> 0
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize opening new bins unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        // But a fresh bin is good if the item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap) * (item_size as f64 / cap);
    }

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let kernel = (-fit_gap * fit_gap / (0.15 * cap * cap)).exp();
        score -= 6.0 * kernel;
    }

    // Many open bins: slight penalty to spreading, encourage consolidation
    score += 0.4 * open_bins_count as f64 * norm_pr;

    score
}

