pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common item
    // size classes (10/20/25/50) are more reusable than awkward remainders.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr == 0 { reusability += 12.0; }                 // perfect fill
    if pr % 10 == 0 { reusability += 4.0; }
    if pr % 20 == 0 { reusability += 2.0; }
    if pr % 25 == 0 { reusability += 2.0; }
    if pr % 50 == 0 { reusability += 2.0; }
    score -= reusability;

    // Penalize dead space that no plausible item (1..=80) can fill well:
    // leftover in (0,10) is nearly unusable.
    if pr > 0 && pr < 10 { score += 15.0; }
    // Leftover in (50,60) awkward band: too big for small items, too small for large
    if pr > 50 && pr < 60 { score += 6.0; }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for stranding capacity
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bin mildly attractive only when
    // current item is huge and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bin normally; discount when item is large and mean residual small
        let mut nb = 25.0 - progress * 5.0;
        if item_size >= 60 && fragmentation < item_size as f64 / bin_capacity as f64 {
            nb -= 20.0;
        }
        score += nb;
    }

    // Mild preference for tighter existing bins (small residual before placement)
    score += bin_residual as f64 * 0.05;

    score
}

