    let frac_used = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * frac_used;

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // favoring consolidation; but reward using nearly-full bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Allow new bin if current item would leave large dead space everywhere
        // or if the next item is large and this item is small.
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < 20 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item exactly fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item is slightly larger than post residual (near-miss waste).
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight;
    // prefer filling it further.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is a huge reward
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0).powf(4.0);
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a sliver that the next item cannot use
        if post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: reward tight packing
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward bins whose residual was already tight (good historical fit)
    score -= 8.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    // Relative to mean residual: prefer filling bins below-average residual
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when many bins are open and it fits somewhere tight
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if post_residual would be very small
        score += 10.0 + 0.1 * post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Progress-aware tightening: late in the stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good, but tiny residual (< 10)
    // is dead space, so penalize a small but nonzero leftover.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure bonus
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins with large mean residual -> prefer reusing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins or
        // high mean residual available.
        score += 40.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // Late in the stream, opening new bins is rarely worth it.
        score += progress * 30.0;
        // But if this item is huge relative to typical residuals, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 35.0;
        }
    } else {
        // Reuse bonus scaled by how average this bin's residual is.
        score -= (bin_residual as f64 - mean_residual).abs() * -0.2;
        // Prefer filling bins with large residuals (reduce fragmentation).
        score -= (bin_residual as f64) * 0.1;
    }

    // Mild time-horizon coupling: early on, keep bins flexible (favor mid-size
    // leftovers); late, close bins aggressively.
    score += (1.0 - progress) * pr * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly penalized.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: late in the stream,
    // waste is increasingly costly, so amplify residual penalty.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward bins whose residual matches the next item's size (lookahead synergy).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize bins with much larger residual than the mean (fragmentation risk),
    // with smooth quadratic coupling to progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.5 + progress);

    // Slight preference against opening new bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Bonus for exact-ish fits (post residual small relative to capacity).
    score -= 5.0 * (1.0 - norm_pr).powi(6) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
