pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals that are "dead" (too small for the smallest plausible item) are heavily penalized.
    let dead_zone: u32 = 10;
    if post_residual < dead_zone {
        score += 60.0; // unusable sliver
    } else {
        // Class of post_residual mod 10: residuals matching common item-size complements are good.
        let class = post_residual % 10;
        // Complement classes (residual such that a common item fills it exactly) get a bonus.
        let common: [u32; 6] = [10, 20, 30, 40, 50, 60];
        let mut harmonic_bonus = 0.0;
        for c in common.iter() {
            if post_residual == *c {
                harmonic_bonus += 15.0;
            }
        }
        // Integer-division threshold: post_residual / 10 gives "slots" of size 10.
        let slots = post_residual / 10;
        harmonic_bonus += slots as f64 * 1.5;
        // Penalize awkward classes (residual mod 10 in {1,2,3} -> hard to fill exactly).
        if class <= 3 {
            harmonic_bonus -= 6.0;
        }
        score -= harmonic_bonus;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item nests.
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic: if next_item_size divides post_residual evenly, extra reward.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty for wasting capacity.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: base score for empty bin is bin_capacity (post_residual == capacity).
    // Make it unattractive unless existing fits are poor or bin pool is empty.
    if bin_residual == bin_capacity {
        // Neutralize base and add penalty; opening is favored only when
        // no other bin fits well or stream is early.
        score = bin_capacity as f64 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // Early in the stream, keep more bins open (more options later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is large, a fresh bin is fine.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward when many bins are open (consolidation pressure).
        if open_bins_count > 4 {
            score -= 2.0;
        }
        // Prefer bins tighter than the mean residual (good consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space avoidance: penalize small unusable gaps after placement.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 20.0 {
        // Small leftover gap is likely dead space -> heavy penalty.
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if the next item fits snugly afterwards.
        let after_next = post_residual - next_item_size as f64;
        if after_next <= 10.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size as f64 {
        // The leftover gap cannot host the next item: mild dead-space penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.4;

    // Prefer bins tighter than the mean residual (better density).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it moderately expensive so it is chosen only
    // when all open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // NEW: scale dead penalty by relative item size (large items on dead space hurt more)
        let rel_next = next / cap;
        score += 20.0 * rel_next * dead * (1.0 - progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // NEW: post_residual must also be able to host item after next (two-step chain)
            let after_next = pr - next;
            if after_next >= item_size as f64 {
                score -= 2.5 * scarcity;
            } else if after_next > 0.0 && after_next < item_size as f64 {
                score += 1.2 * (1.0 - after_next / item_size as f64) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // NEW: never open a new bin when an exact-fit host exists
            if next_item_size > 0 && post_residual == next_item_size {
                score += 60.0;
            }
            // NEW: discourage new bins when open bins are mostly full (good compaction in progress)
            if avg_fill > 0.6 && open_bins_count > 2 {
                score += 6.0 * (avg_fill - 0.6) * 10.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
