}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (quadratic dead-space pressure)
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Two-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to leftover dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins tighter than average get priority
    score -= 1.5 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        // Opening fresh is penalized unless it enables a near-perfect fit
        let fit_quality = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - fit_quality);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // As stream progresses, discourage opening too many bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers are heavily favored.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item can fit in the post-residual, reward this placement;
    // if it cannot, penalize leaving a residual that is awkwardly sized.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we DON'T place here — mild penalty.
            score += 5.0;
        } else {
            // Next item won't fit here either way; neutral.
            score += 0.0;
        }
        // Perfect chain: next item exactly fills post-residual.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else {
        // Last item in the stream: strongly prefer minimizing waste.
        score += (post_residual as f64) * 2.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when there are many open bins with slack
    // (encourage consolidation), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is necessary, remove penalty.
            score -= 45.0;
        }
    }

    // Slight preference for bins with residuals close to the item (best-fit flavor)
    // beyond raw post_residual, but avoid over-fragmenting when many bins are open.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Encourage filling bins nearly to capacity late in the stream.
    if post_residual < 10 && bin_residual < bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
