    // on leftover space that grows quadratically (dead space is increasingly wasteful).
    let mut score = post * (1.0 + residual_norm * residual_norm);

    // Non-linear coupling with stream progress: late in the stream, leftover
    // space matters more (fewer chances to fill it), so scale the penalty up.
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score *= progress_coupling;

