    // post-placement residual, reward this bin (subtract) smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = (next_item_size as f64 / post.max(1.0)).min(1.0);
        let lookahead_reward = 12.0 * fit_quality * (1.0 - progress * 0.5);
        score -= lookahead_reward;
    } else if next_item_size > 0 && post > 0 {
        // Next item does not fit: smooth penalty proportional to how badly it misses.
        let miss = (next_item_size as f64 - post) / cap;
        score += 8.0 * miss * miss;
    }

    // Last-chance bin: strongly reward using the only bin that fits, smoothly
    // scaled by how much slack would otherwise be stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - residual_norm;
        score -= 15.0 * (0.5 + 0.5 * tightness);
    }

