    // bins have poor fits; make the empty bin mildly expensive by default,
    // with a smooth discount when mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let mean_ratio = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln().max(0.0);
        let discount = 18.0 * (1.0 - mean_ratio) * (1.0 + 0.1 * openness);
        score += 30.0 - discount;
    }

    // Small smooth tie-breaker against bins far from the mean residual,
    // encouraging balanced residual distribution across open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (or leave room for
    // typical small items) are more valuable than odd dead space.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = pr as f64 / cap;
    score += 12.0 * waste_frac * waste_frac;

    // Modulo classes on post_residual: residuals in [1..9] are near-dead space
    if pr > 0 && pr < 10 {
        score += 18.0;
    } else if pr >= 10 && pr < 20 {
        score += 6.0;
    }

    // Reward residuals that are exact multiples of 10 (harmonic with capacity 100)
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Perfect fit: zero residual is ideal
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 30.0;
        } else if diff < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item cannot use this bin's leftover; penalize proportionally
        score += 3.0 + waste_frac * 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and we create low-value residual
    if open_bins_count > 3 && pr > 0 && pr < 15 {
        score += 4.0;
    }

    // Stream progression: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - waste_frac);

    // New-bin candidate: penalize opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        let avg_bad = mean_residual / cap;
        score += 20.0 - 25.0 * avg_bad;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin is fine
