pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space: residuals in [1,9] are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; if it barely
    // misses, penalize creating a near-miss gap.
