    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // fits are poor and the item is large relative to a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = (mean_residual - item_size as f64).abs() < 5.0
            || mean_residual < item_size as f64;
        if poor_fit_elsewhere && item_size >= 50 {
            score -= 15.0;
