    // Prefer fuller bins over emptier ones as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual);

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
