    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post residual with stream progress.
    let base = 4.0 * x * (1.0 - x); // peaks at x=0.5 (worst dead space)
    let coupling = base * (0.5 + 0.5 * progress);

    // Penalize residual that cannot fit the lookahead item.
    let mut score = post + 60.0 * coupling;
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 25.0 * gap * (1.0 - progress);
