pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Dead space: nothing can ever fit here (min item size 1..10 zone).
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            // Very tight gap: only tiny items fit; risky residual.
            score += 15.0 * (20.0 - gap) / 10.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when unnecessary.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the current fit is poor. Penalize the empty bin moderately; the
    // dead-space penalties above can then outweigh it for bad fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual bins are "well used").
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Slight stream-progression pressure: as the stream advances, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

