    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: strongly reward bins whose post_residual
    // equals the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild reward, penalize leftover gap
            let gap = pr - nxt;
            score -= 15.0;
            score += gap * 0.35;
        } else {
            // next item won't fit here: penalize proportionally to shortfall
            let short = nxt - pr;
            score += short * 0.45;
