        score += (post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10) unless exact match.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded
    // or the fit is bad; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
        score += 18.0 - crowding * 2.0;
        // If current bin would leave a very tight fit, allow new bin to win.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 8.0;
