    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual becomes waste if next item doesn't fit.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing residuals are poorly matched to the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        // Penalize opening new bins when existing bins fit reasonably well.
        let mut new_bin_penalty = 18.0 + 0.4 * avg_waste;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_penalty += 20.0 * progress;
        // If many bins fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Large items relative to residual: new bin may be justified.
        if item_size as f64 > mean_residual {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    } else {
        // Slight preference for filling already-open bins densely.
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Global pressure: many open bins -> prefer using existing ones.
    score += 0.1 * open_bins_count as f64;

    score
}

