pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // 0..1
    let t = progress;
    // quadratic interaction: dead space penalized more as stream progresses
    score += 30.0 * pr_norm * pr_norm * (0.5 + t);
    score -= 20.0 * pr_norm * (1.0 - t) * (1.0 - t);

    // Reward tight fits (small post_residual) with smooth cubic falloff
    let tight = 1.0 - pr_norm;
    score -= 25.0 * tight * tight * tight;

    // Lookahead coupling: favor bins whose post residual can host next item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (ni - pr) / cap;
            score += 20.0 * gap * gap;
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 40.0 * tight;
    }

    // Last-chance bin: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 35.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mean residual divergence penalty (smooth quadratic)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening new bins mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - t) * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
