pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strongly discounted.
    let pr = post_residual as f64;
    score -= 120.0 * (-pr / 20.0).exp();

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residuals that are "dead" (small, unusable for typical items) are penalized;
    // residuals in reusable classes (multiples of 10) are rewarded.
    let class = post_residual % 10;
    match class {
        0 => score -= 18.0,               // perfectly reusable residual
        1 | 2 | 3 => score += 22.0,       // dead space, nearly unusable
        4 | 5 | 6 => score += 8.0,        // marginal usability
        _ => score -= 4.0,                // decent chance a small item fits
    }

    // Harmonic bonus: if post_residual is an exact multiple of 10, a future
    // item of a harmonic class (10..100 step 10) fits perfectly.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty if we waste a lot anyway
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current bins have poor fits (high mean residual spread)
    // or the fit here is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: penalize opening new bins mildly, but less than
        // a very bad fit would cost.
        score += 30.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If the current item is large, opening a fresh bin is reasonable.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small (bins are nearly full),
        // a new bin is natural.
        score -= mean_residual * 0.3;
    }

    // Stream progression: early in the stream, be more willing to open bins
    // (build diverse partial bins); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    // Mild penalty for creating many open bins (fragmentation control).
    score += open_bins_count as f64 * 0.5;

    // Penalize large leftover relative to capacity (waste ratio).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste and heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Moderate penalty for gaps that are large enough to be useful but still
    // represent significant wasted space relative to the item.
    score += 0.25 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward near-perfect fits (post_residual very small but usable).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than fragmenting across more bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin gets a baseline penalty so it
    // is only chosen when open bins fit poorly; relax this pressure as the
    // stream nears its end (no future to amortize bin openings).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving
    // that space; if it almost fits, slightly penalize a near-miss gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual >= next_item_size - 3 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual deviates below the mean residual (tighter
    // bins get filled first, keeping looser bins flexible).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: tight fits, shaped
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // relative dead-space weighting (borrowed from best)
        let rel = next_item_size as f64 / cap;
        score += (2.4 + 1.2 * rel) * post_residual as f64;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
