                    score += 40.0;
                }
            }
            // never open a new bin when any open bin can host the next item exactly
            if next_item_size > 0 && post_residual == next_item_size {
                score += 60.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but weight by item size.
    score += 0.5 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward if next item fits into post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus proportional to how well the next item fills the leftover.
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
