    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // If no other bin fits, opening is fine (fitting_bins_count==0 handled implicitly
        // since only empty-bin candidate exists); soften the penalty then.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Mild penalty for very small leftovers that nothing can use (min item ~1).
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

