    score -= 2.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Time horizon: early in stream, allow new bins more freely; late, pack tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
