pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands.
    // Classes: [0..=5] near-perfect, (5..=20] small, (20..=40] medium, (40..=60] large, >60 wasteful.
    let post_class: f64 = if post_residual == 0 {
        -30.0
    } else if post_residual <= 5 {
        -18.0
    } else if post_residual <= 20 {
        -6.0
    } else if post_residual <= 40 {
        0.0
    } else if post_residual <= 60 {
        8.0
    } else {
        16.0
    };
    score += post_class;

    // Integer-division harmonic: residual divisible into fine chunks is more reusable.
    let div_score = if post_residual > 0 {
        let d = post_residual;
        // reward residuals that are multiples of common item-size steps (10/20/25/50)
        if d % 10 == 0 { -7.0 } else if d % 25 == 0 { -5.0 } else if d % 20 == 0 { -4.0 } else { 0.0 }
    } else { 0.0 };
    score += div_score;

    // Modulo coupling with next item: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; leftover becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // harmonic class of next item size (capacity fractions)
        let next_class: f64 = if next_item_size >= 50 { 3.0 } else if next_item_size >= 25 { 0.0 } else { -2.0 };
        score += next_class;
    } else {
        // last item: prefer tightest fit strongly
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be very fragmented.
    if bin_residual == bin_capacity {
        // opening fresh: baseline cost, reduced late in stream when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 10.0 * progress - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin leaves room for the larger next item
        }
        return score;
    }

    // Prefer filling bins below mean residual (balancing via harmonic mean-like term)
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

