    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that nothing (min size 1..100, but
    // practically small items) can use are heavily penalized.
    if post_residual > 0 {
        // penalize gaps in the "dead zone" (too small for typical items)
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 25 {
            score += 20.0 * (25.0 - post_residual as f64) / 15.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 80.0;
    }

    // Reward tight fits (small waste relative to bin capacity)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (good fit vs. bin state)
    score += 0.3 * ((bin_residual as f64 - item_size as f64).abs());

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill the emptiest first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 120.0 } else { 0.0 };
        score += 55.0 + 2.0 * open_bins_count as f64 - desperation;
    }

    score
}

