        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // new: dead-space scaled by residual size (small dead slivers are pure waste)
        score += 1.2 * pr * (1.0 - progress) / cap * 10.0;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // new: graded tightness reward regardless of scarcity, stronger early
            score -= (1.5 * (1.0 - progress)) * (1.0 - (slack / (0.5 * cap)).min(1.0));
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
                // new: also forbid new bins when a decent (not just tight) fit exists late
                if progress > 0.5 && post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 0.1 * cap {
                    score += 12.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins that end (nearly) full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next_item_size exactly fills the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 300.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space: post residual too small for the next item.
            // Penalize proportionally to how close it came to fitting next item.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 150.0 + 10.0 * gap as f64;
            } else {
                score += 50.0;
            }
        }
        // If post residual fits next item with big leftover, mild penalty.
        if post_residual > next_item_size && post_residual - next_item_size > 10 {
            score += 20.0;
        }
    } else {
        // Last item: only perfect fit matters.
        score -= 100.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 50 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and lookahead cannot be served.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40;
        let lookahead_mismatch = next_item_size > 0 && post_residual < next_item_size;
        if !(bad_fit || lookahead_mismatch) {
            score += 400.0;
        } else {
            score += 100.0;
        }
    }

    // Late in the stream: consolidate, prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.5 * (bin_capacity - bin_residual) as f64;

    // Many open bins: prefer reusing existing bins over opening more.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 5.0 * (bin_residual == bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
