pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin,
    // unless the fit would be terrible (big dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual as f64 > mean_residual {
            score += 20.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
        }
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9; // baseline for new bin
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 20.0; // opening is fine when bins are nearly full
        }
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.min(bin_capacity as f64);
            if (best_possible - item_size as f64) < 15.0 {
                score += 40.0; // existing bins could take it decently: discourage new bin
            }
        }
        // Late in the stream, avoid leaving many scattered open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space the next item cannot use.
        let dead = post_residual as f64 / next_item_size as f64;
        score += 15.0 * (1.0 - dead.min(1.0));
    }

    // Mild preference for fuller bins overall (compare against mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
