pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress * norm_pr);

    // Reward tight fits: penalize low post_residual
    score -= 0.6 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Penalize dead space that can't fit typical items (smooth via mean residual)
    if pr > 0.0 {
        score += 0.3 * (pr / (mean_residual + 10.0)) * (1.0 - (pr / cap));
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 0.3 * (1.0 - (next_item_size as f64 / cap)) * progress;
    }

    // Mild pressure toward consolidating bins early
    score += 0.05 * (open_bins_count as f64 / (1.0 + progress * total_items as f64 / 100.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by size bands via integer division
    let item_class = item_size / 20; // 0..=5 (tiny, small, medium, large, xlarge, huge)
    let next_class = next_item_size / 20;

    // Perfect fit / near-perfect fit reward: post_residual in a small harmonic band
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty: post_residual too small to hold any item (1..min item assumed >=10 by design, but be safe)
    let min_item = if next_item_size > 0 { next_item_size.min(item_size).min(10) } else { 10 };
    if post_residual > 0 && (post_residual as u64) < (min_item as u64) {
        score += 15.0; // unusable sliver
    }

    // Modulo coupling: post_residual divisible by common item sizes is reusable
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // clean harmonic slot
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next fits: mild reward scaled by how snugly
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize leaving large residual we can't chain into
        score += 6.0;
    }

    // Class pairing bonus: large items (class >= 3) prefer bins with matching phase
    if item_class >= 3 && (bin_residual as i64 - item_size as i64) % 25 == 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        // base penalty so new bins are used only when justified
        score += 20.0 + 10.0 * crowding;
        if item_size > 60 || fitting_bins_count == 0 {
            score -= 35.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 15.0; // existing bins nearly full -> open fresh one
        }
        let _ = progress;
    } else {
        // Prefer tighter existing bins: reward small bin_residual relative to item
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // Prefer bins whose residual is below the mean (tighter packing)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild exploration term: scale pressure early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual != bin_capacity {
        score -= 3.0; // consolidate early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
