                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // NEW: never open a new bin late when any open bin can host the next item
            if progress > 0.6 && fitting_bins_count > 0 {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, penalize leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.5;
        } else {
            // next item won't fit here: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual to mean residual: prefer tighter bins (below mean residual)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably well
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.2;
        if fitting_bins_count > 0 {
            score += 200.0;
        }
    }

    // Slight penalty for very small post_residuals that create unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Stream progression: later in stream, be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base cost: nonlinear dead-space penalty (superlinear in leftover space)
    let mut score = post.powf(1.25);

    // Lookahead (k=2): reward bins whose residue can host the next item,
    // penalize bins whose residue becomes dead space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - post_residual as f64 / cap);
        } else {
            // residue too small for the next item: dead weight
            score += 12.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin (never for the new-bin candidate).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: mild default reluctance; it must beat an existing bin
    // by genuinely avoiding dead space, not by tie-breaking.
    if is_new_bin {
        score += 6.0;
        // If the fresh bin leaves a residue that likely hosts the next item,
        // opening it becomes more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Global context: spread-awareness — when mean residual across open bins
    // is high, prefer bins that reduce fragmentation (tighter fits).
    score += 0.08 * (mean_residual - post);

    // Dynamic time horizon: late in the stream, be slightly more conservative
    // (favor exact fits, avoid scattering residue as the stream ends).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t * (post / cap);

    // Tiny tie-shifter toward bins that absorb larger items efficiently.
    score -= 2.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;

    // Base: raw post-residual (smaller = better), with mild non-linear shaping
    let mut score = pr + 0.35 * pr * pr / cap;

    // Lookahead: exact fit jackpot; graded slack reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // scarcity-aware pull toward tight chains
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // chain of two bonus
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // over-slack penalty when many fitting bins compete
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            // slack just over next item: prefer tighter hosts
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            // dead-space penalty: residual unusable by next item
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            score += 14.0 * (1.0 - pr / cap) * (1.0 - progress);
            if post_residual < next_item_size / 2 {
                score += 4.0 * (1.0 - progress);
            }
            // near-half-dead slivers
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            // half-usable residuals slightly worse early
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // wasteful when open bins mostly empty
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            // never open a new bin when a tight fit exists
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit)
    let mut score = post;

    // Reward tight fits with smooth quadratic term
    score -= 3.0 * (1.0 - post / cap).powi(2) * (item / cap);

    // Penalize dead space that is too small for typical future items
    let dead = post / cap;
    score += 2.5 * dead * (1.0 - dead).powi(2);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate handling: prefer opening a new bin early, or when
    // the fit into existing bins is poor (large post residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap * 0.85 + 12.0 * (1.0 - progress);
        // If no existing bin fits well, new bin becomes attractive
        if post_residual == 0 && bin_residual == bin_capacity {
            // fallthrough
        }
    } else if post_residual as f64 > cap * 0.5 {
        // Poor fit: nudge toward opening a new bin instead
        score += 3.0 * (post / cap - 0.5) * 10.0 * (0.3 + 0.7 * (1.0 - progress));
    }

    // Lookahead: reward bins whose post-residual still fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 1.5 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Mean residual coupling: discourage bins far from the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.2 * dev * dev;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    score -= 2.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which quarter of capacity the leftover falls in.
    let q = (bin_capacity / 4).max(1);
    let quarter = post_residual / q; // 0..4
    match quarter {
        0 => score -= 12.0,          // near-perfect fill
        1 => score -= 4.0,           // small leftover, still usable
        2 => score += 2.0,           // mid leftover
        _ => score += 6.0,           // large leftover
    }

    // Reward if next item exactly fills the post-residual (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional lookahead fit quality.
        let frac = next_item_size as f64 / post_residual as f64;
        if frac >= 0.75 {
            score -= 10.0 * frac;
        } else if frac < 0.2 {
            score += 3.0; // tiny next item wastes a big slot here
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space too small for anything: strong penalty unless last chance.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
