pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 as a "harmonic class"
    let residue = post_residual % 10;
    let harmonic_class = post_residual / 10; // integer division threshold (0..=10)

    // Penalize dead space: residuals in awkward classes (1..=9 residue) are hard to fill
    if residue > 0 && residue < 10 {
        score += (10 - residue) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Class-based reward: high harmonic class (lots of room left) is fine only early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += harmonic_class as f64 * (0.5 + 2.0 * progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward if next item exactly fills the remaining class
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use: penalize proportionally to class
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: discourage spreading, favor filling existing bins
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 200.0;
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
