pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 20 {
        // Medium-risk gaps: mildly penalized, scaled by how far they are from typical item sizes.
        score += 5.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the remaining gap -> dead space likely.
            score += 6.0;
        }
    }

    // Open-bin pressure: prefer placing into existing bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Slight preference for bins tighter than average (better packing density).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure > 0.65 {
            score -= 20.0 * pressure; // bins mostly full: new bin is reasonable
        } else {
            score += 30.0; // discourage wasting capacity in a fresh bin
        }
    }

    // Mild late-stream conservatism: keep bins tight as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Primary: aggressive 2-step lookahead matching.
    // Reward when the post residual exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match: strong reward.
        if gap < 1.0 {
            score -= 25.0;
        } else {
            // Smooth decay of reward with lookahead gap, scaled by item size.
            score -= 18.0 * (-gap / 20.0).exp();
        }
        // Penalize residuals that are too small for the next item but nonzero
        // (dead space the next item cannot use).
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 8.0 * (1.0 - (post_residual as f64) / nxt);
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins tighter than average (fill dense bins),
    // mildly penalize bins looser than average.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Prefer high fill ratio of the bin before placement.
    score -= 0.15 * (1.0 - bin_residual as f64 / cap) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // If the next item is large, a fresh bin may still be attractive.
        if next_item_size > 0 && (post_residual as f64).abs() < 0.5 {
            score -= 20.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < item_size.max(10) {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins with slack: discourage spreading, encourage consolidation.
    if open_bins_count > 2 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * spread;
        score += 0.05 * (open_bins_count as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 4.0; // near-miss dead space penalized
        }
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_options = if fitting_bins_count == 0 {
            0.0
        } else {
            (bin_residual - item_size.min(bin_residual)) as f64
        };
        let best_alt = if fitting_bins_count > 0 { (bin_capacity - item_size) as f64 } else { f64::MAX };
        let threshold = 18.0 - 10.0 * progress; // later in stream, harder to open new bins
        if best_alt > threshold {
            score -= 12.0; // open a fresh bin rather than wreck one
        } else {
            score += 25.0 + 0.1 * (open_bins_count as f64);
        }
        let _ = poor_options;
    }

    // Mild preference for bins whose residual is a multiple-friendly size.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space becomes increasingly costly as stream progresses
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * pr_norm * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits (small post residual) more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
