    }

    // Penalize bins that are far below mean residual (fragmentation avoidance)
    score += 0.3 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    // Lookahead: reward bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 2.0 * (1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64));
        } else {
            score += 1.5;
        }
