    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by how much slack remains after next placement
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit: penalize dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize leftover tightly
        score += 0.2 * post_residual as f64;
    }

    // Compare residual against mean residual: prefer using bins with less residual than average
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty scaled by how many bins could fit
        score += 150.0 + 20.0 * fitting_bins_count as f64;
        // but if next item is large and no open bin could chain, new bin is less bad
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 100.0;
        }
    }

    // Late-stream: prefer tighter packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

