    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward leaving zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize tiny unusable slivers relative to the smallest conceivable item (1).
        // Dead space below ~10 is nearly guaranteed waste.
