    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes doubly valuable; reward it. If next item cannot fit
    // any plausible residual, slightly penalize hoarding space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Chain fit: reward proportionally to how well the next item uses leftover space.
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / post_residual as f64);
        } else {
