    score += 20.0 * (post_residual as f64 / bin_capacity as f64).powi(2);

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system; be pickier about large leftovers.
    score += 0.15 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, opening bins is cheap (many future items
    // can use fresh space); late in the stream, consolidate aggressively.
    let new_bin_penalty = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus early-stream discount.
        score += 25.0 - new_bin_penalty;
    }

    // Late-stream consolidation pressure: penalize leaving moderate waste
    // more heavily as the stream nears its end.
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker against fragmentation across many open bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

