    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Penalize residual classes that are hard to fill (not multiples of common sizes)
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50] {
