    // Mean residual divergence: prefer bins far from mean (extreme consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev / cap;

    // Phase-based scaling: later in stream, be greedier about consolidation
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * phase;

    score
}

