            // COMBINED: linear slack penalty scaled by relative slack (borrowed from best)
            if slack > 4.0 {
                let rel = if slack <= 20.0 { 1.1 } else { 0.25 };
                score += rel * slack * 0.35;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // COMBINED: suppress new-bin opening when a good chain exists in open bins
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 0.15 * cap {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (integer division thresholds) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class the post-residual into harmonic bands: dead space vs usable space.
    let post_quarter = post_residual / (bin_capacity / 4); // 0..4 harmonic class
    match post_quarter {
        0 => score -= 60.0,                       // near-perfect fit
        1 => score -= 25.0,                       // small but usable
        2 => { score += 5.0; }                    // mediocre
        _ => { score += 20.0; }                   // large leftover: poor packing
    }

    // Modulo arithmetic on post_residual: values close to common item sizes
    // (multiples of 10, 20, 25) are more likely to be filled later.
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    if mod10 == 0 { score -= 12.0; }
    if mod25 == 0 { score -= 18.0; }
    if post_residual >= 10 && mod10 != 0 && mod10 < 3 { score += 8.0; } // awkward sliver

    // --- Lookahead coupling: does next item fit into post residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward chains that keep the next item in this bin.
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 30.0 + 25.0 * tightness;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportional to how badly it misses,
        // scaled by whether this bin was the last chance for the current item.
        let miss = (next_item_size - post_residual) as f64;
        if fitting_bins_count == 1 {
            score -= 45.0; // must place here anyway; offset the post penalty
        } else {
            score += 10.0 + miss.min(60.0) * 0.4;
        }
    }

    // --- Last-chance bonus: only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // --- New-bin candidate logic: only open a new bin when the current item is
    // large and no open bin offers a good fit, or when stream is early and
    // residual capacity in open bins is fragmented. ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Prefer new bin for big items that leave awkward post residuals in old bins.
        if item_size >= 60 {
            score -= 35.0 + 20.0 * (1.0 - progress);
        } else if item_size <= 25 {
            score += 40.0; // small items should fill old bins
        } else {
            score += 10.0 * fragmentation; // mild penalty, fill existing space
        }
        // If many open bins with high mean residual, discourage yet another bin.
        score += open_bins_count as f64 * 1.5 * fragmentation;
    }

    // --- Global pressure: as open bins accumulate, prefer tightening existing bins ---
    if open_bins_count > 4 {
        score -= (mean_residual - post).max(0.0) * 0.3; // favor bins tighter than average
    }

    // Progress-scaled tie-breaker: slight preference for exact-fill arithmetic
    if post_residual == 0 {
        score -= 100.0; // perfect closure is always best
    }

    score
}

