    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Core: strongly prefer tight fits via cubic penalty on wasted space.
    let mut score = x * x * x * cap;

    // Smooth quadratic coupling with stream progress: early on, keep bins
    // flexible (mild penalty for very full bins), later, pack tightly.
