    if nxt > 0.0 {
        let gap = post - nxt;
        if gap >= 0.0 {
            // Next item fits: reward proportionally to how well it nests.
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit: penalize slightly, more mid-stream.
            score += 5.0 * (-gap / cap) * (0.5 + 0.5 * progress);
        }
