        score -= 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    // Pressure rises with fitting bins; extra push when open bins are underfilled
                    let mut pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    if avg_fill < 0.18 {
                        pressure += 50.0 * (0.18 - avg_fill);
                    }
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    let crowd = if open_bins_count > 6 {
                        2.0 * (open_bins_count as f64 / 20.0).min(2.0)
                    } else {
                        0.0
                    };
                    score += pressure + late + crowd;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are best.
    let pr = post_residual;
    let cls: f64 = if pr == 0 {
        -60.0
    } else if pr <= 10 {
        -20.0
    } else if pr <= 25 {
        10.0
    } else if pr <= 50 {
        25.0
    } else {
        5.0
    };
    score += cls;

    // Modulo arithmetic on post residual: residuals that divide capacity into
    // nice classes (multiples of 25, 20, 10) are more reusable.
    if pr % 25 == 0 && pr > 0 { score -= 12.0; }
    if pr % 20 == 0 && pr > 0 { score -= 8.0; }
    if pr % 10 == 0 && pr > 0 { score -= 5.0; }
    // Odd dead-space residuals are penalized mildly.
    if pr % 2 == 1 && pr > 0 && pr < 10 { score += 15.0; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: fraction of residual consumed by next item
            let frac = next_item_size as f64 / pr as f64;
            score -= 15.0 * frac;
        } else {
            // next item won't fit here; penalize small leftovers slightly more
            if pr < next_item_size && pr > 0 {
                score += 6.0 * (1.0 - pr as f64 / cap_f);
            }
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins: reward small post_residual relative to capacity.
    score += 8.0 * (1.0 - post_residual as f64 / cap_f) * (bin_residual < bin_capacity) as i32 as f64;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 15);
        if poor_fit && item_size >= 60 {
            score -= 10.0; // open new bin for big items with poor existing fits
        } else {
            score += 45.0; // discourage opening new bins by default
        }
    }

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mean residual coupling: if this bin is much below mean residual, it's
    // an outlier (mostly empty) -> deprioritize slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Prefer residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // NEW: two-item chain lookahead — reward residuals that exactly fit
            // the next item followed by a plausible follow-up (dead-space suppression)
            if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= 0.15 * cap {
                score -= 4.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: suppress new-bin opening when any open bin leaves a nearly
            // perfect fit for the next item (avoid wasting a fresh bin)
            if next_item_size > 0 && fitting_bins_count > 1 {
                let best_gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64;
                if best_gap <= 3.0 {
                    score += 25.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable (min item size assumed small,
    // but gaps < 15 are hard to fill) -> strong penalty.
    if post_residual < 15 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 20.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here; residual becomes dead space risk.
            score += 10.0;
        }
    }

    // Last-chance bin: only bin that can fit the item -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly via its full residual, and add pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from mean residual:
    // a bin with less-than-mean residual is more "consolidated" -> reward.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate (empty bin): make it only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; relaxed when open bins are crowded.
        score += 45.0 - (open_bins_count as f64).min(20.0);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: perfect match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 350.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        }
        // Penalize leaving residual that next item cannot use but is small (dead space).
        if next_item_size > post_residual && post_residual < 10 {
            score += 120.0;
        }
    }

    // Compare against mean residual across open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 60.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when the stream is late and open bins suffice,
    // unless the item is large and would leave a bad fit elsewhere.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        let waste_penalty = 100.0 + 200.0 * progress;
        // New bin is attractive only if no open bin gives a tight fit.
        if post_residual as f64 > (bin_capacity as f64 - item_size as f64) * 0.9 && fitting_bins_count > 0 {
            score += waste_penalty;
        } else if fitting_bins_count == 0 {
            score -= 300.0; // must open a bin anyway
        } else {
            score += waste_penalty * 0.5;
        }
    }

    // Mild preference for filling larger-residual bins early in the stream.
    score += 0.3 * (bin_residual as f64) * (1.0 - progress);

    // Small tie-break favoring bins that stay close to mean residual.
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

