pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post_residual strongly (quadratic).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: post_residual too small for any future item (1..100).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a penalty that shrinks
    // when the item is large or few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > 50 { 20.0 } else { 0.0 };
        score += 25.0 - large_item_bonus
            - (fitting_bins_count as f64).min(5.0) * 3.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If mean residual across open bins is high, prefer existing bins.
        score += (mean_residual / 10.0).min(10.0);
    }

    // Mild penalty for wasting a large-residual bin on a small item.
    if item_size < bin_residual / 4 {
        score += 6.0;
    }

    // Encourage balancing residuals toward mean when many bins open.
    if open_bins_count > 3 {
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
