    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residues mod 10 define
    // "usable" vs "dead" space classes for typical item granularities.
    let res = post_residual % 10;
    let harmonic_bonus: f64 = match res {
        0 => 12.0,                    // perfectly aligned residual
        1 | 2 | 3 | 4 | 5 => 4.0,     // small slivers, mildly usable
        6 | 7 | 8 | 9 => -6.0,        // awkward dead space class
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: residual that can host a mid-size item
    let usable_slots = post_residual / 20;
    score -= 3.0 * usable_slots as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a new residual: evaluate its class
            let nr = post_residual - next_item_size;
            score -= 8.0 - (nr % 10) as f64 * 0.7;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64).min(40.0) * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor (large, awkward) residuals.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin; slight penalty so decent fits win
        score += 5.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere: open new bin
        }
    } else {
        // prefer tighter existing bins: reward small post_residual nonlinearly
        score -= (bin_capacity - post_residual) as f64 * 0.05;
        // reward bins tighter than the mean residual (good compaction)
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Stream progression: late in the stream, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
