    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to typical residuals, or when open bins are very full.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen on good justification.
        score += 30.0 + 2.0 * open_bins_count as f64;
