    // Mean residual coupling: when average residual is high, prefer
    // consolidating into fuller bins (higher relative fill).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * mean_residual * 0.3;

    // Stream progression: early on, allow slightly more exploration of
    // imperfect fits; later, be strict.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
