    // Global pressure: when many open bins exist, prefer filling existing bins over opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual context: if this bin is below-average full (large residual vs mean), mildly penalize,
    // pushing items into already-degraded bins to consolidate space.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative about opening new bins
    // (penalize new-bin candidate); late in the stream, allow slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Mild penalty for placing small items into large-residual bins early (save big holes for big items).
    if item_size < 30 && bin_residual > 70 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
