pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let mut score = r;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with progress
    let dead = (rn * rn) * (1.0 - rn) * cap;
    score += dead * (0.5 + progress * progress) * 0.5;

    // Reward tight fits more strongly as the stream progresses
    let tight = (1.0 - rn) * (1.0 - rn);
    score -= tight * (1.0 + 2.0 * progress) * 8.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth quadratic overlap)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = rn - nx / cap;
        let overlap = (diff * diff);
        score -= (1.0 - overlap) * 6.0 * (0.5 + progress);
