                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize dead space that no future item can use.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Harmonic class of post_residual: residuals that are "harmonic" (multiples of 10,
    // or small enough to be fillable by typical items) are less wasteful.
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    score -= 6.0 * harmonic;

    // Dead-space penalty grows when residual falls into an awkward class:
    // residuals in (0,10) or (60..80) are hard to fill with items 10..80.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr > 60 {
        score += 8.0 + 0.2 * (pr - 60) as f64;
    }

    // Lookahead coupling: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // Perfect pairing: post_residual equals a harmonic multiple of next item size
            if pr == next_item_size || pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // This bin becomes dead after placement; penalize more if next item is large.
            score += 4.0 + 0.15 * next_item_size as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening a new bin is attractive when open bins are congested or mean residual is tiny.
        if mean_residual < 15.0 {
            score -= 22.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Slight drift with stream progression: later in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: bins whose residual class (pr / 20) is low are preferred.
    score -= 2.0 * ((pr / 20) as f64);

    score
}

