        score -= 30.0; // perfect closure
    } else if post_residual <= 9 {
        score += 25.0; // near-dead space
    } else if post_residual <= 19 {
        score += 12.0;
    }

    // Modulo-class coupling: does the leftover match a plausible item class?
    // Items 10..80; treat residual mod 10 as a compatibility signal.
