        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 18.0;
        } else {
            score -= (post_residual - slack) as f64 * 0.05;
        }
    } else if next_item_size > post_residual {
        // next item cannot follow here; penalize proportionally to wasted room
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    // Integer-division threshold on post_residual / 20: large leftovers are
    // still useful, mild reward scaling.
    let class = post_residual / 20;
    score -= class as f64 * 2.0;

    // Late-stream consolidation: fewer bins preferred as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

