pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more than proportionally.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * pressure;
    } else {
        score -= 4.0 * pressure.min(3.0);
    }

    // Favor bins whose residual deviates below the mean (tighter bins first).
    score -= 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
