pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        if next_item_size == post_residual {
            score -= 400.0; // chain perfect fit
        }
        // Penalize leaving residual that neither fits next item nor is small.
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight packing: penalize large post_residual relative to bin capacity.
    score += 0.8 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Prefer using existing bins over opening new ones, especially late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residual of open bins is very fragmented.
        score += 150.0 + 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 300.0; // no open bin can fit: must open
        } else if fitting_bins_count == 1 && mean_residual > 2.0 * item_size as f64 {
            score -= 50.0; // last chance bin is roomy, avoid wasting it
        }
    } else {
        // Existing bin: reward when it is the only fitting bin (avoid opening new).
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
        // Prefer bins with residual close to item (best fit flavor).
        score -= 30.0 * (1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64)).max(0.0);
    }

    // Coupling with mean residual: favor bins below mean residual (tighter bins).
    score -= 0.4 * (mean_residual - post_residual as f64);

    score
