    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else {
        score += 8.0; // awkward residue
    }

    // Penalize small unusable leftovers (dead space) via integer-division thresholds
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr <= 20 {
        score += 5.0; // borderline: many items are 10-20
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 15.0;
            }
            score += slack as f64 * 0.3;
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let tight = (mean_residual / cap) < 0.35;
        if tight && crowd > 2.0 {
            score -= 18.0;
        } else {
            score += 30.0 + crowd * 2.0;
        }
    }

    // Fraction-of-capacity phase: mid-stream, prefer tighter packing
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * phase;

    // Mild preference toward fuller bins overall
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // COMBINED: scale dead-space penalty by relative residual size (borrowed from best)
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Mild preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // NEW: scarcity-weighted slack reward regardless of progress
            score -= 0.45 * slack * scarcity;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: penalize new-bin opening more when a moderately-tight fit exists
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 0.5 * next.max(1.0) {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space avoidance: residuals too small for the smallest item (1) are
    // only truly dead if below the practical minimum item size; penalize tiny
    // leftover gaps harshly since they are unlikely to be filled later.
    let gap = post_residual as f64;
    if gap < 10.0 {
        // Nearly-dead space: worse than wasting a whole empty bin.
        score += 120.0 * (10.0 - gap);
    } else if gap < 20.0 {
        // Small gap zone: moderate penalty scaled by how tight it is.
        score += 25.0 * (20.0 - gap) / 10.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin; if post_residual can't hold the next item,
    // add a mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the current fit leaves a
    // large unusable gap; otherwise penalize proliferation of open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, grows with number of open bins.
        score += 80.0 + 5.0 * open_bins_count as f64;
        // But if all open bins would leave dead space < 10, prefer a new bin.
        let would_fit_badly = fitting_bins_count > 0 && gap < 10.0;
        if would_fit_badly {
            score -= 200.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come
        // to fill them); late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Open-bin pressure: mildly penalize bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins), nudging toward filling nearly-full bins first.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for larger items going into larger-residual bins.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Scarcity-weighted slack penalty (borrowed idea): when few bins fit,
            // keeping larger slack is more valuable
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual holds two next items -> strong candidate
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: partially recoverable, slightly less bad
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing material
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                }
            }
        }
        // Late-stream pressure: many open bins, low mean fill -> prefer fresh bin less
        if open_bins_count > 4 && progress > 0.5 && avg_fill_guard(mean_residual, cap) < 0.18 {
            score += 5.0 * (0.18 - avg_fill_guard(mean_residual, cap)) * 10.0;
        }
        if progress > 0.6 && open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

#[inline]
fn avg_fill_guard(mean_residual: f64, cap: f64) -> f64 {
    mean_residual / cap.max(1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
