pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect exact match gets a big bonus
        if match_gap < 0.5 {
            score -= 40.0;
        } else {
            // Reward proportional closeness of the lookahead fit
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the resulting residual: penalize dead space
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual is far below mean (waste-prone), reward above-mean residuals
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream: encourage consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate should only win when existing fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
