pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large leftover space.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 4.0 * fit_gap;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize dead space the next item cannot use.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> discourage new bins, encourage filling.
    let pressure = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
    score -= 5.0 * pressure * (mean_residual / bin_capacity as f64).min(1.0);

    // New-bin candidate: penalize opening a bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * t;
    }

    // Small bonus for bins already heavily loaded.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
