pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), scaled by capacity.
    let mut score = post / capacity;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late in the stream, penalize them quadratically.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let tightness = post / capacity;
    score += tightness * (0.5 + 2.5 * p2 + 3.0 * p3);

    // Smooth penalty for dead space relative to mean residual of open bins.
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let excess = post - mean;
    score += 0.15 * excess * excess / capacity;

    // Reward filling bins completely (post_residual near 0) with a smooth term.
    score -= (1.0 - tightness) * (1.0 - tightness) * 0.5;

    // Lookahead: reward leaving space for the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.1 * gap / capacity;
        // Strong reward when post-residual exactly accommodates the next item.
        score -= 0.4 * (1.0 - gap / capacity);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Slight preference for reusing bins over opening new ones, decaying with stream progress.
    if bin_residual == bin_capacity {
        score += 0.8 - 0.5 * progress;
    } else {
        score -= 0.1 + 0.3 * p2;
    }

    // Mild penalty for many open bins (encourage consolidation), smooth in count.
    score += 0.02 * (open_bins_count as f64).powf(1.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
