    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Class via integer division thresholds (capacity fractions).
        let cls = post_residual / 10; // classes 0..=10
        let class_penalty = match cls {
            0 => 60.0,          // 1..9: nearly unusable dead space
            1 => 30.0,          // 10..19
            2 => 15.0,          // 20..29
            3 => 5.0,           // 30..39
            4 | 5 => -5.0,      // 40..59: useful for mid items
            _ => 0.0,           // large residual still flexible
        };
        score += class_penalty;

        // Modulo-10 harmony: residual divisible by 10 pairs well with typical sizes.
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement possible: reward, stronger the tighter the chain fit.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 12.0 - chain_tightness * 0.15;
            // Harmonic pair: next_item_size + item_size divides capacity nicely.
            if (item_size + next_item_size) % 50 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize leaving residual in the gap band
            // that is just barely too small (dead zone).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 10.0 - gap; // just-missed chains are worst
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect last chance
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let mean_gap = (mean_residual - item_size as f64).abs();
        // Base penalty so new bins are used only when needed.
        score += 40.0 + crowd * 2.0 - progress * 5.0;
        // If mean residual of open bins barely fits the item, opening new bin is fine.
        if mean_residual < item_size as f64 + 3.0 {
            score -= 30.0;
        }
        if mean_gap < 2.0 {
            score -= 10.0;
        }
        // Large items favor fresh bins.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Prefer fuller bins overall: closeness of fill to capacity.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Slight preference for tight fits measured directly.
    score += (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1..10)
    // are pure waste; penalize them strongly with a nonlinear curve.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones;
    // when few bins are open, allow opening new bins more freely.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * 6.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.15;
    }

    // Progress factor: late in the stream, tighten up (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0;

    // Prefer bins whose residual is close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-match lookahead: if the next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If the next item also fits in this bin afterwards, reward chained placement.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * chain_waste;
    }
    // Dead space: post_residual too small for the next item -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if lookahead shows the next item pairs well with a fresh bin, soften.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 4.0;
        }
    }

    // Late in the stream, prefer tightening existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // NEW: scale dead-space penalty with relative gap (borrowed from best)
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // NEW: stronger scarcity-driven slack preference late in stream
            score -= 1.4 * slack * scarcity * progress;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // NEW: late-stream strong preference for near-full bins (residual variance reduction)
    if progress > 0.6 {
        let fill = (cap - pr) / cap;
        score -= 6.0 * fill * (progress - 0.6) * 2.5;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: raise new-bin pressure when a fitting bin is a near-exact fit
            if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                if slack <= 10.0 {
                    score += 12.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large wasted residual, especially small "dead" slivers.
    if post_residual > 0 {
        let dead_penalty = (bin_capacity as f64 / post_residual as f64).recip() * 40.0;
        score += dead_penalty;
    } else {
        score -= 30.0; // perfect fit is great
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: generally discouraged unless nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 45.0 - desperation * 55.0;
        // Opening a new bin is more attractive late in the stream? No: keep bins tight early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else {
            score -= 12.0 / gap;
        }
    }
    // If next item won't fit here anyway, mild bonus for consuming residual now.
    if next_item_size > post_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference to fill bins when many are open (consolidation).
    score += open_bins_count as f64 * 0.3;

    // Prefer placing larger items into tighter bins.
    score -= (item_size as f64 / bin_capacity as f64) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;

    // Base: post-residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.35 * prn * prn);

    // Stream-progress coupling: penalize large residuals more as stream advances
    score += 20.0 * prn * prn * progress;

    // Reward tight fits: small post residual gets subtraction, amplified by progress
    score -= 15.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Dead-space penalty: residuals too small for typical future items
    if next_item_size > 0 {
        let nn = next_item_size as f64 / cap;
        if prn < nn {
            score += 10.0 * (nn - prn) * (1.0 + progress);
        } else {
            score -= 5.0 * (prn - nn) * prn;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Many open bins: encourage consolidation by penalizing high-residual bins mildly
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * prn;

    // Deviation from mean residual: prefer bins near (or below) mean to keep balance
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Smooth new-bin tie-break: empty bin gets slight bias toward use as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress * irn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let pr = post_residual;
    // Reward post-residuals that lie in "friendly" classes (divisible by small sizes)
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        if pr % 5 == 0 { harmony += 2.0; }
        score -= harmony;
        // Penalize awkward mid-range dead space
        if pr > 5 && pr < 10 { score += 8.0; }
        if pr > 30 && pr < 40 { score += 3.0; }
    }

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fill fraction bonus (nonlinear)
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // dead space relative to lookahead
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
        // harmonic match: post_residual and next_item share a divisor class
        if next_item_size > 0 && post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when residuals are fragmented
    if bin_residual == bin_capacity {
        // baseline attractiveness of a fresh bin
        score = cap - item_size as f64; // post_residual of fresh bin
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        } else {
            // penalize new bin when mean residual is still useful
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let usefulness = mean_residual / cap;
            if mean_residual >= next_item_size as f64 && next_item_size > 0 {
                score += 40.0; // existing bins can host the next item too
            }
            score += usefulness * 20.0 * (1.0 - progress);
            if fitting_bins_count > 2 {
                score += 15.0;
            }
        }
    }

    // Slight preference to fill bins with larger residual first when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual that no future item can use
    // (smaller than the next item and smaller than the minimum plausible item)
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 60.0 + (next_item_size - post_residual) as f64;
        }
        if post_residual < 10 {
            score += 80.0; // tiny unusable gap
        }
        // Dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + open_bins_count as f64 * 8.0;
        // Opening a new bin is acceptable early in the stream or when existing
        // residuals are small (mean residual low => existing bins nearly full)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0 + mean_residual * 0.3;
    } else {
        // Reward placing into bins with low residual (tight packing)
        score += mean_residual * 0.1;
    }

    // Prefer bins whose residual is close to the item (minimal waste)
    score += (bin_residual - item_size) as f64 * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
