}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0 (nonlinearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 15.0 * (1.0 - gap);
        } else {
            // Penalize leaving residual that no next item can use relative to mean residual.
            let dead = (post_residual as f64 - mean_residual).max(0.0);
            score += 0.5 * dead;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins with residuals far from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Prefer filling bins with low residual among many open bins.
    score += 0.1 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize existing bins less); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when it produces a good future
    // residual profile (i.e., residual after placement is small relative
    // to next item) or when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 1 {
            score += 10.0; // discourage opening a bin when alternatives exist
        }
    }

    score
}

