pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // mid-stream, tight fits are rewarded; early/late, waste matters more.
    let bump = (progress * std::f64::consts::PI).sin();
    score -= bump * 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize residual that cannot fit the lookahead item (smooth quadratic).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 20.0 * gap * gap * cap;
        } else {
            // reward leftover that still fits next item
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for bins deviating from mean residual (consolidation).
    score += 0.1 * (pr - mean_residual).abs();

    // Discourage opening new bins when open bins fit well.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Polynomial shaping of waste: small residuals are dead space, penalize quadratically.
    score += 4.0 * norm_pr * norm_pr * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions (C=100 assumed).
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    // Class 0: post_residual is exact multiple of small harmonic steps (10/20/25/50)
    if pr == 0 {
        score -= 900.0;
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 {
        score -= 40.0; // clean divisible dead space, likely reusable
    } else if pr < 10 {
        // dead space too small for any item: penalize
        score += 60.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // reward residual that can host next item, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = bin_capacity as f64 - mean_residual;
        // prefer new bin only if existing bins are quite full on average
        score += 200.0 + 100.0 * (1.0 - progress) - 1.5 * avg_fill;
    }

    // Prefer packing into bins whose residual is close to item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    // Slight preference for bins with larger residual among equals (use emptier bins first).
    score -= 0.05 * bin_residual as f64;

    // Mild penalty for too many open bins relative to progress (encourage consolidation early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 2.0 + 10.0 * progress {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // Tight-chain bonus: scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Scarcity-weighted slack reward (borrowed from best): fewer fitting bins -> reward slack more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Two-of-next chain: residual can host next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        } else {
            // bin can't host next item: penalize leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            // Two-step dead-space lookahead: unusable residual is worse
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-fit check: residual barely below next item is especially wasteful
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            } else if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residual scraps are cheap to close out
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            // Large next item: a fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when open bins already hold near-exact fits
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    // Fragmented open-bin pool: fresh bin slightly more acceptable
                    let frag = if avg_fill < 0.18 && progress > 0.5 { 5.0 * (0.18 - avg_fill) * 10.0 } else { 0.0 };
                    score += pressure + late + frag;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "dead". Penalize them heavily, with a
    // graded penalty as the gap approaches unusability.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // semi-dead zone: only very small items could fit
        score += 25.0 - (post_residual - dead_threshold) as f64 * 1.5;
    }

    // Reward perfect / near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness ratio bonus: the fuller the bin becomes, the better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= dead_threshold {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer closing out existing bins rather than fragmenting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * (6.0 + 8.0 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "small" bin we should drain first.
    let residual_gap = mean_residual - post_residual as f64;
    score -= residual_gap * 0.4;

    // New-bin candidate logic: an empty bin is attractive only when the
    // item is large (would leave an awkward gap in a partial bin) or when
    // no good fits exist. Penalize the fresh bin mildly otherwise so
    // existing bins win, but give it a lookahead edge.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual { 15.0 } else { 0.0 };
        score = 45.0 - 55.0 * large_item + lookahead_bonus
            + (open_bins_count as f64) * 3.0 * (1.0 - progress);
        // If current item nearly fills the bin, a fresh bin is great.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 40.0;
        }
    } else {
        // Lookahead: if the next item fits exactly into the post-residual,
        // reward creating that opportunity.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // next item can't follow here; slightly penalize leftover gap
            score += (post_residual as f64) * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item still fits in the leftover space -> moderate reward, scaled by how snug.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.15 * snug;
    }

    // Next item does NOT fit: leftover is likely dead space -> penalize large leftovers,
    // especially small-but-unusable residuals (worst waste zone).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 + 0.10 * post_residual as f64;
    }

    // Penalize residual far below mean residual (creating atypical tiny holes).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Late in stream: tighten packing, discourage waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: tighten fill.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Penalize small dead space that no future item (>=10) can use.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual <= 20 {
        score += 3.0;
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Chain fit: residual also fits next item with room to spare.
            if post_residual >= next_item_size + 10 {
                score -= 2.0;
            }
        } else {
            // This placement blocks the next item's reuse of this bin.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Perfect lookahead pair: item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when
    // many bins are already open; make empty-bin score unattractive
    // unless it's genuinely needed.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.8;
        // Early in stream, allow more bin openings.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0;
    }

    // Prefer bins with below-average residual (tighter consolidation).
    score += (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for keeping the number of open bins down.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
