            if next_item_size > 0 && post_residual > next_item_size / 2 && post_residual < next_item_size {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

