    // Lookahead coupling: if next item fits into post_residual, big reward (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack = (pr as f64 - nx) / cap;
            score -= 14.0 * (1.0 - slack) * (1.0 - slack);
        } else {
