    // New-bin candidate handling: make empty bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        // Smooth: new bin score rises with mean residual and scarcity of fitting bins.
        score = cap * (0.35 + 0.5 * crowding * crowding) - 30.0 * scarcity * (1.0 - progress);
