    // Mild penalty when bin residual deviates from mean residual (prefer balanced bins),
    // with smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Small reward for tight fits relative to item size (non-linear in item/capacity).
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * (1.0 - fill);

    score
}

