pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "small" class (fits likely future items) are rewarded.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class A: post_residual small enough to hold a typical next item -> reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus: leftover can host the lookahead item.
            score -= 6.0 + 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty, scaled by how "wasted" the leftover is.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * waste * waste;
        }
        // Exact-fit chain: post_residual equals next item size -> perfect pairing.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands of C=100).
    let band = post_residual / 10; // 0..=10 harmonic class
    match band {
        0 => score -= 8.0,           // near-perfect fill
        1 | 2 => score -= 4.0,       // small usable leftover
        3 | 4 => score -= 1.0,       // neutral
        5 | 6 => score += 2.0,       // awkward mid leftover
        _ => score += 5.0,           // large leftover: wasteful bin
    }

    // Modulo arithmetic: leftover divisible by common item granularities is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it only wins when open
    // bins would create big dead space, unless stream is early or bins are scarce.
    if bin_residual == bin_capacity {
        let dead_space_avoided = (post_residual as f64).max(0.0);
        score += 9.0 - 0.05 * open_bins_count as f64 - 10.0 * (1.0 - progress);
        let _ = dead_space_avoided;
