    // even the smallest plausible item are "dead" — penalize heavily.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(item_size as f64);
        if (post_residual as f64) < dead_threshold {
            score += 25.0; // unusable sliver
