    // Exact / tight fit reward: relative fill of the bin.
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * fill;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 10.0 + 5.0 * pressure;
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the lone fitting bin
