        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // COMBINED: scarcity-weighted slack shaping from best heuristic
            if slack > 20.0 && fitting_bins_count <= 2 {
                score -= 0.6 * (slack - 20.0) * scarcity;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // COMBINED: residual-value shaping for dead residuals (from best)
            let rel = next / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual >= 2 * next_item_size {
        score -= 3.0;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that is too small for typical items (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving large gap it can't use
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, modulated by how full the fleet is
        score += 12.0;
        score -= 4.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // If many bins open and mean residual large, prefer reusing
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward using bins that are already fairly full
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * fill;
    }

    // Time horizon: early in stream, be conservative (favor compacting existing bins);
    // late in stream, allow opening new bins more freely
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    } else {
        score -= 4.0 * (1.0 - progress);
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    // Reward placing into bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

