pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // waste matters more as the stream matures.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward residual that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize bins far from the mean residual (encourage homogeneous fill),
    // with weight growing over the stream.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.3 + 0.7 * progress);

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 * (0.5 + progress);
