pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are "harmonic" and more likely to be filled later.
    let post = post_residual;
    let mut harmonic_bonus = 0.0;
    if post > 0 {
        if post % 50 == 0 { harmonic_bonus += 6.0; }
        else if post % 25 == 0 { harmonic_bonus += 4.0; }
        else if post % 20 == 0 { harmonic_bonus += 3.0; }
        else if post % 10 == 0 { harmonic_bonus += 2.0; }
        // dead-space class: small odd residuals are hard to fill
        if post < 10 { harmonic_bonus -= 8.0; }
        else if post < 20 && post % 10 != 0 { harmonic_bonus -= 4.0; }
    } else {
        // perfect fit
        harmonic_bonus += 10.0;
    }
    score -= harmonic_bonus;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post { score -= 12.0; }
        else if post >= next_item_size {
            score -= 3.0;
            // harmonic pairing: next item leaves another harmonic residual
            let pp = post - next_item_size;
            if pp % 25 == 0 || pp % 20 == 0 { score -= 2.0; }
        } else {
            score += 4.0; // next item won't fit here; this residual likely dead
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has neutral-ish score unless
    // current open bins are poor fits / fragmented.
    if bin_residual == bin_capacity {
        score = 55.0;
        // open a new bin early when few bins open (keeps future flexibility)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        // penalize opening bins when good fits exist
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Prefer fuller bins (lower residual relative to mean)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    score
}

