pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly unusable
    // for future items (sizes 1..100, realistically >=10 in classic streams).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // hard penalty for creating dead space
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0; // mildly risky gap
    }

    // Reward very tight fits (post_residual near zero but not zero already low).
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (which the new-bin candidate would otherwise win).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it unattractive
    // unless open bins are scarce or the fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 5.0;
        // If the item would leave a large residual anyway, new bin is fine.
        if post_residual >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones, avoid spreading.
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0; // next item fills this bin nicely
        } else if slack <= 15 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // next item cannot use this residual at all
    }

    // Mean residual coupling: bins far below mean residual are "wasted" capacity;
    // prefer bins whose residual is close to the item (small relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * mean_residual * 0.5;

    // Early stream: be a bit more willing to open bins (spread items), late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
