            // Next item still fits: reward closeness of match relative to mean residual.
            let tightness = (pr - nxt) / pr.max(1.0);
            score -= 100.0 * (1.0 - tightness);
        } else {
            // Next item won't fit: penalize leftover space, scaled by how wasted it is.
            let waste = (nxt - pr) / bin_capacity as f64;
            score += 80.0 * waste;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // A bin left with residual far below the mean creates isolated dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let dev = (pr - mean_residual) / cap;
    if dev < 0.0 {
        // Below-mean residual: slightly penalize very small leftovers (hard to reuse).
        score += 20.0 * (-dev);
    } else {
        // Above-mean residual: mildly reward keeping usable space.
        score -= 10.0 * dev;
    }

