        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: discourage new bins late when decent fits exist
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth progress coupling: early in the stream tolerate larger residuals
    // (bins can be filled later); late in the stream penalize them more.
    let progress_weight = 0.6 + 1.4 * progress * progress;
    score *= progress_weight;

    // Interaction: residual vs mean residual — penalize bins that deviate
    // from the fleet's average residual, scaled smoothly by progress.
    let dev = pr - mean_residual;
    score += 0.35 * dev * dev / cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward a post_residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack_fit) * (1.0 + progress);
        } else {
            // Post-residual too small for next item: penalize dead space smoothly.
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).sqrt() + 15.0 * progress;
    }

    // Tiny smooth tie-breaker favoring tighter fits.
    score += (item_size as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
