pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition into capacity-fraction classes
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
    let mut bonus = 0.0;

    // Reward near-exact closure (post_residual in tiny class)
    if pr == 0 {
        bonus -= 60.0; // perfect fit
    } else if pr <= eighth {
        bonus -= 30.0; // excellent fit class
    } else if pr < quarter {
        bonus -= 12.0; // decent fit class
    } else if pr == quarter || pr == 2 * quarter || pr == 3 * quarter {
        bonus -= 8.0; // harmonic multiples of quarter: clean future splits
    } else {
        bonus += 5.0; // awkward dead space class
    }

    // Modulo-10 class coupling: residual compatible with typical item granularity
    let m = pr % 10;
    if m == 0 {
        bonus -= 6.0;
    } else if m <= 3 {
        bonus -= 2.0;
    } else if m >= 7 {
        bonus += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            bonus -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            bonus -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize blocking a better future use
            bonus += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        bonus -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        bonus += 35.0;
        if fitting_bins_count == 0 {
            bonus -= 100.0; // no alternative: must open
        }
    }

    // Tighten toward mean residual: prefer bins below mean (denser bins)
    bonus -= 0.3 * (mean_residual - bin_residual as f64);

    // Progression: as stream advances, be greedier about closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    bonus -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
