pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 9) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Gap cannot host the next item: mild penalty scaled by how close it is.
            score += 4.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading, favor filling.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins with residuals near the mean (balanced packing),
    // but only mildly so tight fits still dominate.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Early in the stream, be more willing to open fresh bins (cheap now,
    // useful later); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: acceptable early, costly later; baseline so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 0.2 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 5.0; // fresh bin always fits the lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low post_residual)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0 + (10 - post_residual) as f64 * 5.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // next item cannot fit here; penalize large dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new empty bin mildly unless the fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if next item is large and this item is small, a fresh bin is fine
        if next_item_size > 0 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing (prefer tight fits more aggressively)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
