            let dead_rel = gap / cap;
            score += 40.0 * dead_rel * (1.0 - progress);
            // strongly quadratic dead-space penalty (from best heuristic)
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // near-half-dead residuals: discourage unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // half-usable residual: mild extra penalty early
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
