}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr);
    score += 30.0 * coupling * (0.5 + progress);

    // Penalize large residuals late in the stream (dead space matters more)
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward tight fits: low post_residual gets bonus, stronger early
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / cap);
    }

    // New-bin candidate: penalize opening a bin when decent fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 8.0 + 10.0 * progress;
    }

    // Mean residual coupling: prefer bins near the mean (keeps residual distribution balanced)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual (modulo arithmetic) ---
    // Residuals that are "nice" multiples of small harmonics are more reusable.
    let pr = post_residual as i64;
    if pr > 0 {
        // Reward residuals divisible by common item harmonics (10, 20, 25, 50)
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Penalize awkward residuals in dead zones (1..9, 11..19 odd leftovers)
        if pr < 10 { score += 25.0; }          // nearly unusable dead space
        else if pr < 20 && pr % 2 == 1 { score += 8.0; }
        // Integer-division threshold: floor(pr/10) class
        let cls = pr / 10;
        score -= cls as f64 * 1.5;             // bigger usable residual preferred
    } else {
        // Perfect fill is excellent
        score -= 40.0;
    }

    // --- Tight fit reward: how much of the bin is consumed ---
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if post_residual == next_item_size as u32 {
            // This placement sets up an exact fit for the next item
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here afterwards
            score -= 5.0;
        } else {
            // Next item won't fit in residual: mild penalty scaled by gap
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.3;
        }
        // Harmonic match: residual is a multiple of next item's class
        if next_item_size > 0 && pr > 0 && pr % (next_item_size as i64) == 0 {
            score -= 12.0;
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- Mean residual coupling: prefer bins below mean (tighter bins) ---
    score += (mean_residual - post_residual as f64) * 0.4;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful if existing bins fit decently;
        // penalize proportionally to open bins and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        // But if item is huge and leaves a harmonic-friendly residual, allow it
        if fill_frac > 0.8 { score -= 20.0; }
    }

    // --- Late-stream consolidation pressure ---
    let prog = step_index as f64 / total_items.max(1) as f64;
    score -= prog * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
