    // Penalize small-but-usable gaps less harshly, scaled by how tight they are.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
    } else {
        // Slight preference for bins with lower residual (tighter packing).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
