pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild tightness preference; late: strong tightness preference.
    let tightness = base * base / cap;
    let coupling = base * (0.5 + 1.5 * progress) + tightness * (0.3 + 1.7 * progress * progress);

    // Reward placements that leave room for the lookahead item (smooth interaction).
    let lookahead = next_item_size as f64;
    let lookahead_term = if next_item_size > 0 {
        let gap = (pr - lookahead).abs();
        -0.6 * (1.0 - gap / cap) * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Penalize deviation from mean residual (keeps bin pool homogeneous).
    let homogeneity = 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin: strong reward to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -8.0 * (1.0 + progress) } else { 0.0 };

    // New empty bin candidate: penalize unless residuals are badly fragmented.
    let new_bin = if bin_residual == bin_capacity {
        6.0 + 4.0 * progress + 0.05 * open_bins_count as f64
    } else {
        0.0
    };

    let mut score = base + coupling + lookahead_term + homogeneity + last_chance + new_bin;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
