pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 4 quarters.
    let quarter = bin_capacity / 4;
    let class = match post_residual {
        0 => 0u32,                       // perfect fit
        p if p < quarter => 1,           // small dead space
        p if p < 2 * quarter => 2,
        p if p < 3 * quarter => 3,
        _ => 4,
    };

    // Reward perfect fits and tight fits strongly.
    score -= match class {
        0 => 60.0,
        1 => 25.0,
        2 => 10.0,
        _ => 0.0,
    };

    // Modular harmonic classes on post_residual (mod 10): residuals divisible
    // by 10 are "harmonious" with typical item sizes drawn from 1..=100.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m <= 3 {
        score += 3.0 + m as f64;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 30.0 + 0.3 * slack as f64;
        // Extra harmonic bonus if next_item_size aligns with post_residual class.
        if (post_residual % 10) == (next_item_size % 10) {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // Dead-space penalty scaled by how far next item overshoots.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Integer-division threshold: penalize leaving more than half a bin empty
    // unless this bin is the only fitting option.
    if post_residual > bin_capacity / 2 {
        score += 12.0;
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current bin fit
    // is poor (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.4 * post_residual as f64
            + 0.05 * open_bins_count as f64
            + 20.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference to balance residuals toward the mean across open bins.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

