pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // reward proportional to how much of post_residual the next item consumes
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 35.0 * fill;
        } else {
            // next item does not fit; penalize leaving awkward dead space
            let dead = (post_residual as f64) / (next_item_size as f64);
            score += 12.0 * (1.0 - dead.min(1.0));
        }
    }

    // Penalize post_residual far from typical useful sizes (small residuals are dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Compare against mean residual across open bins: prefer bins with less residual than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // if other bins can fit the item, make new bin less attractive unless fits are bad
        if fitting_bins_count > 0 {
            let best_possible = if next_item_size > 0 { 0 } else { 0 };
            let _ = best_possible;
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Penalize leaving residual that is small but not zero (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer filling existing ones rather than opening new
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += open_pressure * 3.0;

    // Compare residual to mean residual: bins below mean residual are "fuller", favor them
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - tightness);

    // New empty bin candidate: penalize unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * t) + pr_norm * (1.0 - t) * (1.0 - t);
    score += 8.0 * coupling;

    // Penalize large residual late in the stream (wasted space harder to fill)
    score += 6.0 * pr_norm.powi(3) * t;

    // Reward tight fits (small post_residual) especially when many bins are open
    let tightness = 1.0 - pr_norm;
    score -= 4.0 * tightness * tightness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - pr_norm) * t;
    }

    // Penalize bins far from mean residual to keep diversity of residual sizes
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    // Slight preference for using existing bins over opening new ones early
    score -= 1.0 * (1.0 - t) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residual mod capacity fractions.
    // Perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fractional class of post_residual relative to capacity (eighths).
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 0..7
    match class {
        0 => score -= 40.0,          // tiny dead space, great fit
        1 => score -= 20.0,          // <= 12.5% waste
        2 => score -= 5.0,
        3 => score += 10.0,
        4 => score += 25.0,          // ~half empty: mediocre
        5 => score += 35.0,
        6 => score += 20.0,
        _ => score -= 15.0,          // nearly empty bin, flexible
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact class match: post_residual == next_item_size is gold.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // Reward proportional to how tight the lookahead fit is.
                score -= 60.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 30.0 + 0.5 * (post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.5;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
        // If next item is huge and post_residual here would be zero anyway,
        // opening a fresh bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Modulo-10 harmonic tiebreak on post_residual: multiples of 10 pair well
    // with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

