pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (exact fills are ideal)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the next item (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: penalize using bins when many are open (prefer filling existing ones)
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow new bin if this item would create dead space in every existing bin
        if post_residual > 0 && post_residual < 10 && fitting_bins_count > 0 {
            score -= 55.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // tight coupling: closer post_residual is to next item, the better
            score += gap * 0.35;

            // if next item fits after this placement, mild reward
            if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        // dead space after two steps: post_residual smaller than next item is waste
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // last item: minimize leftover aggressively
        score += post_residual as f64 * 0.5;
    }

    // Tight-fit reward relative to current residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0;
    }

    // Penalize deviation from mean residual (avoid creating outliers)
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.15;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
