pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score -= 6.0; // next item can still go here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = avg_fullness * (0.5 + 0.5 * progress);
        score += 40.0 * (1.0 - pressure);
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative, new bin is fine
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in stream: be more conservative, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.4 * progress * (post_residual as f64 / bin_capacity as f64);

