                score += 30.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..10 harmonic class

    // Penalize dead space non-linearly; small residuals (<=10) are nearly perfect fits.
    if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 6.0;
    } else {
        // Modulo-style penalty: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are reusable; odd remainders are dead space.
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 10 == 0 { 12.0 }
            else if r % 25 == 0 { 9.0 }
            else if r % 20 == 0 { 7.0 }
            else if r % 5 == 0 { 3.0 }
            else { -4.0 };
        score -= harmonic_bonus;
        // Squared waste penalty scaled by stream progression.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += (post_residual as f64).powi(2) / (bin_capacity as f64) * (0.4 + 0.6 * progress);
    }

    // Lookahead: strongly reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // Next item can't use leftover: penalize leaving stranded space.
        score += 6.0 + (class as f64) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are very fragmented
