    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / item_size.max(1) as f64;
        if fragmentation < 1.0 {
            score -= 10.0 * (1.0 - fragmentation);
        } else {
            score += 15.0 * (fragmentation - 1.0).min(3.0);
        }
        if open_bins_count > 0 && post_residual == 0 {
            score -= 5.0;
        }
    }

    // Mild preference for bins tighter than the current mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

