            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: penalize new bins more when the best fit is decent (slack <= 8)
            if next_item_size > 0 && fitting_bins_count > 0
                && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 8.0 {
                score += 10.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < ~10) are wasted capacity.
    // Penalize unusable gaps super-linearly.
    let dead = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64 * 6.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let pressure = (open_bins_count as f64).powf(0.8) * 2.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the lookahead item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powi(2) * 30.0
        } else {
            0.0
        };
        // Base cost of a fresh bin: high unless residuals are fragmented.
        score += 55.0 + (mean_residual / bin_capacity as f64) * 20.0 - lookahead_pressure;
        // Late in the stream, opening bins is fine (no future to plan for).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    } else {
        // Existing bin: bonus if it can also serve the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            // Post residual too small for the lookahead: mild penalty.
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit reward (small post_residual preferred)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain completion: bin becomes exactly full
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward if next item fits, penalize proportionally to leftover gap
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does not fit: penalize dead space that is too small to be useful
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // near-full bin is fine
            } else {
                score += 8.0 * (dead / bin_capacity as f64);
            }
        }
    } else {
        // last item: strongly prefer filling bins as much as possible
        score -= 40.0 * tightness;
    }

    // Compare against mean residual: bins with residual near mean are "typical";
    // prefer placing into larger-than-mean residual bins to preserve tight bins
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 6.0 * ((res - mean_residual) / bin_capacity as f64);
    } else {
        score += 6.0 * ((mean_residual - res) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and few bins fit it
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // early stream: more willing to open bins; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * pressure * item_frac * (1.2 - progress);
        // penalize new bin if many open bins have plenty of room
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0;
        }
        // never open a new bin for a tiny item late in the stream
        if item_size < 30 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Mild penalty for waste overall
    score += 0.05 * post_residual as f64;

    // Small tie-break noise-free deterministic jitter based on state
    score += 0.01 * ((open_bins_count as f64) * (step_index as f64 + 1.0)).sqrt();

    score
}

