    score -= 18.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 {
        score -= 6.0; // small dead space is fine (bin nearly perfect)
    } else if post_residual < 20 {
        score += 4.0; // awkward gap zone
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large leftover only mildly
            score += 2.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are fragmented/full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is penalized normally, but rewarded when existing
        // residuals are small (nothing useful to pack into).
        score += 30.0 - 45.0 * (1.0 - fragmentation) - 10.0 * progress;
        // If no other bin fits, new bin is the fallback: reduce its score.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Global state: with many open bins, prefer consolidating into high-residual bins.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild time-horizon shaping: early on, be slightly greedy for tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * fit_ratio * 5.0;

    // Mean-residual coupling: if average residual is large, prefer bins above mean.
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

