pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: penalize large leftover (waste), but non-linearly.
    let mut score = x * x * cap + 0.35 * pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly; late, punish dead space more.
    let coupling = (0.5 - progress) * (x - 0.35) * (x - 0.35) * cap;
    score += 2.0 * coupling;

    // Smooth reward for tight fits (small post_residual), stronger as stream progresses.
    let tightness = (1.0 - x).powi(3);
    score -= 6.0 * tightness * (0.5 + progress);

    // Penalize post_residual that cannot fit the next item (dead space) — smooth gate.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = (nx - x).max(0.0) / cap;
        score += 4.0 * unusable * pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.15 * open_bins_count as f64 * x;

    // Reward bins whose residual is near the mean residual (harmonized packing).
    score -= 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make empty bins moderately attractive only when
    // remaining residual of open bins would be very tight or stream is early.
    let is_new = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new {
        score += 3.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in the low band (1..item_size range
    // of typical future items) is unusable, so penalize it superlinearly.
    let post = post_residual;
    if post > 0 && post < 10 {
        score += 60.0 * (10.0 - post as f64) / 10.0;
    } else if post >= 10 && post < 20 {
        score += 15.0 * (20.0 - post as f64) / 10.0;
    }

    // Perfect fit reward (modulo-style class: post_residual == 0).
    if post == 0 {
        score -= 120.0;
    }

    // Reward bins whose post-residual can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 25.0;
            // Extra reward if the lookahead would then also leave a large-enough class residual.
            let post2 = post - next_item_size;
            if post2 >= 10 {
                score -= 10.0;
            } else if post2 > 0 {
                score += 5.0; // creates new tiny dead space for the next step
            }
        } else {
            score += 8.0; // lookahead cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if the current best fit
    // would be terrible. Fresh bin has residual == capacity, so give it a baseline
    // penalty that tight fits overcome.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If the stream is early, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins whose residual deviates from the mean in the "tighter" direction.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    // Harmonic capacity-fraction class: residuals that are exact fractions of
    // capacity (25/50/75) are reusable anchors; reward leaving them.
    let cap_u = bin_capacity;
    if post == cap_u / 4 || post == cap_u / 2 || post == 3 * cap_u / 4 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

