    // Perfect fill: zero waste.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1;
    }
    // Penalize if post residual blocks the next item while it would fit elsewhere.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when open bins are nearly saturated
    // or mean residual is very low (no good home available).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0;
        }
        if post_residual == bin_capacity {
            // never open a bin for nothing (shouldn't happen, guard anyway)
            score += 1000.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.3;

    // Mild progress scaling: early in the stream, be slightly more willing
    // to open bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

