        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Waste-density shaping: penalize leaving residuals that are unlikely usable
    // (small odd leftovers below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Scarcity: slack more valuable when few bins can host next item
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            // bin can't host next item: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // Relative dead-space shaping borrowed from best heuristic
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: tiny residuals are worth finishing
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Loose fit among many candidates
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        if post_residual < 2 * next_item_size {
            score += 0.8 * slack / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Penalize creating tiny unusable dead space (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 18.0 * chain_fit;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for blocking.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large or few fitting bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        // Penalize new bins generally, but less when item is big or many open bins are fragmented.
        score += 20.0 - 15.0 * pressure - (open_bins_count.min(10) as f64);
        if post_residual > bin_capacity / 2 {
            score += 10.0; // wasteful empty-bin opening
        }
    }

    // Global fragmentation awareness: prefer bins below mean residual (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Mild time-horizon scaling: early on, be more conservative about residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    score
}

