    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them quadratically.
    let prn = pr / cap; // normalized residual in [0,1)
    let prog_term = (0.5 + progress) * prn * prn * cap;
    score += prog_term;

    // Smooth reward for near-perfect fits (post residual small relative to item)
    let tightness = (it - pr).max(0.0) / cap;
    score -= 12.0 * tightness * (1.0 - prn) * (1.0 - prn);

    // Penalize residuals that cannot fit the next item (lookahead), smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * cap * (0.5 + progress);
        } else {
            // smooth reward when next item fits perfectly
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strong smooth discount to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - prn);
    }

    // New-bin candidate: mildly discourage unless residual pressure is high
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 5.0 + 10.0 * (1.0 - pressure) * (1.0 - progress);
    }

    // Mild penalty for very many open bins with scattered residuals
    let scatter = (mean_residual - pr).abs() / cap;
    score += 2.0 * scatter * scatter * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
