    // Harmonic class of the leftover space: classify post_residual by capacity fractions
    // (0..12, 13..25, 26..50, 51..75, 76..100 style thresholds via integer division)
    let post_class = post_residual / 13; // 0..=7 harmonic buckets
    let class_penalty: f64 = match post_class {
        0 => -6.0,                    // near-perfect fill: strongly reward
        1 => -3.0,                    // small dead space: mild reward
        2 => 1.5,                     // awkward ~26-38 leftover
        3 => 0.0,                     // ~39-51 leftover: neutral
        4 => 2.0,                     // ~52-64 leftover
        5 => 4.0,                     // ~65-77 leftover
        _ => 6.0,                     // nearly untouched bin: wasteful
    };
    score += class_penalty;

    // Modulo-10 harmonic resonance: leftover that is a multiple of 10 is reusable
    // by the common small-item sizes (10,20,...,80)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Leftover that pairs exactly with typical item sizes gets a resonance bonus
    let resonance = [10u32, 20, 25, 30, 40, 50, 60, 70, 80]
        .iter()
        .any(|&s| s == post_residual);
    if resonance {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how much would then remain
            let next_post = post_residual - next_item_size;
            score -= 5.0 - (next_post as f64) * 0.05;
            // harmonic coupling: next_post divisible by 10 is ideal
            if next_post % 10 == 0 {
                score -= 2.0;
