            let miss = next_item_size - post_residual;
            score += (miss as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; make it costly unless open bins are nearly full anyway
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64);
        score += 15.0 + waste * 0.5;
