        let tightness = mean_residual - bin_residual as f64;
        score += tightness * 0.15;
    }

    // Penalize huge open-bin sprawl slightly to encourage closing out bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

