            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // Dampen new-bin pressure when the only fits are very loose (slack > 30)
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            // MUTATION: stronger new-bin resistance mid-stream when a decent fit exists
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to ever fit a plausible item (min size 1,
    // but small gaps < ~10 are practically unusable) are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual as i32) as f64 * 25.0;
    }
    // Mid-range dead space (10..20) is mildly penalized since few items fit.
    else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / 20.0) * 8.0;
        } else {
            // Post residual can't host the next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.6;
        }
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0 + open_bins_count as f64 * 2.0;
        // If many fitting bins exist, opening a new bin is wasteful.
        score += base_penalty + fitting_bins_count as f64 * 5.0;
        // But if the item is large and residuals are small on average, allow new bin.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is above average
    // (keep tighter bins for later, avoid wasting spread space).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Slight stream progression adaptation: later in the stream, be more conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
