    // 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(60.0);
        }
    }

    // Compare post_residual to mean residual: prefer bins whose leftover
    // is small relative to average (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If the item leaves a large residual anyway, new bin is less bad.
        score -= 0.2 * post_residual as f64;
    }

    // Late in the stream: tighten packing further.
    let progress = step_index as f64 / total_items as f64;
    score += 2.0 * progress * post_residual as f64 * 0.1;

    score
}

