    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item can still fit: mild reward
        score -= (next_item_size as f64 / post_residual.max(1) as f64) * 40.0;
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize wasting large residuals
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Many open bins: prefer filling existing ones rather than opening new
    if open_bins_count > 4 {
        score -= open_bins_count as f64 * 2.0;
    }

    // Reward bins with residual below mean (consolidate small residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Early stream: be more selective about tight fits; late stream: pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * tightness;

    // Penalize leaving residuals that are awkwardly small (dead space 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
