pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate moderate residuals; late in stream, strongly penalize waste.
    let poly = (pr / cap).powi(2) * (1.0 + 3.0 * progress) + (pr / cap).powi(3) * 4.0 * progress;
    score += poly * cap;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    if pr == 0 {
        score -= 30.0 + 20.0 * progress;
    } else {
        score -= 12.0 * (-pr / 25.0).exp() * (1.0 + progress);
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - pr / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (nx - pr) / cap * 100.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are quite full or many are open.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        score = cap * (1.0 - 0.5 * progress) - 10.0 * avg_fullness * progress;
        if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning the only fitting bin
        }
        if pr == 0 {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate among many open bins.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals divisible by 10/20/25/50 (harmonic classes of capacity)
        if pr % 50 == 0 {
            score -= 18.0;
        } else if pr % 25 == 0 {
            score -= 12.0;
        } else if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            // awkward residue: penalize dead space nonlinearly
            score += (pr as f64).powi(2) / (bin_capacity as f64);
        }
    } else {
        // perfect fit
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        if pr == next_item_size {
            score -= 15.0;
        }
        // harmonic match: next item divides post residual evenly
        if next_item_size > 0 && pr % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here: leftover becomes dead space
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin if this fit is decent.
    if fitting_bins_count == 1 {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 30.0 * tightness;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins tighter than the mean residual (good packing density).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits with mild cubic shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Graded slack penalty (combined from parent + best)
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Scarcity-weighted slack reward: prefer roomy bins when few options
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-next-item capacity: residual can host next twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Overhang penalty: residual barely above next item is a poor chain
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = slack;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            // Bin can't host next item: penalize dead space strongly
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-usable residual: still salvageable for small items
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // Severely unusable residual: extra penalty graded by gap ratio
            if (pr as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress)
                    * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are valuable finishing targets
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins open and far from mean residual
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap;
            // Large next item: fresh bin may serve it better
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                // Avoid opening new bins when an open bin holds a near-exact fit
                let mut tight_open = false;
                if open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                    // Low average fill: open bins are wasting space, be lenient
                    if progress > 0.5 && open_bins_count > 4 && avg_fill < 0.18 {
                        score += 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                    if progress > 0.6 && open_bins_count > 6 {
                        score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                    }
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

