    } else if pr < 40.0 {
        score += 8.0 * (1.0 - pr / 40.0); // small gaps are risky
    } else {
        // Larger residual space is flexible; mildly reward it.
        score -= 2.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: consolidate when many bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space that even the next item cannot use
        score += 10.0;
    }

    // Mean residual coupling: if open bins are already loose, avoid
    // spreading; if they are tight, a roomy placement is more valuable.
    if pr > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Its raw post_residual is large; add a moderate opening cost so it only
    // wins when all fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
