}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (waste), reward moderate leftovers that stay usable.
    if post_residual > 0 {
        let usable = post_residual as f64 / bin_capacity as f64;
        if usable < 0.10 {
            score += 60.0 * (0.10 - usable) / 0.10;
        } else {
            score -= 10.0 * usable;
        }
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
        // Extra bonus if leftover fits next item almost exactly.
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize proportionally to wasted potential.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let congestion = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).min(20.0);
    score += 2.0 * congestion * (0.5 + progress);

    // Fullness reward: the tighter the fit relative to residual, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // New-bin candidate handling: only attractive when open bins are crowded or residual is poor.
    if bin_residual == bin_capacity {
        let good_reason = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.5 && open_bins_count > 0)
            || (next_item_size > 0 && next_item_size > mean_residual);
        if good_reason {
            score -= 90.0 * (0.3 + progress);
        } else {
            score += 150.0; // discourage scattering into new bins
        }
    }

    // Late in stream: consolidate aggressively, keep mean residual low.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 20.0 * (bin_residual as f64 - mean_residual).max(0.0) / 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear waste penalty: squared residual scaled by stream progress
    score += 0.35 * (pr / cap) * (pr / cap) * (0.5 + progress) * cap;

    // Perfect-fit reward (smooth via exponential)
    score -= 30.0 * (-(pr / 8.0)).exp();

    // Lookahead coupling: penalize residuals too small for the next item (dead space),
    // but reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 8.0 * (1.0 - progress) * ((nx - pr) / cap) * cap;
        } else {
            score -= 6.0 * (-( (pr - nx) / 10.0 )).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild preference for tighter bins relative to the fleet mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and more so when other bins could fit the item.
    if bin_residual == bin_capacity {
        score += cap * (0.9 - 0.4 * progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Slight consolidation pressure when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "usable" classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // Harmonic class: post_residual divisible by small common sizes
        // (10, 20, 25, 50) leaves re-usable chunks; reward those.
        let harmonic_bonus = if post_residual % 50 == 0 {
            12.0
        } else if post_residual % 25 == 0 {
            8.0
        } else if post_residual % 20 == 0 {
            6.0
        } else if post_residual % 10 == 0 {
            4.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead-space penalty: leftovers too small for the minimum item (1..100 range,
        // but tiny slivers under ~10 are near-useless).
        if post_residual < 10 {
            score += 25.0;
        }

        // Lookahead coupling: if the next item fits exactly into the post_residual,
        // this placement sets up a perfect follow-up.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 45.0;
            } else if next_item_size < post_residual {
                // next item fits: mild reward proportional to how well it uses the space
                let fill = next_item_size as f64 / post_residual as f64;
                score -= 10.0 * fill;
            } else {
                // next item won't fit here: penalize proportionally to wasted potential
                score += 5.0;
            }
        }
    }

    // Fraction-of-capacity class of the current fill level.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.9 {
        score -= 15.0; // nearly full bins are great to close out
    } else if fill_frac >= 0.5 {
        score -= 5.0;
    } else {
        score += 5.0; // dumping into a mostly-empty bin wastes it
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins should only win when no open bin
    // offers a decent fit. Penalize the fresh bin so it's chosen only when
    // open-bin scores are bad; scale penalty with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;
        // If next item is large and this item is small, saving empty space helps
        if next_item_size > 50 && item_size < 30 {
            score -= 15.0;
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for bins whose residual deviates from the mean in a
    // "complementary" way (this item brings the bin toward a full harmonic class).
    let new_residual = post_residual as f64;
    if (new_residual - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream),
    // and increasingly toxic as it shrinks.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny dead gap: heavy penalty
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0; // small gap: moderate penalty
        }
        // Reward tight fits superlinearly: residual near 0 after placement is ideal.
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).powi(6);
    } else {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins); with few open bins, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 8.0 * pressure;
        // But if no open bin fits, new bin is necessary: the oracle will compare anyway;
        // soften slightly when this is the only option contextually.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward using it, especially under high bin pressure.
        score -= 5.0 + 4.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead (k=2): reward leaving post_residual that can host the next item exactly,
    // penalize leaving gaps the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Gap is usable by next item; reward proximity to a perfect next fit.
            let slack = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64).powi(3);
        } else if post_residual > 0 {
            // Next item cannot use this gap: penalize proportionally to its deadness.
            score += 10.0 * (1.0 - (post_residual as f64) / nxt);
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (fewer open bins at the end), so reward filling existing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a good consolidation target; pull its score down toward preference.
    let residual_diff = bin_residual as f64 - mean_residual;
    score -= 0.05 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // Graded bonus for keeping residual exactly consumable by next two items
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            // Mid-slack penalty scaled by relative slack, discourages wasteful placement
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            // Reward near-exact two-item chains more aggressively early on
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            // Penalize residuals that are dead for the next TWO plausible sizes
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            // MUTATION: graded scarcity bonus for very tight slack when bins are scarce
            if slack <= 2.0 && fitting_bins_count <= 2 {
                score -= 3.0 * (1.0 - progress);
            }
            // MUTATION: discourage burning a bin whose residual could host next item plus half again
            if slack > 15.0 && post_residual < 2 * next_item_size && progress > 0.4 {
                score += 1.2 * slack / next.max(1.0);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // Dampen new-bin pressure when the only fits are very loose (slack > 30)
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            // Stronger new-bin resistance mid-stream when a decent fit exists
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            // MUTATION: resist new bins when the best fit is near-exact even late
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 2.0 {
                score += 25.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Graded slack penalty (from best heuristic, inverted sign)
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            let tight_bonus = (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress);
            score -= tight_bonus * fill_ratio;
            // Scarcity-weighted slack reward: fewer competing bins -> reward slack absorption
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Exact-multiple chain: residual equals k * next item size
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual can host next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            score += 8.0 * dead_rel * dead_rel * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Half-fit dead space: residual barely under half of next item
            if (pr as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - (pr / (0.6 * next_item_size as f64)));
            }
            if pr > next_item_size as f64 / 2.0 {
                score += 2.0 * (1.0 - progress);
            }
            // Full-dead weighting by next item relative size
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
        }
    }

    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Late stream: small residuals are good to burn off
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Deviation from mean residual penalty
    if mean_residual > 0.0 && post_residual > 0.0 {
        let dev = (mean_residual - pr).abs();
        score += 0.05 * dev.min(50.0) * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap && fitting_bins_count > 0 {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let mut tight_open = false;
                if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 2 {
                    let tightest = post_residual.min(bin_capacity);
                    if tightest >= next_item_size && (tightest - next_item_size) <= 3 {
                        tight_open = true;
                    }
                }
                if tight_open {
                    score += 20.0;
                } else {
                    let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                    let late = if progress > 0.75 { 28.0 } else { 0.0 };
                    score += pressure + late;
                    // Low average fill: new bins are cheap, allow more of them
                    if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                        score -= 5.0 * (0.18 - avg_fill) * 10.0;
                    }
                    if progress > 0.6 && open_bins_count > 6 {
                        score -= 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
                    }
                }
            }
        }
    }

    score += 0.06 * (bin_capacity - bin_residual) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but new-bin candidate
    // (residual == capacity) gets a neutral-ish baseline handled below.
    let is_new_bin = bin_residual == bin_capacity;

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if is_new_bin {
            // New bin: after this item, residual = capacity - item_size.
            // Reward if next item fits exactly-ish into the fresh remainder.
            let diff = (pr - nxt).abs();
            score -= 6.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
            // Mild penalty for opening new bins when plenty of open bins exist.
            score += 2.0 + 0.35 * open_bins_count as f64;
        } else {
            // Perfect chain: post_residual == next_item_size => zero waste over 2 steps.
            if (pr - nxt).abs() < 0.5 {
                score -= 25.0;
            } else if pr > nxt {
                // Next item fits: reward proportional to how snug the two-step fit is.
                let two_step_waste = pr - nxt;
                score -= 12.0 * (1.0 - two_step_waste / bin_capacity as f64);
            } else {
                // Next item won't fit here: penalize dead space relative to mean residual.
                let dead = pr;
                score += 0.5 * dead * (dead / mean_residual.max(1.0)).min(3.0);
            }
            // Extra penalty for leaving residuals that no plausible item (>=1) can use well
            if pr > 0.0 && pr < 10.0 {
                score += 8.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // ---- Last-chance bonus: if this is the only bin that fits, avoid new bin ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // ---- Mean residual anchoring: prefer bins below-average fullness when
    //      many bins are open (balance), above-average when few bins ----
    if !is_new_bin {
        let dev = post_residual as f64 - mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.15 * dev * (1.0 - progress);
    }

    // ---- Prefer filling bins that are already mostly full (classic best-fit) ----
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let coupling = prn * prn * (1.0 + 2.0 * progress) - 0.5 * prn * progress;
    score += 30.0 * coupling;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - prn;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize bins that waste space relative to mean residual
    score += 5.0 * (pr - mean_residual) / bin_capacity as f64;

    // Lookahead: penalize leaving residual that cannot fit the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let waste = (nr - pr).max(0.0) / bin_capacity as f64;
        score += 15.0 * waste * waste;
        // Reward leaving residual exactly matching next item
        let match_term = (pr - nr).abs() / bin_capacity as f64;
        score -= 8.0 * (1.0 - match_term) * (1.0 - match_term) * (1.0 - progress);
    }

    // Mild penalty when many bins are open, encouraging consolidation
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - prn) - 15.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
