pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Dead-space penalty: leftover that no typical item (>=10) can use
    if pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr < 20 {
        score += 12.0;
    } else {
        // modulo arithmetic on post_residual: leftovers near harmonic class
        // boundaries (multiples of 10/20/25) are more reusable
        let m10 = (pr % 10) as f64;
        let m25 = (pr % 25) as f64;
        score += m10 * 0.4 + (25.0 - m25).abs() * 0.15;
    }

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic tier of remaining slack after the lookahead
            if slack < 10 { score -= 25.0; }
            else if slack < 20 { score -= 15.0; }
            else { score -= 5.0 + slack * 0.1; }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr as f64) * 0.25;
        }
    }

    // Integer-division thresholds on residual class
    let cls = pr / 10; // residual decade class 0..10
    match cls {
        0 => score += 20.0,          // 0-9: dead
        1 => score += 5.0,           // 10-19: only tiny items
        2 | 3 => score -= 3.0,       // 20-39: useful mid range
        4 | 5 => score -= 6.0,       // 40-59: half-class, very reusable
        _ => {}                       // large residual: near-empty bin
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // but attractive early in stream or when many bins open and mean residual is small
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress) + (mean_residual / cap) * 10.0;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild preference for tighter bins when many fitting bins exist
    if fitting_bins_count > 2 {
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for lookahead: penalize proportional dead space.
        score += post_residual as f64 * 1.5;
    }

    // Open-bin pressure: discourage spreading across many bins mildly.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when it leaves large usable space and
    // existing fits are poor. Penalize new bins slightly by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 >= mean_residual {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Stream progression: later in stream, slightly favor consolidation.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match => strong reward; near match => graded reward
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score -= 40.0 / diff; // closer match -> bigger subtraction
        }
        // Penalize leaving residual that is too small for next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to current item (small post_residual is good)
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Compare against mean residual: bins with more slack than average are better targets
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score += 20.0 + poor_fit + 0.1 * open_bins_count as f64;
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
