pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (post_residual < next threshold) is wasted.
    if post_residual > 0 {
        // penalize residual that is too small to ever be useful again
        score += (post_residual as f64).powf(1.3) * 0.15;
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin;
    // otherwise penalize leaving a residual that blocks the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Reward using bins with relatively small residuals (consolidate fullness).
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.1 * mean_gap;

    // Prefer filling nearly-full bins more aggressively as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // With many open bins, discourage opening new bins implicitly by
    // favoring existing bins slightly more.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make the empty bin attractive only when the current
    // item is large and fits poorly elsewhere; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 14.0 * large_item;
        // late in the stream, opening new bins is more acceptable
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post residual, with smooth non-linear amplification
    let mut score = post * (1.0 + 0.8 * post / cap) + 6.0 * (post / cap).powi(2);

    // Smooth non-linear coupling with stream progress: tighten as stream advances
    score += (0.5 + 2.5 * progress) * (post / cap).powi(3) * 20.0;

    // Perfect fit reward (smooth, not hard threshold)
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness.powi(4);

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack_match = 1.0 - ((post - nx) / cap).powf(0.5);
            score -= 10.0 * slack_match;
        } else {
            score += 4.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize new bins, more so when open bins exist and fit is available
    if is_new_bin {
        let pressure = (open_bins_count as f64).powf(0.5) * 0.5;
        score += 25.0 + pressure + 15.0 * progress;
        // But allow new bin if post residual would be very reusable
        if post >= 20.0 {
            score -= 12.0 * (post / cap);
        }
    }

    // Deviation from mean residual: prefer bins with residual close to item need
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i32; // 0..=10 decile class

    // Reward small post_residual strongly (tight fit) via nonlinear shaping
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    // Modulo arithmetic: residual mod 10 classes are "awkward" if small but nonzero.
    let awkward = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + (10 - post_residual) as f64; // unusable sliver
    }
    if awkward == 1 || awkward == 9 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how well next item fills remaining space
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - fill_after / cap);
        } else {
            // next item cannot follow here: penalize proportionally to waste
            score += 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are full-ish
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 20.0;
        let big_item = item_size as f64 / cap;
        // prefer new bin for large items or when mean residual is low
        let new_bin_bonus = 25.0 * big_item + 10.0 * (1.0 - mean_residual / cap) + 8.0 * (1.0 - progress) - crowded;
        score = post_residual as f64 - new_bin_bonus;
        if next_item_size > 0 && next_item_size <= post_residual - item_size.min(post_residual) {
            score -= 5.0;
        }
    }

    // Mild exploration coupling via step parity class
    if (step_index ^ post_residual as usize) % 3 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small residuals that likely cannot host future items
    // (typical item sizes 10..80, but be conservative for unknown distributions).
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item fills leftover space
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot use this residual: penalize larger leftovers
            score += 0.10 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; make it costly early,
        // cheaper late when residuals are fragmented.
        score += 30.0 + 8.0 * bin_pressure - 20.0 * progress;
        // If mean residual across open bins is small (fragmented), new bin is more attractive.
        score -= (mean_residual / 10.0).min(15.0);
        // If next item is large and mean residual is small, prefer new bin more.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin: slight reward scaled by bin pressure to consolidate.
        score -= 2.0 * bin_pressure.min(4.0);
        // Penalize leaving residual close to but below common item sizes
        // (unusable gap zones), e.g. residual just under 10 or between 81..99 unusable-ish.
        if post_residual >= 81 {
            score += 5.0; // large residual is fine actually; mild penalty only
            score -= 10.0; // net reward for keeping a big usable bin
        }
    }

    // Mean-residual coupling: bins far below mean residual are "ragged";
    // prefer placing into bins with residual close to item size.
    let res_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * res_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // COMBINED: scale dead penalty with relative residual (borrowed from best)
        let rel = next / cap;
        score += (1.2 + 0.6 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Mild preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // NEW: graded slack penalty scaled by scarcity (from best heuristic)
            if slack > 20.0 {
                score += 0.1 * slack * scarcity;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: suppress new bins when a decent-fit bin exists mid-stream
            if next_item_size > 0 && fitting_bins_count > 1
                && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 0.15 * cap {
                score += 12.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // 2-step lookahead: strongly reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
