            // leftover can't host the next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // If next item is huge, prefer conserving space in bins that could host it
        if next_item_size >= 70 && post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Compare against mean residual: bins tighter than average are precious.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= (mean_residual - res) * 0.4; // favor tight bins
        } else {
            score += (res - mean_residual) * 0.15; // penalize loose bins slightly
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open early when few bins exist; costlier late with many open bins.
        score += open_bins_count as f64 * 2.0;
        // If the current bin would leave a big awkward gap, new bin is fine.
        if bin_residual - item_size > 40 && post_residual > 0 {
            score -= 25.0;
        }
        // If next item could perfectly fill this fresh bin after placement, encourage it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
