pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let class = pr % 10; // fine harmonic class
    let big_class = pr / 25; // coarse quarter-class

    // Penalize residuals in "dead zones" that few item sizes can fill
    // Dead space classes: residuals like 1..9 are hard to fill.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }
    // Quarter classes: residuals in (0,25) are least reusable
    if big_class == 0 && pr > 0 {
        score += 12.0;
    } else if big_class == 1 {
        score += 4.0;
    } else if big_class == 2 {
        score -= 2.0;
    }

    // Reward perfect-ish fits (post_residual divisible by small harmonics)
    if pr == 0 {
        score -= 50.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else {
        score += class as f64 * 0.4;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward if next item leaves another good residual
        let next_post = pr - next_item_size;
        if next_post % 10 == 0 || next_post == 0 {
            score -= 10.0;
        }
        if next_item_size > pr {
            score += 5.0; // next item won't fit here anyway; mild penalty for wasting
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer existing bins when mean residual is large
    if bin_residual == bin_capacity {
        // brand-new bin: baseline penalty proportional to wasted capacity elsewhere
        score += 20.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // reward tightness relative to mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 5.0;
    }

    // Coupling: many open bins -> discourage opening more
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
