    // Reward tight fits: small post_residual is good, but only if it's not dead space.
    let post = post_residual as f64;
    let tightness = 1.0 - post / cap;
    score -= 2.5 * tightness * tightness;

    // Dead-space penalty: post_residual too small to fit anything useful (items >= 1,
