    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect closure is excellent.
        score -= 15.0;
    }

    // Harmonic class: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            if rem2 < 10 {
                score += 6.0; // creates new dead space
            } else {
                score -= 5.0; // keeps bin usable
