    if next_item_size > item_size && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 30.0;
    }

    // Mild preference for fuller bins (low post residual overall).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: only attractive when it enables a clean fit for the lookahead item.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        } else {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
