pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for near-perfect two-item packing.
            if post_residual - next_item_size < 10 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Prefer filling bins that already have low residual (consolidation).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (late in stream, prefer closing out open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 60.0 * progress;
        // If no open bin fits (fitting_bins_count counts only this new bin), allow it.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Reward opening a new bin when existing bins are fragmented.
        if mean_residual > 60.0 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with residual close to item size overall.
    let abs_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * abs_gap;

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; late, chase low post_residual harder.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 2.0;
    score += 30.0 * poly;

    // Dead-space penalty: very small post residual is good (subtract), but leave room for next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 8.0 * (1.0 - ((pr - n) / cap).abs() * 4.0).max(-1.0);
        } else {
            score += 5.0 * (1.0 - (n - pr) / cap).max(0.0);
        }
    } else {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: only fitting bin -> reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many open bins already exist and mean residual is high (fragmentation).
    let frag = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += 3.0 * frag * (0.3 + 0.7 * progress);

    // Smooth interaction: item size relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // MUTATION: stronger dead-space penalty late in the stream
        if progress > 0.5 {
            score += 6.0 * dead * (progress - 0.5) * 2.0;
        }
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // MUTATION: graded preference for residuals that can host many future items
            if next > 0.0 && post_residual >= 4 * next_item_size {
                let host = (post_residual as f64 / next).min(8.0);
                score += 0.4 * host * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
