    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
        // MUTATION: stronger snap-up when very late
        if progress > 0.9 {
            score -= 3.0;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // MUTATION: harder to open new bin early when decent fits exist
            if progress < 0.4 && fitting_bins_count >= 2 && avg_fill < 0.5 {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals divisible by common item sizes (or leaving small dead space) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: post_residual too small to ever fit another item (items >= 1,
    // but penalize tiny unusable slivers strongly since they waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - pr / 10.0);
    }

    // Reward residuals in harmonic classes: divisible by 10/20/25/50 are "clean" classes.
    let mut harmony = 0.0;
    if post_residual % 10 == 0 { harmony += 6.0; }
    if post_residual % 20 == 0 { harmony += 4.0; }
    if post_residual % 25 == 0 { harmony += 3.0; }
    if post_residual % 50 == 0 { harmony += 3.0; }
    score -= harmony;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // Reward proportionally, with harmonic bonus if post_residual % next == 0
            score -= 25.0 * (nxt / pr);
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize slightly scaled by wasted fraction
            score += 10.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets baseline near capacity residual,
    // with modulation by stream progress and open bin count.
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        // Early in stream: prefer new bins slightly less; late: keep bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // Many open bins: encourage consolidation into existing bins instead.
        score += (open_bins_count as f64).min(20.0) * 1.5;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Never open a new bin when this is the last fitting bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 20.0 * (fill - 0.8);
    }

    // Mild penalty for deviating from mean residual (prefer balancing bin loads).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
