pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack); // diminishing reward with slack
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5; // penalize residuals that can't host next item
        }
    }

    // Penalize residuals below the minimum item size (dead space), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * (3.0 + 4.0 * progress);
    }

    // Compare against mean residual: avoid leaving much more than average.
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual * 1.5) * 0.8;
    }

    // Last chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Mild penalty for spreading across many open bins when item fits many bins
    // (encourage consolidation when alternatives exist).
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
    }

    // Discourage opening a new bin unless current bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
