pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) sharpening.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate slack; late, penalize residual waste more strongly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Smooth reward for tight fits relative to mean residual state.
    let mean_fit = mean_residual - pr;
    score -= 6.0 * (mean_fit / cap) * (1.0 - progress);

    // Lookahead coupling: reward bins whose post-residual still admits the next item,
    // penalize when next item cannot use the leftover space (smooth sigmoid-free form).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).max(0.0);
        let ratio = usable / cap;
        score -= 8.0 * ratio * (1.0 - ratio) * 4.0;
        // Penalize leaving residual just below next item size (dead zone).
        let dead = if pr < nxt && pr > 0.0 { (nxt - pr) / nxt } else { 0.0 };
        score += 12.0 * dead * dead * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: opening a new bin is expensive unless current
    // bins fit poorly. Penalize new bin smoothly by number of alternatives.
    if bin_residual == bin_capacity {
        let alt = fitting_bins_count as f64;
        let pressure = alt / (alt + 1.0);
        let item_frac = item_size as f64 / cap;
        // Large items early, or many fitting bins -> keep using open bins.
        score += 30.0 * pressure + 20.0 * (1.0 - item_frac) * (1.0 - progress);
        // Late in the stream, a fresh bin is less costly (amortization).
        score -= 15.0 * progress * progress;
    }

    // Mild penalty for bin proliferation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
