pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Also penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: score naturally grows with post_residual, but add
    // a nonlinear squeeze so near-full placements are extra attractive.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; penalize lightly so it doesn't override dead-space logic.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, heavily discourage
    // opening a new bin (i.e., favor this one) unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make an empty bin moderately attractive only when
    // no open bin fits well; otherwise it should lose to tight fits.
    if bin_residual == bin_capacity {
        let base = 45.0 + open_bins_count as f64 * 1.2;
        // If the next item could combine with this one in a fresh bin, soften.
        let soft = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            10.0
        } else {
            0.0
        };
        score += base - soft;
    }

    // Slight progression awareness: late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
