            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // NEW: suppress new-bin opening late when any open bin still fits the item
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
