    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" classes (small, or large enough to host typical future items).
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else {
        // dead-space penalty grows for residuals in the awkward mid-range
        // (too small for common items, too large to ignore).
        let frac = pr as f64 / cap;
        if pr < 10 {
            score -= 12.0; // near-perfect fill
        } else if pr <= 30 {
            // awkward class: 11..30 wastes capacity
            score += 18.0 * (1.0 - frac * 2.0);
        } else if pr <= 50 {
            score += 4.0;
        } else {
            // large residual: reusable, mild reward scaled by size
            score -= 6.0 * frac;
        }
        // modulo harmonic refinement: residuals divisible by common item
        // granularities (10/20/25) tile better with future items.
        if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: strongly reward bins whose post_residual can host
    // the next item (k=2 lookahead), especially exact or tight fits.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
            if pr == next_item_size { score -= 15.0; }
        } else {
            // next item won't fit here: mild penalty proportional to gap class
            let gap = (next_item_size - pr) as f64;
            score += (gap / cap).min(1.0) * 10.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // when several bins fit, prefer the tightest (post_residual already
        // encodes this), small bonus for competition
        score -= 3.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well. Penalize the empty-bin candidate normally, but
    // relax the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64 / 20.0).min(1.0);
        score += 40.0 - 15.0 * progress - 10.0 * congestion;
        // if next item is huge, a fresh bin is fine
        if next_item_size >= 70 { score -= 20.0; }
    }

    // Slight tie-break toward bins below mean residual (balancing load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps too small to ever hold the smallest item (1) are pure waste,
    // but practically unusable gaps are those below a soft threshold.
    let dead_threshold: u32 = 8;
    if post_residual > 0 && post_residual < dead_threshold {
        // Unusable sliver: heavy penalty proportional to how close to zero.
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

