    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Tightness coupling: reward small post_residual nonlinearly ---
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // --- Next-item lookahead: penalize if post_residual barely misses fitting next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin stays usable for the next item: reward.
            score -= 10.0 + (post_residual - next_item_size).min(20) as f64 * 0.5;
        } else {
            // Post placement the next item cannot fit: dead-end risk penalty,
            // scaled by how close we are to fitting it (near-miss is worst).
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + miss.min(30.0) * 0.8;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- Open bins pressure: discourage opening new bins when many are open ---
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // New-bin candidate baseline: its post_residual is large (bad),
        // add extra pressure growing with open_bins_count and mean residual slack.
        score += open_bins_count as f64 * 6.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        // Early in the stream, opening bins is cheaper (future consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 15.0;
    } else {
        // Reward reusing existing bins mildly, more so when many bins are open.
        score -= 4.0 + open_bins_count as f64 * 0.5;
    }

    // --- Residual balance: prefer bins whose residual deviates from mean
    // in a way that consolidates space (fill the emptiest usable bins first) ---
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.15;
    }

    score
}

