            if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                if slack <= 2.0 {
                    score += 25.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

