pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for the smallest possible item (1..100 range) are pure waste.
    // With unknown distribution, treat small gaps (< 10) as dead; larger small gaps partially penalized.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: perfect or near-perfect fills get a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, heavily reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty for stranding capacity.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that leave many bins open with scattered residuals
    // when mean residual is low (bins nearly full); encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.8 * (0.5 + progress);
        // Prefer bins whose residual is close to the mean (balanced packing).
        score += ((post_residual as f64 - mean_residual).abs()) * 0.15;
    } else {
        // New-bin candidate: penalize opening a new bin unless current options are terrible.
        // Scale pressure with number of open bins and stream progress.
        score += 25.0 + open_bins_count as f64 * 2.0 * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Base: tight fits preferred, nonlinear shaping
    score += pr_norm * pr_norm * 3.0;

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // Scarcity-weighted slack reward: with few alternatives, generous slack is fine
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // Tight-chain bonus scaled by fill ratio, stronger early
            let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
            score -= (1.0 - slack / cap.max(1.0)) * 6.0 * (1.0 - progress) * fill_ratio;
            // Exact-multiple chain
            if post_residual != bin_capacity && post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Two-item chain: residual fits next item twice
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // Multi-item chain window (2..=4 copies)
            if post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 4 * next_item_size {
                score -= 1.2 * (1.0 - progress);
            }
            // Over-tight window penalty when many candidates exist
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
        } else {
            // bin can't host next item: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            let dead = gap / cap;
            score += 42.0 * dead * (1.0 - progress);
            score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // Absolute residual shaping for unusable bins
            let rel = next_item_size as f64 / cap;
            score += (2.4 + 1.2 * rel) * pr;
            // Half-dead residual: partially salvageable
            if post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            if pr < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Late stream: tiny residuals are worth finishing
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Loose fit among many candidates
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            score += 2.5;
        }
        if post_residual < 2 * next_item_size {
            score += 0.8 * slack / next_item_size as f64 * 10.0;
        }
    }

    // New-bin candidate: open only when fits are poor or chain is promising
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let avg_fill = mean_residual / cap.max(1.0);
            if next_item_size as f64 > 0.55 * cap {
                score += 12.0 + 8.0 * avg_fill;
            } else {
                let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
                let late = if progress > 0.6 { 2.0 * (open_bins_count as f64 / 20.0).min(2.0) } else { 0.0 };
                score += pressure + late;
                if open_bins_count > 4 && progress > 0.5 && avg_fill < 0.18 {
                    score += 5.0 * (0.18 - avg_fill) * 10.0;
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: waste-free placements are strongly preferred.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        let tiny = (post_residual as f64).min(10.0);
        score += (10.0 - tiny) * (10.0 - tiny) * 0.8;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: the better it fits, the bigger the reward.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * fit_ratio;
        } else {
            // Next item won't fit here: mild penalty, worse if gap is small.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "nearly full" -> placing here is good; far above mean -> avoid.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (fitting_bins_count as f64).recip()
        };
        // Opening a new bin costs a fixed overhead, discounted when many
        // bins are already open (amortization) or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 250.0 - 120.0 * pressure - 60.0 * (1.0 - progress) + post_residual as f64 * 0.01;
    }

    // Slight preference to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack = post_residual as f64 - next;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual; mild penalty scaled by waste.
            score += 3.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: when many bins are open, prefer filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5 * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { 1.0 } else { 0.0 };
        score += 25.0 * poor_fit + 10.0 * (1.0 - progress);
        // If next item is small enough to pair with this item, opening a new
        // bin is attractive (fresh bin can host both).
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
        }
    }

    // Fragmentation guard: avoid leaving residuals that are awkwardly small.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
