    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score += 25.0 * diff * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() - 15.0 * progress;
    } else {
        // Favor bins below mean residual (denser bins)
        score -= 8.0 * (mean_residual - pr) / cap;
    }

    // Small non-linear reward for near-perfect fits
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // COMBINED (from best): scale dead-space penalty by item relative size
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if slack <= 3.0 && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - progress);
            }
            // COMBINED: divisibility lookahead — residuals that are exact multiples
            // of next item can host a chain of future items
            if post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 4 * next_item_size {
                score -= 1.2 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Late-stream tighter tolerance for slack — squeeze residual space hard
    if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack <= 8.0 {
            score -= 1.5 * (8.0 - slack) / 8.0;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the item: capacity-fraction bands (small / medium / large)
    let frac = item_size as f64 / cap;
    let item_class = if frac > 0.5 { 3 } else if frac > 0.34 { 2 } else { 1 };

    // Harmonic class of the post-residual: how "usable" is the leftover space
    let post_frac = post_residual as f64 / cap;
    let post_class = if post_frac > 0.5 { 3 } else if post_frac > 0.34 { 2 } else if post_frac > 0.1 { 1 } else { 0 };

    // Reward tight fits strongly
    score -= 8.0 * (1.0 - post_frac);

    // Penalize dead space: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect pairing
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            let gap_frac = gap as f64 / cap;
            // modulo-style harmonic penalty: gap in awkward band hurts
            if gap_frac > 0.1 && gap_frac < 0.34 {
                score += 6.0;
            } else {
                score += gap_frac * 10.0;
            }
        } else {
            // next item cannot fit here; leftover likely wasted
            score += 4.0 + post_frac * 12.0;
        }
        // integer-division thresholds: does post_residual split into k copies of next item?
        if post_residual > 0 && next_item_size > 0 {
            let k = post_residual / next_item_size;
            if k >= 2 && post_residual % next_item_size == 0 {
                score -= 10.0 * (k as f64).min(3.0);
            }
        }
    }

    // Item-class vs residual-class harmony: place big items into big-residual bins
    score += 5.0 * ((item_class as i32 - post_class as i32).abs() as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size <= bin_residual { 0.0 } else { 0.0 };
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        let spread = (mean_residual - post_residual as f64).abs();
        score = cap * (1.0 - 0.3 * pressure) + bad_fit + spread * 0.1
            + 10.0 * (open_bins_count as f64).sqrt() * 0.0
            + if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
    }

    // Progress-based mild tightening: later in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_frac);

    // Mean-residual anchor: pull scores toward bins near the mean residual
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (wasted capacity).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Prefer bins whose post-residual can host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins already tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight late-stream tightening bias.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if next item fits in the post residual exactly / closely
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits: penalize proportionally to wasted gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 - gap * 0.15;
        } else {
            // next item does not fit: penalize dead space that blocks the next item
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Penalize bins whose residual is far above the mean residual (poorly filled bins)
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - res_f) * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if no good fit exists elsewhere, opening a new bin is fine
        if fitting_bins_count <= 1 && post_residual == bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Late in stream: prefer tighter packing overall
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (res_f * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: quadratic reward for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward leaving space exactly usable by next item.
            score -= 2.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation (prefer using existing bins).
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Reward bins tighter than the mean residual (best-fit style).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, tighten packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild penalty so it is only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + item_size as f64 * 0.05;
        // If no open bin could fit at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let t = progress;
    let coupling = norm_pr * norm_pr * (0.5 + t) + norm_pr * (1.0 - t) * (1.0 - t);
    score += 20.0 * coupling;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (pr + item_size as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize bins with residual far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize wasting space the next item could use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (nxt / cap);
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Mild new-bin penalty when many bins are open and fit is poor.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 10.0 * waste * waste + 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity fractions are "good" states.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;

    // Reward post-residuals close to harmonic fractions (usable future fits).
    let frac_bonus = if post_residual == 0 {
        40.0 // perfect closure
    } else if (pr - half).abs() <= 2.0 {
        25.0
    } else if (pr - third).abs() <= 2.0 {
        18.0
    } else if (pr - quarter).abs() <= 2.0 {
        12.0
    } else {
        0.0
    };
    score -= frac_bonus;

    // Penalize dead space that no plausible item (min size 1, typical 10+) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit exactly or nicely into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 { score -= 8.0; }
            score -= 5.0;
        } else {
            // next item won't fit here: penalize blocking a tight residual
            if post_residual >= next_item_size.saturating_sub(5) {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, but allow it when existing residuals are large.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // high mean residual => open bins are crowded
        score += 15.0 - 25.0 * pressure;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild late-stream preference to fill existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.05;

    // Prefer bins whose residual is already below mean (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 15] are nearly unusable
    // (items are >= 1, but small gaps rarely match future small items exactly).
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64) / 16.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many alternatives: slight penalty to discourage spreading items thin.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // penalize opening new bins unless the fit is excellent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + 8.0 * pressure;
        if post_residual >= 20 {
            score -= 20.0; // a new bin still leaves usable space
        }
    } else {
        score -= 5.0; // mild bonus for reusing an open bin
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space relative to the known next item
        }
    }

    // Late in the stream, prioritize closing bins out (perfect/tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        // Dead-space penalty scaled by scarcity of fitting bins
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        // MUTATION: residual-relative dead-space term (borrowed from best heuristic)
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr;
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            // MUTATION: divisibility bonus — residuals that are clean multiples of
            // the next item size are likely to chain-fill perfectly later
            if post_residual % next_item_size == 0
                && post_residual >= 2 * next_item_size
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            // MUTATION: allow a new bin late-stream when open bins are nearly full
            // and the next item would otherwise strand a large dead residual
            if progress > 0.7
                && next_item_size > 0
                && post_residual > 0
                && post_residual < next_item_size
                && avg_fill > 0.75
            {
                score -= 18.0 * (avg_fill - 0.75);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tight = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tight * tight;

    // 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            // Perfect chain: next item fills bin completely.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here: penalize leaving medium gaps.
            let gap = nr - pr;
            score += 0.15 * gap;
        }
    }

    // Compare against mean residual: prefer bins below mean (more filled).
    score += 0.3 * (mean_residual - post_residual as f64).max(-40.0).min(40.0) * -1.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless no decent fit exists or it enables a perfect pair.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            penalty -= 25.0; // perfect two-item fill of a fresh bin
        }
        if fitting_bins_count <= 1 {
            penalty -= 20.0;
        }
        score += penalty;
    }

    // Late in stream: consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
