    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base penalty: prefer existing bins when reasonably tight
        let existing_tightness = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 30.0 + 10.0 * (open_bins_count as f64).sqrt();

        // If the best alternative is a very poor fit (huge post_residual elsewhere),
        // opening a new bin is attractive: emulate by checking mean residual.
        if existing_tightness > 0.5 {
            new_bin_score -= 20.0;
