    score -= 0.5 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins whose residual is near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

