                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // Suppress new-bin opening late when any open bin still fits the item
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 6.0;
            }
            // NEW: never open a new bin when an open bin gives a perfect or
            // near-perfect fit for the next item
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= 2.0 {
                score += 25.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residual that divides capacity nicely (e.g. 0, 20, 25, 50)
    // is reusable by common item sizes. Reward residuals in low modulo classes.
    let harmonic = (post_residual % 10) as f64;
    score -= harmonic * 0.5; // residual aligned to decade is more reusable

    // Penalize tiny dead space that nothing (min item 1..10) can use well,
    // but reward residual >= 10 so future items can fit.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Next-item lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + next_item_size as f64 * 0.3;
        } else {
            // waste: this bin becomes nearly dead after placement
            let slack = (next_item_size - post_residual) as f64;
            score += slack * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // creates large dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 8.0;
        score += 150.0 + pressure;
        if post_residual >= 20 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Fraction-of-capacity coupling: prefer filling bins past half full.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 25.0;

    // Mean-residual coupling: if this bin is below mean residual (already tight),
    // it's a good target; penalize dumping into the emptiest bin.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.6;

    // Late-stream tightening: as stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - pr) * 0.1;

    // Integer-division threshold on post_residual: residuals above half capacity
    // are wasteful targets for small items.
    if post_residual > bin_capacity / 2 && item_size < bin_capacity / 4 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range gaps (10..=25) are mildly wasteful too.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.8 * (post_residual as f64 - 9.0);
    }
    // Perfect or near-perfect fits rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            } else if gap < 10 {
                score += 3.0;
            }
        } else {
            // Next item cannot use residual: residual becomes dead space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than average (good fits relative to fleet state).
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening new bin is fine if it's the only option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual is already the base, amplify it).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: strongly reward post_residual that exactly matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 25.0; // perfect 2-chain: item + next item fill this bin
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post_residual too small for next item: dead space penalty grows
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: any placement works, prefer fullest bin.
        score -= 10.0 * tightness;
    }

    // Penalize creating dead space far below the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Cost of opening a new bin; scale with how many bins are already open.
        score = bin_capacity as f64 + 10.0 + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is small (all bins crowded),
        // opening fresh space is more attractive.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        // If next item is huge relative to mean residual, prefer fresh bin.
        if next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild preference to spread load when many bins are open and mean residual is high.
    if !is_new_bin && mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 1 {
        score += 2.0;
    }

    // Stream progression: early on, be more willing to open bins (better structure later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize leaving residuals that are too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize wasting a good bin on this item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    let pressure = mean_residual / bin_capacity as f64;
    if pressure > 0.5 && open_bins_count > 3 {
        score -= pressure * 12.0;
    }

    // Time horizon: early in stream, be picky (penalize loose fits more);
    // late in stream, just pack to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * tightness * 20.0;
    if post_residual == 0 {
        score -= 30.0 * (0.5 + progress);
    }

    // New-bin candidate: only attractive if existing bins fit poorly
    if bin_residual == bin_capacity {
        let base_new_bin_cost = 30.0 + open_bins_count as f64 * 2.0;
        // if this bin would be the only fitting option, opening is fine
        if fitting_bins_count == 0 {
            score = base_new_bin_cost - 50.0;
        } else {
            score = base_new_bin_cost + tightness * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        // MUTATION: relative dead-space penalty scaled by item size (from best heuristic)
        let rel = next / cap;
        score += (2.4 + 1.2 * rel) * pr * (1.0 - progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            // MUTATION: divisibility bonus — residuals that are clean multiples of
            // the next item size pack chains perfectly later
            if post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size && post_residual <= 4 * next_item_size {
                score -= 1.2 * (1.0 - progress);
            }
            // MUTATION: residual still large enough to host the next item AND the
            // item after (two-step lookahead), scaled by scarcity
            if post_residual >= 2 * next_item_size && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            // MUTATION: resist opening new bins when many bins are near-empty and
            // progress is late — force consolidation into partially filled bins
            if progress > 0.6 && open_bins_count > 8 && avg_fill < 0.35 {
                score += 8.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
