    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 + pr_norm);

    // Deviation of this bin's residual from mean residual
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: neutral baseline scaled with progress
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.0 + 0.3 * progress) - 2.0 * tightness;
    }

    score
}

