        score += 8.0;  // awkward sliver
    } else {
        score += 2.0;
    }

    // Fractional capacity coupling: reward tight fits nonlinearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // harmonic match: next item leaves another divisible residue
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer reusing open bins early in the stream,
    // allow opening a new bin when open bins are very fragmented.
    if bin_residual == bin_capacity {
