pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward a post-fit that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect pair (fills bin completely)
        } else if post_residual >= next_item_size {
            let rem2 = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * rem2.min(50.0); // good lookahead fit, decays with leftover
        } else {
            // next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(60.0);
        }
    }

    // Relative-to-mean coupling: bins with more residual than average are preferred targets
    // (consolidate space), bins below average are penalized (preserve tight bins).
    score -= 0.6 * ((post_residual as f64) - mean_residual);

    // Dead-space penalty: small unusable leftovers (assuming typical min item ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are small relative to the item (poor fits everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_waste = mean_residual - item_size as f64;
        // penalize new bin when decent residual exists elsewhere
        score += 25.0 + 0.4 * mean_residual - 0.5 * avg_waste.max(0.0);
        if progress < 0.15 {
            score -= 20.0; // early stream: new bins cheap
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Mild tie-break: prefer bins that keep larger residuals spread (balance load)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * (fit_ratio - 0.9);
    } else if fit_ratio > 0.7 {
        score -= 12.0 * (fit_ratio - 0.7);
    }

    // Penalize large dead space relative to typical future item sizes.
    let dead_penalty = (post_residual as f64).powf(1.6) / (bin_capacity as f64);
    score += 0.25 * dead_penalty;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // mild bonus proportional to how well next item would fill leftover
            let nl = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * nl * nl;
        } else {
            // next item won't fit here: penalize leaving awkward residual
            score += 6.0;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it
    // attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // A new bin is penalized; but less so when many open bins already exist
        // and mean residual is small (open bins are nearly full anyway).
        let mut nb = 55.0;
        nb -= 0.8 * open_bins_count as f64;
        nb += 0.5 * mean_residual;
        nb -= 20.0 * progress;
        // If item is large relative to capacity, new bin is more reasonable.
        nb -= 0.3 * item_size as f64;
        score += nb.max(-30.0);
    } else {
        // Existing bin: slight preference for bins with residual close to mean
        // (keeps bin residuals balanced, preserving flexibility).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild global pressure: when many bins are open, tighten placements.
    score -= 0.15 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
