    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }
    // penalize spreading across many open bins; mild new-bin bonus early
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 6.0 * mean_residual / cap - 10.0 * (1.0 - progress);
    }
    score
}

