        score -= 25.0; // perfect fit bonus
    } else if class >= 1 && class <= 3 {
        score += 8.0 + 2.0 * (3 - class) as f64; // dead-space penalty
    } else if class >= 4 && class <= 6 {
        score -= 3.0; // reusable mid-band
    } else {
        score -= 1.5; // large residual, still useful
    }

    // Integer-division threshold: post_residual / 10 (decile of capacity)
    let decile = pr / 10;
    score -= decile as f64 * 0.8; // prefer bins with larger remaining deciles

    // Coupling with next item: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0; // lookahead fits: strong chain bonus
            // harmonic match: next item's class complements this residual
            if (next_item_size % 10) == class {
                score -= 4.0; // exact harmonic alignment
            }
        } else {
            score += 5.0; // next item won't fit here; this bin likely closes
            // but if post_residual is small, closing is fine
            if pr <= 10 {
                score -= 6.0;
            }
        }
    } else {
        // last item: closure is free
        score -= 4.0;
    }

