    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current item is large
    // and no good residual exists (harmonic threshold: item in top third of capacity)
    if bin_residual == bin_capacity {
        if item_size > (2 * bin_capacity) / 3 {
            score -= 3.0; // big item: fresh bin is okay
        } else {
