pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Harmonic class logic: classify post_residual into capacity-fraction bands.
    // Residuals that are dead space (too small for typical items) are heavily penalized.
    let cap_f = bin_capacity as f64;
    if post_residual == 0 {
        score -= 80.0; // perfect fit, ideal
    } else {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 90.0; // tiny dead space, nearly unusable
        } else if pr < 20.0 {
            score += 40.0;
        } else if pr < 34.0 {
            score += 10.0;
        } else if pr < 50.0 {
            score -= 5.0; // half-capacity class: still useful
        } else if pr < 67.0 {
            score -= 10.0;
        } else {
            score -= 15.0; // large residual: bin stays flexible
        }
        // Integer-division harmonic: reward residuals that are near-multiples of common item classes
        let q = post_residual / 10;
        let r = post_residual % 10;
        if r >= 7 { score += 8.0 * r as f64 / 10.0; } // awkward remainder above a class boundary
        if q >= 1 && r <= 2 { score -= 6.0; } // sits just above a clean class multiple
    }

    // Lookahead coupling: if the next item fits the post_residual exactly-ish, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap_f);
        } else {
            // next item won't fit here; penalize proportionally to how close we came
            let over = (next_item_size - post_residual) as f64;
            score += 15.0 * over / cap_f;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

