    // fits poorly everywhere (this call has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; add pressure proportional to how many bins are open
        // (prefer consolidating into existing bins when reasonably possible).
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if many bins are open with high mean residual, a new bin is fine to spread load
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 30.0;
