    // using them closes bins and reduces open-bin count).
    score -= 10.0 * (mean_residual - bin_residual as f64).max(0.0) / cap_f;

    // Stream progression: early in the stream, be more conservative about creating
    // tight (dead-space) fits since future distribution is unknown; late, exploit tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && progress < 0.3 {
        score += 25.0;
    }

    score
}

