        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Mid-size dead space (11..=20) is partially risky; mild penalty.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits: the smaller post_residual relative to item, the better.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // large residuals when bin count is already high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit post_residual and post_residual is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 25 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): post_residual == capacity - item_size is
    // naturally large; add a small extra penalty so it only wins when all
    // open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 5.0;
        // But if no open bin really fits well, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Slight stream-position adaptation: late in the stream, tighten up
    // (avoid leaving many half-empty bins behind).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item (strengthened)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 16.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 5.0 * (1.0 - progress);
        }
        // NEW: proportional dead-space penalty scaled by item size
        score += 0.55 * (next_item_size - post_residual) as f64 * (1.0 - 0.5 * progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            // Mild preference for residuals that can host a third item
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            // Two-item chain lookahead
            if slack <= 3.0 && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - progress);
            }
            // NEW: quadratic slack penalty — waste grows superlinearly
            if slack > 20.0 {
                score += 0.012 * (slack - 20.0) * (slack - 20.0) * 0.1;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Late-stream tighter tolerance for slack — squeeze residual space hard
    if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack <= 8.0 {
            score -= 1.5 * (8.0 - slack) / 8.0;
        }
    }
    // NEW: extended squeeze window
    if progress > 0.9 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 8.0 && slack <= 25.0 {
            score -= 0.6;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // Suppress new-bin opening late when any open bin still fits the item
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 8.0;
            }
            // NEW: suppress new bin when an open bin can host item AND next item
            if next_item_size > 0 && fitting_bins_count > 0
                && post_residual >= next_item_size + item_size as u32 {
                score += 10.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead matching.
    // Reward bins whose post_residual matches the next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        // Perfect chain: next item fits exactly into the leftover space.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack_after_chain = post_residual - next_item_size;
            // Prefer chains that leave small-but-usable leftovers.
            score -= 40.0 * (1.0 - (slack_after_chain as f64) / bin_capacity as f64);
            // Bonus if chain leaves another exact-match residual (50/50 style splits).
            if slack_after_chain <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item cannot chain into this bin: penalize proportionally to mismatch.
            let miss = nxt - post;
            score += 15.0 + 25.0 * (miss / 100.0);
        }
        // Extra penalty if post_residual is a dead space that nothing (10..80) can use.
        if post_residual > 0 && post_residual < 10 {
            score += 45.0;
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 0.0;
    }

    // Tightness reward relative to capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean wastes the "rich" bins; prefer bins near/above mean residual.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 12.0 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or current bins are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Baseline cost of a fresh bin.
        let mut new_bin_score = 55.0 + 40.0 * (1.0 - item_frac);
        // Late in the stream, opening new bins is less wasteful (fewer future
        // items to strand residual space), so discount slightly.
        new_bin_score -= 15.0 * progress;
        // If many bins fit the item, opening a new bin is clearly worse.
        if fitting_bins_count > 2 {
            new_bin_score += 30.0;
        }
        // If the only alternative leaves large dead space, new bin becomes viable:
        // emulate by comparing against the tightest possible open-bin outcome.
        let best_open_post = post_residual; // for open bins this is residual - item
        if bin_residual != bin_capacity || best_open_post > 0 {
            // open-bin path exists; penalize new bin if any open bin gives small post_residual
            if best_open_post <= 15 && bin_residual != bin_capacity {
                new_bin_score += 50.0;
            }
        }
        // Many open bins already: discourage spreading.
        new_bin_score += 3.0 * open_bins_count as f64;
        score = new_bin_score;
    }

    // Mild regularization to keep scores comparable across bins.
    score += 0.001 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual already encodes this).

    // Penalize bins that will be nearly empty after placement only mildly;
    // reward leaving residual that matches the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual.max(0)) as f64;
        score += 4.0 * (gap / 100.0).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to keep tightest-fit dominance.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation pressure); prefer spreading when few open.
    let open_pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score -= open_pressure * (item_size as f64 / bin_capacity as f64) * 6.0;

    // Mean residual alignment: bins whose residual is close to mean are
    // "typical"; reward placing into below-mean-residual bins (denser bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Time horizon: early in stream, keep bins flexible (penalize tiny residuals);
    // late in stream, squeeze everything (reward tight fits harder).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (1.0 - t); // early dead space is costly
        score -= 5.0 * t;          // late: perfect fill is great
    }

    // New-bin candidate: reserve it for items that fit nowhere well.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { 0 } else { 0 };
        let _ = best_possible;
        // Cost of a fresh bin grows with how many bins already open.
        score += 18.0 + 2.0 * open_bins_count as f64;
        // But if this bin would be the only fit and the item is large, allow it.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late stream: opening new bins is cheap since stream ends soon.
        score -= 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: dead space penalized super-linearly, worsened by progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = 2.0 * x * x + 0.5 * x;

    // Stream progress amplifies waste penalty (late in stream, tightness matters more).
    score += progress * 1.5 * x * x;

    // Coupling with mean residual: prefer bins that deviate (tighter) from the average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev;

    // Lookahead: reward leaving space exactly usable by next item (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs() / cap;
        score -= 1.2 * (1.0 - fit_gap) * (pr / n.max(1.0)).min(1.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score = 3.5 + 2.0 * progress + 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

