    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to tightness of the pair
            score -= 30.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += 10.0 * ((next_item_size - pr) as f64 / bin_capacity as f64);
