        if bin_residual >= pair && pair > item_size {
            // could have held both: reward taking first slot here
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so we only open
    // when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if item is large relative to capacity and mean residual is small,
        // opening fresh is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 || mean_residual < item_size as f64 * 0.5 {
            score -= 65.0;
        }
        // Early stream: opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 25.0;
        }
    }

    // Prefer filling fuller bins: reward small post_residual generally.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residual far from mean residual (fragmentation).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Many open bins: discourage spreading; prefer tight packing into existing.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

