pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual below the minimum item size (1) is impossible, but small
    // residuals (< 15) are hard to fill; penalize super-linearly.
    let dead = if post_residual < 15 {
        (15 - post_residual) as f64
    } else {
        0.0
    };
    score += 3.0 * dead * dead / 15.0;

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit of residual with next item: strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strong penalty for opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        // Late in stream, prefer reusing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Penalize bins whose residual deviates badly from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        if next_item_size - post_residual <= 6 {
            score += 5.0 * (1.0 - progress);
        }
        // MUTATION: dead residual that is also small in absolute terms is
        // nearly wasted capacity — penalize proportionally to its size
        score += 0.25 * pr * (1.0 - progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // MUTATION: reward leaving a residual exactly equal to the next
            // two items combined (perfect chain) regardless of progress
            if post_residual == 2 * next_item_size {
                score -= 6.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            // MUTATION: tighter escape hatch — allow a new bin only when the
            // best existing fit would leave a residual dead for the next item
            // AND that dead space is large relative to the item
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                if post_residual < next_item_size / 2 {
                    score -= 24.0;
                } else {
                    score -= 10.0;
                }
            }
            // MUTATION: resist new bins when an existing fit leaves a residual
            // that exactly chains with the next item
            if next_item_size > 0 && post_residual == next_item_size {
                score += 60.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // strongly reward this bin (perfect 2-item packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after = post_residual - next_item_size;
        score -= 18.0;
        score -= 0.25 * (next_item_size as f64);
        // Extra reward if after both items the residual is nearly zero.
        if slack_after <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use (dead space risk).
        let gap = (next_item_size as f64) - (post_residual as f64);
        score += 0.15 * gap.min(60.0);
    }

    // Compare post residual relative to mean residual across open bins.
    // Filling a bin below-average residual (denser than average) is good.
    score += 0.10 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably well,
    // unless the item is huge (would leave a very small residual anyway).
    if bin_residual == bin_capacity {
        let new_bin_bonus = if item_size >= 70 {
            // Large item: near-full packing of a fresh bin is fine.
            -8.0
        } else {
            // Small/medium item in a fresh bin wastes capacity; discourage.
            15.0 + 0.3 * (item_size as f64)
        };
        // If many open bins exist, opening new bins is more costly.
        score += new_bin_bonus + 0.05 * (open_bins_count as f64);
    }

    // Slight preference early in the stream to consolidate (fewer bins early compounds).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post_residual could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize creating dead space the next item cannot use.
            score += 2.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Penalize spreading across many open bins when residuals are large;
    // encourage consolidation toward mean residual.
    if bin_residual as f64 > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to residuals) or many bins are already open.
    if bin_residual == bin_capacity {
        let spread = (mean_residual / bin_capacity as f64).min(1.0);
        score += 5.0 - 4.0 * spread - 0.05 * open_bins_count as f64;
        if item_size > 70 {
            score -= 3.0; // big items: fresh bin is fine
        }
    }

    // Mild time pressure: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 1.5 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Normalized post-residual and its smooth non-linear shaping.
    let x = pr / cap;
    // Dead-space penalty: strongly penalize residuals that are hard to fill later
    // (mid-range residuals are the worst; very small ones are fine).
    let dead = 3.0 * x * (1.0 - x) * (1.0 - x); // peaks around x ~ 1/3
    let tight_fit_reward = -2.5 * (1.0 - x) * (1.0 - x); // reward near-full fits

    // Lookahead coupling: penalize if next item won't fit in the resulting residual.
    let nx = next_item_size as f64;
    let lookahead = if nx > 0.0 {
        if pr < nx {
            2.0 * (nx - pr) / cap * (1.0 + progress)
        } else {
            -1.0 * (1.0 - (pr - nx) / cap) * 0.5 // small reward if next item fits snugly
        }
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    let last_chance = if fitting_bins_count == 1 && !is_new_bin { -5.0 } else { 0.0 };

    // Stream-progress coupling: later in the stream, prefer tighter packing
    // (waste less), encouraging consolidation of open bins.
    let progress_coupling = -1.5 * progress * (1.0 - x);

    // Mean-residual deviation: prefer bins whose residual is close to the mean
    // (keeps open bins balanced) unless it is a near-perfect fit.
    let dev = (pr as f64 - mean_residual).abs() / cap;
    let balance = 0.8 * dev * (1.0 - (1.0 - x));

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits (fitting_bins_count counts open bins only) or when the
    // item is large and the resulting residual is small.
    let new_bin_penalty = if is_new_bin {
        let open_pressure = open_bins_count as f64 * 0.3;
        let large_item = (item_size as f64 / cap) * 2.0;
        6.0 + open_pressure - large_item - 3.0 * progress
    } else {
        0.0
    };

    let mut score = pr + dead + tight_fit_reward + lookahead + last_chance
        + progress_coupling + balance + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: base preference proportional to its emptiness.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin costs ~one full bin; only attractive when current
        // fit is poor (large post_residual) or item is small relative to capacity.
        score = 55.0
            + 0.45 * (item_size as f64)
            - 0.10 * (open_bins_count as f64)
            - 0.25 * (post_residual as f64);
        // If the next item would fit nicely in the fresh bin, slightly favor it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 0.15 * (next_item_size as f64);
        }
        // Early in the stream, new bins are cheap (few open bins to manage).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        return score;
    }

    // Harmonic-class logic on post_residual: classify leftover space into
    // capacity-fraction classes (dead space = residual below smallest useful size).
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that fall into "dead zones": < 10 (nothing fits).
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 40 && post_residual < 50 {
        score -= 4.0; // half-bin class: very reusable
    } else if post_residual >= 25 {
        score -= 2.0;
    }

    // Perfect fit bonus (exact fill).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual,
    // scaled by how snugly it fits (harmonic closeness).
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 + 12.0 * snug;
    } else if next_item_size > post_residual {
        // Next item won't fit here: mildly penalize leaving awkward gaps.
        score += 3.0 * frac;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is far above
    // the mean helps equalize residuals (keeps many medium gaps usable).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.05 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // Integer-division threshold: bins whose post_residual stays in a
    // reusable class (>= capacity/4) get a mild discount.
    if post_residual >= bin_capacity / 4 {
        score -= 3.0;
    }

    // Modulo-class exploration: residuals near multiples of 10 are
    // statistically easier to combine with typical item sizes.
    let m = post_residual % 10;
    if m <= 2 {
        score -= 2.0;
    } else if m >= 8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // treat gaps below the minimum possible item size as pure waste
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap);
        } else {
            // penalize gaps that no plausible next item can use well
            let usable = if (next_item_size > 0 && gap >= next_item_size as f64) || gap >= 10.0 { 1.0 } else { 0.0 };
            if usable < 1.0 {
                score += 40.0;
            }
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover; slight penalty
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading items across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins deviating from mean toward tighter fill.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.9 * open_bins_count as f64 - 0.5 * mean_residual;
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in wasted space).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.3 * chain_waste;
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize leaving a sliver that blocks nothing.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Compare against mean residual: prefer bins with less residual (denser bins).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 15.0;
        }
    }

    // Late in stream: prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);
    score *= 1.0 + 0.8 * progress * pr_norm;

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        score += 14.0 * (1.0 - pr_norm) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        if next_item_size - post_residual <= 6 {
            score += 5.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            // COMBINED: graded slack terms from best heuristic (scaled additions)
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual < 2 * next_item_size {
                let over = slack;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // COMBINED: penalize slack relative to mean residual (dead-space diagnosis)
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                score -= 18.0;
            }
            // MUTATION: escape hatch — allow new bin when the best existing fit
            // wastes more than half the next item's size in dead space
            if next_item_size > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                if slack > 0.5 * next {
                    score -= 8.0 + 6.0 * (slack / next).min(2.0);
                }
            }
        }
    }

    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead space analysis: if the leftover cannot fit the next item anyway,
    // the waste is "free" — reward using this bin now.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // leftover unusable by lookahead: soften penalty proportionally
            let usable_waste = post_residual as f64 / next_item_size.max(1) as f64;
            score -= 15.0 * (1.0 - usable_waste);
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // leftover is a near-perfect slot for the next item: big reward
            score -= 20.0;
        }
    } else {
        // last item: any bin that fits is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive early,
    // cheaper later in the stream when fragmentation dominates.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // penalize new bins more when item is small (wastes capacity)
        let mut new_bin_penalty = 35.0 * (1.0 - item_frac) + 10.0;
        // as stream progresses and open bins fragment, allow new bins more readily
        new_bin_penalty -= 20.0 * progress;
        // if existing bins are heavily fragmented, new bin is more attractive
        new_bin_penalty -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
        // if very few bins fit the item, opening new may be wise
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Prefer filling bins that are already mostly full (consolidate fragments).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fullness;

    // Mild penalty for spreading across many open bins when residuals are large.
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    // Late-stream: squeeze every bin harder, avoid leftovers.
    if progress > 0.8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual), softly normalized.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, waste matters less (bins are cheap to start);
    // later, tight packing dominates via a sharpened quadratic term.
    let tightness = pr / cap;
    let sharpen = 1.0 + 4.0 * progress * progress;
    score += sharpen * tightness * tightness;

    // Reward filling a bin almost exactly, with a progress-amplified cubic bonus.
    let near_full = (cap - pr) / cap;
    score -= progress * near_full * near_full * near_full * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 + progress;
    }

    // New-bin candidate: penalize slightly so we only open when fits are bad,
    // but relax this penalty as the stream progresses and mean residual shrinks.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.6 * progress - 0.2 * (mean_residual / cap);
    }

    // Lookahead coupling: if the next item fits the resulting residual exactly,
    // reward this placement; if the residual is just barely too small, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 0.4 * (1.0 - slack / cap);
        } else {
            score += 0.3 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual), penalize dead space quadratically.
    score += (post_residual as f64).powi(2) / cap;

    // Harmonic class of post_residual: mod-10 buckets. Residuals in [1,10] are
    // nearly dead space (few items that small); penalize strongly.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        if pr < 10 {
            score += 60.0; // unusable sliver
        } else if cls == 0 {
            score -= 15.0; // perfectly divisible residual, easy to refill
        } else if cls <= 5 {
            score += 12.0; // awkward remainder class
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): neutral baseline; discourage early opening,
    // allow it when residuals across open bins are large and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        score = cap * 0.55 + open_bins_count as f64 * 2.0 - fragmentation * 30.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 20.0; // no open bin likely fits the next item either
        }
    }

    // Mild preference to fill bins with larger mean residual (consolidate waste).
    score -= mean_residual * 0.05;

    // Fractional capacity threshold: residual above half-capacity is valuable, keep it.
    if post_residual > bin_capacity / 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
