    // Pressure from number of open bins: with many open bins, favor consolidation.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins with residuals below the mean (consolidate fuller bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    score
}

