    // Dead-space penalty: post_residual too small to ever fit min-size item
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    // Lookahead coupling: penalize if post_residual cannot fit next item but bin_residual could
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size {
            score += 20.0;
        }
        // Harmonic class: post_residual divisible-friendly with next item size
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin bonus: only fitting bin left
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        score = 70.0 + 0.5 * open_bins_count as f64 - 0.3 * (step_index as f64 / (total_items.max(1) as f64));
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0; // next item won't fit alongside in fresh bin
        }
        if poor_fit > 0.0 { score += 0.0; }
        // discourage opening when mean residual large (existing bins have room)
        score += 0.4 * mean_residual;
    }

    // Prefer filling bins with larger residual (reduce bin count) mildly
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize gaps that cannot fit the lookahead item either (double-wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Perfect closure bonus: bin fully used.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.05;
    }

    // Lookahead synergy: reward leaving exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

