pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match within a small tolerance.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff <= 3 {
            score -= 200.0 - (diff as f64) * 40.0;
        }
        // Penalize post_residual that is too small for the next item but still
        // large enough to be "wasted" dead space (unusable for typical items).
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 50.0;
        }
    }

    // Reward tight fits relative to the mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 1.5;
    } else {
        score += (post_f - mean_residual) * 0.75;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good fit (post_residual would be a poor match for the next item).
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a perfect fit.
        score = 60.0 + post_f;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: opening a bin is required
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0; // fresh bin gives perfect lookahead fit
        }
    }

    // Prefer keeping the number of open bins moderate: early in the stream
    // allow more bins to spread load; late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful again
    // (dead space below the minimum plausible future item size).
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further slack: mild reward scaled by fit quality
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 - 0.15 * slack_after_next as f64;
        } else {
            // next item cannot use this bin's leftover: penalize proportional to gap
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit in existing bins is poor. Penalize the fresh bin, more so when many
    // bins are already open or mean residual is large (existing capacity pool).
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
    } else {
        // Prefer bins whose residual is close to the item (best-fit style),
        // reward bins that are "more full" than average.
        let fullness_gap = mean_residual - bin_residual as f64;
        score -= 0.4 * fullness_gap;
    }

    // Time horizon: early in the stream, be more conservative (keep bins
    // flexible); late in the stream, exploit tight fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open and this placement would leave a
    // large awkward residual (fragmentation control).
    if post_residual > 40 && post_residual < 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
        let usable = pr / cap;
        score += 14.0 * (1.0 - usable) * (1.0 - progress);
        if post_residual < next_item_size / 2 {
            score += 4.0 * (1.0 - progress);
        }
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 6.0 * dead * 100.0 * scarcity * (1.0 - progress);
        if next_item_size - post_residual <= 6 {
            score += 5.0 * (1.0 - progress);
        }
        // MUTATION: relative dead-space penalty scaled by item size share
        let rel_dead = (next_item_size - post_residual) as f64 / next.max(1.0);
        score += 3.0 * rel_dead * (1.0 - progress);
    }

    // Lookahead: exact fit jackpot; graded slack with scarcity weighting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // MUTATION: penalize slack relative to mean residual more broadly
            // (target the dead-space ratio weakness)
            if slack > 10.0 && pr > mean_residual * 1.2 {
                score += 0.05 * (pr - mean_residual) * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                score -= 18.0;
            }
            // MUTATION: extra new-bin resistance when a fit exists that leaves
            // a residual reusable by the next item (keep chains alive)
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 12.0 {
                score += 8.0 * (1.0 - progress);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (tight fits preferred).
    let mut score = pr * (1.0 + norm_pr * (1.5 + 2.5 * progress));

    // Reward when the next item exactly or nearly fills the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / cap).powi(3);
    } else if next_item_size > 0 {
        // Penalize if next item cannot use this leftover.
        score += 8.0 * norm_pr;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize creating residual far below the mean (fragmenting).
    if bin_residual < bin_capacity {
        let dev = (pr - mean_residual) / cap;
        score += 10.0 * dev * dev.abs();
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += 2.0 * (open_bins_count as f64).ln() * progress;

    // New-bin candidate: neutral baseline, slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score = cap * (1.2 + 0.8 * progress) - 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity/10 buckets
    let class = post_residual / (bin_capacity / 10);
    score -= class as f64 * 3.0;

    // Perfect fit reward (modulo arithmetic on capacity)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: penalize proportionally to wasted fraction
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_capacity != bin_residual {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else {
            // opening a new bin wastes (bin_residual - item_size) of an existing bin
            score += 25.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
            if fitting_bins_count == 1 {
                score += 50.0; // keep last-chance bins alive
            }
        }
    }

    // Progress-aware mild preference for tighter bins later in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64) * 0.1 * progress;

    // Prefer bins with residual below mean (denser bins)
    score -= (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

