            if slack > 10.0 && pr > mean_residual * 1.2 {
                score += 0.05 * (pr - mean_residual) * (0.5 + 0.5 * (1.0 - progress));
            }
            // MUTATION: two-item chain lookahead — residual that fits next item
            // twice exactly is nearly perfect
            if post_residual == 2 * next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                score -= 18.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 12.0 {
                score += 8.0 * (1.0 - progress);
            }
            // MUTATION: stronger new-bin resistance when many bins already fit
            // the item with modest slack (avoid bin proliferation)
            if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                if slack <= 20.0 {
                    score += 10.0 + 2.0 * (fitting_bins_count as f64).min(5.0);
                }
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // future item are pure waste -> heavy penalty.
    if post_residual > 0 {
        // smallest plausible item is 1; treat gaps < ~10 as dead space
        if post_residual < 10 {
            score += 50.0 * (10.0 - post_residual as f64);
        } else {
            // smooth penalty growing as residual shrinks toward dead zone
            score += 8.0 * (10.0 / post_residual as f64);
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into the gap,
    // penalize if the gap is just barely too small for the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            score -= 15.0; // next item can still use the gap
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 25.0; // gap just misses next item -> likely dead space
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 20.0;
        }
    } else {
        // Mild reward for filling fuller bins (tighter packing).
        score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;
