    // Base: non-linear penalty on post-residual (dead space), cubic coupling
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: dead space hurts more later
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prog_poly * norm_pr * cap.sqrt();

    // Reward tight fits: subtract bonus when post_residual is small relative to item
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (item_size as f64 / cap);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0) * (nx / cap);
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + prog_poly);
    }

    // New-bin candidate: penalize mildly early, more when many open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() + 10.0 * prog_poly;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (1.0 + prog_poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals in [0,10) are near-perfect; residuals divisible into common
    // item-size classes (10/20/25/50) are more reusable than odd leftovers.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // modularity bonus: residual matching common size classes
        let class_bonus = if pr % 10 == 0 {
            12.0
        } else if pr % 25 == 0 {
            8.0
        } else if pr % 20 == 0 {
            6.0
        } else {
            0.0
        };
        score -= class_bonus;
        // dead-space penalty grows super-linearly for large awkward residuals
        if pr > 50 {
            score += (pr as f64 - 50.0) * 0.8;
        }
    }

    // Tightness: reward filling a large fraction of the bin
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
            // extra reward if next item leaves a harmonic residual too
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins with residuals below the mean (consolidate waste),
    // penalize dumping into bins with lots of room unless fill is tight.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: only attractive when nothing fits well.
    // Base penalty so open bins are preferred unless their fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0
            - 20.0 * progress
            - 0.3 * open_bins_count as f64;
        // opening a new bin is fine if the item is large (would waste open bins)
        if item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

