pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 3.0 * open_bins_count as f64 * (1.0 - fit_ratio.min(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a dead gap
    // that cannot host the lookahead item, or no bin fits well.
    if bin_residual == bin_capacity {
        let dead_for_next = next_item_size > 0 && post_residual < next_item_size;
        if post_residual < 10 || dead_for_next {
            score -= 20.0;
        } else {
            score += 35.0; // prefer reusing open bins for normal fits
        }
    }

    // Lookahead synergy: reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 10.0; // awkward gap just above next item
    }

    // Early in stream, be slightly more willing to open bins (build structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item still fits in the leftover space: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins tighter than the mean residual (good fits), avoid loose bins.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are bad,
    // but relax as stream progresses (early on, keeping bins compact matters).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress;
