pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 6.0 * tight * tight;

    // Penalize dead space that no plausible future item can fill.
    // Items are 1..100; residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residual below the mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    // Time horizon: late in the stream, avoid opening new bins (consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, adjusted by state.
        let mut new_bin_score = 45.0;
        // Early stream: opening bins is cheap to keep options open.
        new_bin_score -= 20.0 * (1.0 - progress);
        // If many bins are open with large mean residual, prefer reusing them.
        new_bin_score += 0.15 * open_bins_count as f64 * (mean_residual / cap);
        // If no bin fits (fitting_bins_count counts open bins; new bin always "fits"),
        // this call competes normally; lookahead can justify a fresh bin.
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: slight bonus for reusing when many bins are open.
        score -= 0.1 * open_bins_count as f64;
        // Late stream: extra reward for keeping residual low.
        score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let next = next_item_size as f64;

    // Base: prefer tight fits with smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 42.0 * dead * (1.0 - progress);
        score += 8.0 * dead * dead * 100.0 * (1.0 - progress);
