            if post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size / 2 {
                score += 3.0 * (next_item_size as f64 - pr) / next.max(1.0);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // Penalize slack relative to mean residual
            if slack > 10.0 && pr > mean_residual * 1.2 {
                score += 0.05 * (pr - mean_residual) * (0.5 + 0.5 * (1.0 - progress));
            }
            // MUTATION: chain-continuation bonus — slack small enough that the
