            if slack > 0.0 && slack < 8.0 && post_residual < next_item_size * 2 {
                score -= 2.0 * (8.0 - slack) * 0.25 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
