    // Smooth stream-progress coupling: early on tolerate waste, later tighten
    let tight = 1.0 + 2.0 * progress * progress;
    score *= tight;

    // Penalize post-residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * pr;
    } else if next_item_size > 0 {
        score -= 3.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins below mean residual slightly (fill emptier bins first)
    score -= 0.05 * (mean_residual - pr);

    // New-bin candidate: mild penalty so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual in (0, 10] -> dead space; strong penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Class 2: perfect or near-perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Class 3: residual divisible by common item sizes (harmonic bins).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 30.0;
            } else {
                score -= 10.0 * (1.0 - leftover as f64 / cap);
            }
        } else {
            // Next item cannot use this residual: penalize wasting a large bin.
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when no tight fit is available.
    if bin_residual == bin_capacity {
        // Base new-bin score; opening fresh bins early is cheap, later is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 60.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // If many bins are open, discourage spreading.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild tie-break: prefer bins whose residual is below mean (compact fill).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.13;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals too small for typical items
    // (smallest item is 1, but small gaps < ~15 are nearly unusable) are
    // penalized super-linearly.
    if post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 3.0;
    }

    // Reward bins whose residual is "wasted" anyway if the gap can still
    // host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 {
        // Gap cannot fit the next item: mild penalty pushing toward bins
        // that stay useful, but only if this bin is not a last resort.
        score += 5.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening new bins is cheaper so prefer tight fits only.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New empty bin candidate: only attractive when no open bin fits well
    // (handled implicitly) — make it moderately expensive.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // But if item is large relative to capacity and mean residual is low,
        // opening fresh may be wise.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 400.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // Next item fits here afterwards: reward proportional to tightness.
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in residual: mild penalty scaled by gap.
            score += 0.3 * diff;
        }
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 50.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 30.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= bin_capacity {
            0.0
        } else {
            0.0
        };
        score = score * 0.5 + bin_capacity as f64 * 0.6 + lookahead_bonus;
        // Penalize opening new bins when several bins already fit the item.
        if fitting_bins_count > 1 {
            score += 80.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Mild penalty late in stream to consolidate.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 60.0 * progress;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;

    // Base: raw post-residual (smaller = better) as primary signal
    let mut score = pr;

    // Smooth shaping of the base
    let pr_norm = pr / cap;
    score += 0.5 * pr_norm * pr_norm * cap;

    // Stream-progress coupling: keep large residuals slightly more valuable early
    score += 0.8 * progress * pr * pr_norm;

    // Lookahead: exact fit jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            // graded slack: near-fits heavily rewarded, large slack mildly penalized
            if slack <= 4.0 {
                score += 3.6 * slack;
            } else if slack <= 20.0 {
                score += 1.1 * slack;
            } else {
                score += 0.25 * slack;
            }
            // scarcity: when few bins fit, reward leaving room for next item
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
            if fitting_bins_count > 3 && slack > 10.0 {
                score += 2.5;
            }
            // tight chain bonus: residual that fits next item almost exactly
            if fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next.max(1.0) * 10.0;
            }
            if post_residual >= 3 * next_item_size {
                score += 1.5;
            }
            if post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack > 8.0 && slack <= 30.0 {
                score += 0.12 * slack * (1.0 - 0.5 * progress);
            }
            if progress < 0.5 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 3 {
                score -= 4.0 * (1.0 - progress);
            }
            if slack > 15.0 && pr > mean_residual * 1.4 {
                score += 0.08 * (pr - mean_residual) * (1.0 - progress);
            }
            if post_residual > next_item_size
                && post_residual % next_item_size == 0
                && post_residual <= 4 * next_item_size
            {
                score -= 1.2 * (1.0 - progress);
            }
            // dead-space ratio penalty: slack far above mean residual wastes space
            if slack > 10.0 && pr > mean_residual * 1.2 {
                score += 0.05 * (pr - mean_residual) * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            // next item cannot fit here: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
            // relative dead-space penalty scaled by item share
            let rel_dead = gap / next.max(1.0);
            score += 3.0 * rel_dead * (1.0 - progress);
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap;
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 {
                let min_slack_ok = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 30.0;
                if !min_slack_ok {
                    score -= 12.0;
                }
            }
            if progress > 0.35 && progress < 0.75 && fitting_bins_count > 1 {
                score += 6.0;
            }
            if progress > 0.75 && avg_fill > 0.55 {
                score += 10.0 * (avg_fill - 0.55);
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                score -= 18.0;
            }
            // keep chains alive: a fit leaving reusable residual resists new bin
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 12.0 {
                score += 8.0 * (1.0 - progress);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: strongly favor placements leaving little dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate penalty: only open a new bin when no open bin fits well
    // (post_residual too large relative to capacity) or nothing fits at all.
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If existing bins fit tightly, discourage opening a new one.
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            let _ = best_possible;
            score += 20.0 * (1.0 - progress);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 18.0 * (1.0 - progress);
        // If many bins are open, prefer reusing them.
        score += 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item could use the residual left here,
    // reward this placement; if the leftover residual is awkward for the next
    // item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits into the leftover: good chaining.
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Leftover is unusable by next item: dead space risk.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
            // Extra penalty if next item also barely misses (fragmentation risk).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 6.0;
            }
        }
    }

    // Global residual balance: prefer bins whose residual is close to the mean
    // (keeps open bins homogeneous and easier to fill later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, prioritize closing bins tightly (fewer wasted gaps).
    if progress > 0.8 {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild preference for filling more-emptied bins first (keep fuller bins for
    // small future items).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // scarcity-aware slack reward: when few bins can host next item,
            // preserving a tight chain matters more
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // chain-of-two bonus, strengthened when next item is scarce
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // scarcity-aware slack discount (borrowed from best heuristic)
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 40.0 * dead_rel * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // sub-half residuals are near-dead: extra penalty
            if post_residual > 0 && (post_residual as f64) < 0.5 * next_item_size as f64 {
                let rel = next_item_size as f64 / cap;
                score += (2.4 + 1.2 * rel) * pr;
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress)
             + 2.0 * norm_pr * progress * (1.0 - progress)
             + 3.0 * norm_pr * norm_pr * norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Lookahead: penalize residuals that can't hold next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (1.0 - ((pr - ns) / cap));
        } else {
            score += 12.0 + (ns - pr);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize fragmenting large residual into tiny dead space
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr);
    }

    // Mean residual coupling: prefer bins near mean residual
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately attractive early, less so late
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (4.0 * cap);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: post_residual buckets by integer division thresholds.
    // Residuals <= 10 are dead space (no item can be that small... but sizes 1..100 allowed).
    let dead_threshold: u32 = 9;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0; // unusable sliver
    } else if post_residual <= 25 {
        score -= 10.0; // still useful for small items
    } else if post_residual <= 50 {
        score -= 20.0;
    }

    // Modulo classes of post_residual vs next_item_size: reward exact harmonic pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here afterwards: strong reward.
        score -= 30.0;
        // Exact division harmony: post_residual % next_item_size small => chainable.
        let m = post_residual % next_item_size;
        score -= 15.0 * (1.0 - (m as f64) / (next_item_size.max(1) as f64));
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: neutral-ish base, but prefer it only when
    // open bins are nearly full on average (avoid fragmenting).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming large items
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
    }

    // Late-stream consolidation: favor existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the minimum item size
    // under the nominal regime) are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Tight fit bonus: near-perfect packing gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space pressure grows with stream progression: early on, waste is
    // recoverable; late in the stream, every wasted unit costs a bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; a new bin is penalized via the empty-bin call.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if post residual is just barely too small for the next item, penalize
    // (that residual is likely dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly penalizing outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

