pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress * norm_pr);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 3.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 1.5 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * progress;
    }

    // Coupling with mean residual: prefer bins deviating favorably from mean
    score += 0.5 * (pr - mean_residual) / cap;

    // Slight preference for consolidating into fewer bins
    score += 0.1 * open_bins_count as f64 / (total_items as f64).max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over small moduli
    let pr = post_residual as i64;
    let m3 = pr % 3;
    let m5 = pr % 5;
    let m7 = pr % 7;

    // Dead-space penalty: residuals too small for typical items are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Harmonic "sweet spots": residuals in classes divisible by common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward proportionally
            score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
            // Harmonic bonus if next item exactly consumes the remaining class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize leaving awkward residuals
            score += 3.0 + 0.05 * (post_residual as f64);
            // Small residuals that nothing will ever use again
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing space
    if open_bins_count > 4 {
        score -= 2.0 * (mean_residual - post_residual as f64).abs().min(10.0) / 10.0;
        score += 0.5 * open_bins_count as f64 * 0.1;
    }

    // Mean residual coupling: prefer bins whose residual tracks the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Progress-based modulation: late in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: only prefer a fresh bin when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // Open a new bin if existing fitting bins are few but fragmented
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If lookahead item is large, a fresh bin keeps big space available
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Late stream with many bins: discourage proliferation
        if open_bins_count > 8 && progress > 0.5 {
            score += 10.0;
        }
    }

    // Small harmonic jitter from modulo classes (deterministic tie-breaking)
    score += (m3 as f64) * 0.3 + (m5 as f64) * 0.2 - (m7 as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // another item (below the minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Perfect fit bonus: zero residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.3 * (bin_capacity as f64 - slack);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item would fit this bin now, but placing current item here breaks that.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // If some existing bin fits decently, discourage new bin.
        if fitting_bins_count >= 1 && item_size >= 10 {
            score += 5.0;
        }
    } else {
        // Reward using open bins, scaled by how well residual is exploited.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Mild preference for bins whose residual deviates below the mean
    // (tighter bins get used first, keeping loose bins flexible).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.1 * diff;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
