    let tight_fit_bonus = 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);
    score -= tight_fit_bonus;

    // 2-step lookahead: if the next item fits into post_residual, this is a great chain.
    if next_item_size > 0 && post_residual >= next_item_size {
