    // Penalize creating dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; escalate with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
