            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
            // scarcity-aware slack discount
            score -= 0.9 * slack * scarcity * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            // amplified dead-space quadratic penalty (borrowed from best)
            score += 40.0 * dead_rel * (1.0 - progress);
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            // usable-space discount
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // sub-half residuals are near-dead: extra penalty
            if post_residual > 0 && (post_residual as f64) < 0.5 * next_item_size as f64 {
                let rel = next_item_size as f64 / cap;
                score += (2.4 + 1.2 * rel) * pr;
            } else if post_residual > next_item_size / 2 {
                // just-above-half residuals get a mild early-stream penalty
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Over-tight fit guard: residual barely above next item creates a bad chain
    if next_item_size > 0 && fitting_bins_count > 2 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += 0.8 * over / next_item_size as f64 * 10.0;
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: prefer absorbing into bins already holding similar items
    if progress > 0.75 && post_residual > 0 && post_residual < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            // many open bins late in stream: discourage extra empties
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (good chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward if next item nearly fills the leftover
            let fill = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - fill / bin_capacity as f64);
        } else if next_item_size > bin_residual && next_item_size <= bin_capacity {
            // next item can't fit here anyway; mild neutral
            score += 2.0;
        } else {
            // placing here strands the next item's fit elsewhere
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 0.05 * mean_residual * crowding * (1.0 - progress);

    // Early phase: be conservative, keep bins balanced; late phase: fill greedily
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 - item_size as f64;
        score = new_bin_base;
        if fitting_bins_count > 0 {
            // make new bin slightly worse than a decent existing fit
            score += 12.0 + 3.0 * (fitting_bins_count as f64);
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // chaining potential in a fresh bin
        }
    }

    score
}

