pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post residual (waste), scaled by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth cubic coupling: large post-residuals penalized more later in stream
    score += 20.0 * norm_pr.powi(3) * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr).powi(2) * (0.3 + 0.7 * progress);

    // Lookahead coupling: favor bins whose post-residual matches next item size
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).abs() / cap;
        score += 8.0 * gap * (1.0 - gap);
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid new bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when many bins open relative to mean residual (fragmentation)
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * progress;

    // New-bin candidate: neutral-ish score, slightly penalized early, less late
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * progress + 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
