pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue classes" are more likely to be closed out usefully.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward tight fits strongly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    }

    // Modulo-10 harmonic class: residues near 0 are "dead space" classes
    // (few item sizes in 1..=100 can fill them exactly).
    let class = pr % 10;
    match class {
        0 => score += 8.0,        // exact multiple: hard to reuse
        1 | 9 => score += 4.0,    // awkward residues
        2 | 8 => score += 2.0,
        5 => score += 1.0,        // half-class: medium reusable
        _ => {}
    }

    // Integer-division thresholds: how many "typical" items still fit?
    let fits_small = pr / 10; // smallest item class
    score -= (fits_small.min(5) * 3) as f64;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let next_post = pr - next_item_size;
            // reward chains that leave reusable residues
            score -= (next_post / 10).min(4) as f64 * 2.0;
            if next_post % 10 == 0 && next_post > 0 {
                score += 3.0; // again a dead multiple after chaining
            }
        } else {
            // next item cannot follow in this bin: slight penalty
            score += 5.0;
        }
    }

    // Fraction-of-capacity harmonic: bins with residual near capacity
    // fractions k/4 are natural split points.
    let frac = pr as f64 / cap;
    for k in [0.25f64, 0.5, 0.75] {
        let d = (frac - k).abs();
        if d < 0.03 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Large items keep future flexibility, so a fresh bin is fine for them.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If many bins are open and mean residual is high, prefer reusing.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 {
            score += 10.0 * progress;
        }
    } else {
        // Reuse bonus scaled by how full the bin already is.
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * used_frac;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Tie-break with mean residual alignment: prefer bins near the mean
    // (keeps the residual distribution balanced).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64; // gap of 1 -> +36, gap of 9 -> +4
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is the ideal outcome
    }

    // Reward tight fits: fraction of the residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0 - 2.0 * gap;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: penalize leaving medium dead space.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items, favor
    // filling existing bins; but a new-bin candidate should be attractive when
    // all open residuals are large and fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (1.0 - fill_ratio);

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and open bins are nearly full/fragmented.
    if bin_residual == bin_capacity {
        score += 45.0; // base cost of a fresh bin
        score -= 0.25 * mean_residual; // opening is cheaper when residuals are big/wasted
        if item_size >= 50 && mean_residual < item_size as f64 * 1.2 {
            score -= 50.0; // item barely fits nowhere: open a new bin
        }
        score += 5.0 * progress; // late in the stream, prefer consolidation
    } else {
        // Mild preference for bins whose residual is close to the item.
        let slack = (bin_residual - item_size) as f64;
        score += 0.1 * slack;
    }

    score
}

