    }

    // Late-stream tighter tolerance for slack
    if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack <= 8.0 {
            score -= 1.5 * (8.0 - slack) / 8.0;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            // Extra pressure when open bins are mostly empty regardless of progress
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            // Suppress new-bin opening late when any open bin still fits the item
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 6.0;
            }
            // NEW: suppress new bins mid-stream when a decent fit exists
            if progress > 0.5 && fitting_bins_count >= 2 {
                score += 3.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward exact match of next_item_size into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect follow-up fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize wasted residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // placement leaves them near the open-bin average (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize large post_residual relative to smallest possible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // item is large and no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) >= post_residual;
        let _ = good_fit_exists;
        // base penalty for opening a new bin
        score += 10.0;
        if item_size >= 50 && (bin_residual - item_size) > 40 {
            // large item into fresh bin is fine, slight discount
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin can also host next item: attractive
            score -= 12.0;
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;

    let mut score = post;

    // Reward tight fits (low post_residual relative to capacity).
    score -= 12.0 * (1.0 - post / cap);

    // Nonlinear penalty on leftover dead space (quadratic waste aversion).
    score += (post * post) / (4.0 * cap);

    // Lookahead coupling: reward if the next item can also fit here.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 + 0.25 * (post - nxt);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Prefer filling bins that are already more full than average.
    score += 0.2 * (mean_residual - bin_residual as f64);

    if is_new_bin {
        // Opening a new bin: cheap early (flexibility), expensive late (waste).
        score += 30.0 * progress;
        // Discourage hoarding many open bins when a placement is available.
        score += 2.0 * open_bins_count as f64;
        // A new bin is more attractive for large items (small natural leftover).
        score -= 0.1 * item_size as f64;
    } else {
        // Slight preference for reusing existing bins as the stream progresses.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: penalize leftover waste quadratically (dead space is the enemy)
    let mut score = post * post / cap;

    // Smooth coupling: waste penalty grows with stream progress (be pickier late)
    score *= 1.0 + 1.5 * progress * (1.0 - progress * 0.5);

    // Reward high fill ratio (item almost exactly fills the bin)
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward bins whose residual is close to the next item size (lookahead chaining)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-resort bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // New empty bin candidate: penalize unless current item is large relative to capacity
    // and no tight open fit exists
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / cap).powi(2);
        score = cap * (1.0 - large_item_bonus) + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Mild tie-break: prefer bins with residual near mean (keeps bin population balanced)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smooth shaping
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Dead-space penalty: residuals too small for plausible items
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 4.0 * dead * dead * (1.0 + progress);

    // Lookahead: exact fit for next item is a jackpot; graded otherwise
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 255.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if slack <= 4.0 {
                score -= 14.4 - 3.6 * slack;
            } else if slack <= 20.0 {
                score -= 8.0 - 1.1 * slack;
            } else {
                score -= 2.0 - 0.25 * slack;
            }
            // chain-of-two bonus, strengthened when next item is scarce
            if post_residual >= 2 * next_item_size {
                score -= 3.0 + 2.0 * scarcity;
            }
            // scarcity-aware slack discount
            score -= 0.9 * slack * scarcity * (1.0 - progress);
            // over-just-above-next penalty: bin barely fits next item, leaving a sliver
            if post_residual > next_item_size && post_residual < 2 * next_item_size {
                let over = (post_residual - next_item_size) as f64;
                score += 0.8 * over / next_item_size as f64 * 10.0;
            }
            // exact double fit is a jackpot too
            if post_residual == 2 * next_item_size {
                score -= 1.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            let dead_rel = gap / cap;
            score += 42.0 * dead_rel * (1.0 - progress);
            // strong quadratic dead-space penalty (from best heuristic)
            score += 800.0 * dead_rel * dead_rel * (1.0 - progress);
            let usable = pr / cap;
            score += 14.0 * (1.0 - usable) * (1.0 - progress);
            // near-half-dead residuals: strongly discourage leaving unusable slivers
            if post_residual > 0 && (post_residual as f64) < 0.6 * next_item_size as f64 {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next_item_size as f64));
            }
            // sub-half residuals are near-dead: extra penalty
            if post_residual > 0 && (post_residual as f64) < 0.5 * next_item_size as f64 {
                let rel = next_item_size as f64 / cap;
                score += (2.4 + 1.2 * rel) * pr;
            } else {
                // just-above-half: mild extra penalty early
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }

    // Early stream: favor bins that keep usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            score += 2.5;
        }
    }

    // Late-stream small-residual cleanup: snap up tiny leftovers
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that would strand future items
    if progress > 0.75 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // New-bin candidate: open only when fits are poor or it enables a good chain
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            // if open bins are mostly empty, opening another is wasteful
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            // many open bins late: discourage opening new ones
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

