pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space severity via capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Modulo classes: residuals that are "harmonic" (nice fractions of capacity)
    // are more reusable; penalize them less.
    let harmonic_bonus = match post_residual % 25 {
        0 => 12.0,           // 0, 25, 50, 75, 100: perfect harmonic classes
        _ => 0.0,
    };
    let semi_harmonic = match post_residual % 10 {
        0 => 6.0,
        _ => 0.0,
    };
    score -= harmonic_bonus + semi_harmonic;

    // Dead space: small but nonzero residuals are the worst (unusable wedges)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - frac * 10.0).max(0.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * fill;
            // harmonic chain: post_residual % next_item_size small
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item can't use this bin's leftover; penalize tight fits more
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate logic: opening a new bin is only good early in the stream
    // or when current fit is very poor (large post_residual waste relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // A fresh bin has post_residual == capacity - item_size; compare against
        // typical leftover. Open new bin if current bins would leave bad wedges.
        let poor_fit = (post_residual as f64) > 0.35 * bin_capacity as f64
            && post_residual < bin_residual;
        if poor_fit && progress < 0.9 {
            score -= 15.0;
        } else {
            score += 10.0 + 10.0 * progress; // discourage proliferation late
        }
        let _ = waste_ratio;
    }

    // Integer-division threshold: bucket post_residual into quartiles
    let q = post_residual / (bin_capacity / 4).max(1);
    score += match q {
        0 => 0.0,          // near-perfect fit
        1 => -2.0,         // leaves a quarter: quite reusable
        2 => -4.0,         // leaves half: very reusable
        3 => -1.0,         // three-quarters left: bin barely used, mild penalty
        _ => 0.0,
    };

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.5 * open_bins_count as f64 / (fitting_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
