        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 1.8 * gap;
            if post_residual > 0 && post_residual < next_item_size.min(30) {
                score += 6.0;
            }
            if post_residual > 0 && pr < 0.6 * next {
                score += 3.5 * (1.0 - progress) * (1.0 - pr / (0.6 * next));
            }
            if post_residual > 0 && post_residual > next_item_size / 2 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 180.0;
    }
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 1.5;
    }

    // Early stream: favor bins keeping usable mid-size residuals
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 13.0;
        }
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Distance from mean residual when many bins open
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // Late-stream small-residual cleanup
    if progress > 0.7 && post_residual > 0 && post_residual <= 15 {
        score -= 2.5;
    }

    // Late-stream: snap up residuals that can't fit more items
    if progress > 0.75 && post_residual > 0 && pr < item_size as f64 * 1.5 {
        score -= 3.0;
    }

    // Late-stream tighter tolerance for slack — squeeze residual space hard
    if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack <= 8.0 {
            score -= 1.5 * (8.0 - slack) / 8.0;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 0.3 * cap;
        if fitting_bins_count == 0 || chain_ok {
            score += 2.0;
        } else {
            let pressure = 46.0 + 17.0 * (fitting_bins_count as f64).min(4.0);
            let late = if progress > 0.75 { 28.0 } else { 0.0 };
            score += pressure + late;
            let avg_fill = (cap - mean_residual) / cap.max(1.0);
            if avg_fill < 0.18 && open_bins_count > 4 {
                score += 5.0 * (0.18 - avg_fill) * 10.0;
            }
            if progress > 0.6 && open_bins_count > 6 {
                score += 2.0 * (open_bins_count as f64 / 20.0).min(2.0);
            }
            if next_item_size > 0 && fitting_bins_count > 0 {
                let tightest = post_residual >= next_item_size
                    && (post_residual - next_item_size) as f64 <= 5.0;
                if tightest {
                    score += 40.0;
                }
            }
            if avg_fill < 0.12 && open_bins_count > 6 {
                score += 4.0;
            }
            if progress > 0.85 && fitting_bins_count > 1 {
                score += 6.0;
            }
        }
    }

    // Mild fill tiebreak
    score += 0.06 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * chain_quality;
    }
    // Penalize leaving a residual too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = post_residual as f64 / cap;
        score += 8.0 * dead * dead;
    }

    // Last-chance: strongly prefer the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64) / cap; // large items leave large residuals anyway
        let penalty = 20.0 + 30.0 * (1.0 - poor_fit) + 15.0 * progress;
        // If the best alternative would leave big dead space, allow opening.
        let escape = if next_item_size > 0 && post_residual >= next_item_size { 25.0 } else { 0.0 };
        score += penalty - escape;
    }

    // Mild preference for bins with below-average residual (consolidate emptier bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight penalty for proliferating open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize wasted space quadratically, with progress-dependent weight
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= (1.0 - norm_pr).powi(3) * 0.8;

    // Interaction: large items prefer bins with large residuals (smooth coupling)
    score += fit * norm_pr * (1.0 - progress) * 0.5;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - progress + 0.25);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack = (pr as f64 - nx) / cap;
            score -= (1.0 - slack).powi(2) * 0.6 * (1.0 - progress);
        } else {
            score += 0.3 * progress;
        }
    }

    // Mean residual coupling: prefer bins near the mean (keeps residuals uniform)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 0.4;

    // Mild penalty for spreading across too many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit: perfect or near-perfect packing gets strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Harmonic class of post_residual: dead space in low-value classes is penalized.
    // Class boundaries at multiples of 16 (capacity/6-ish granularity).
    let class = post_residual / 16;
    match class {
        0 => score -= 8.0,            // tiny leftover, still usable
        1 => score += 4.0,            // awkward 16..31 zone
        2 => score += 10.0,           // 32..47 dead-ish zone
        3 => score += 6.0,            // 48..63 can host mid items
        4 => score += 2.0,            // 64..79
        _ => score += 0.0,            // large residual, flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 22.0;
        } else {
            score -= (slack as f64) * 0.15; // mild preference for chains
        }
    }
    // If next item cannot fit here, penalize slightly so bins that chain are preferred.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: if only one bin fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin is expensive unless it enables perfect packing later.
    if bin_residual == bin_capacity {
        // New bin raw residual = capacity - item_size; penalize opening.
        score += 30.0;
        // But if this is early in the stream or many bins already open, new bins are cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If no open bin fits well (large item), allow new bin more readily.
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Avoid opening a new bin when the item would leave a bad class in it.
        let new_class = post_residual / 16;
        if new_class == 2 {
            score += 12.0;
        }
    }

    // Prefer reusing bins with small residuals relative to mean (reduce fragmentation).
    score += ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0) * 0.3;

    // Mild bonus for using already-open bins (fewer total bins).
    if bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Modulo tie-breaker: prefer post_residuals divisible by 4 (cleaner splits).
    if post_residual % 4 == 0 {
        score -= 2.0;
    }

    score
}
